/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170821-9","meetingId":"h29-cm08","date":"2017年8月21日","dateIso":"2017-08-21","committee":"文教委員会","time":"午後 １時００分～午後 ５時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"平成２８年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"平成２８年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"教育施策の成果と明らかになった課題は何か、また、それをどう生かしていくのかということを伺いたいと思います。なぜいけないのか、そういったところもしっかりとやっていってほしいと求めましたが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"本区では平成１８年度から取組んでまいりましたけれども、よい取り組みであるとお答えていただいているところから成果であると考えており。これはどんな理由があってもいけないと答えていますが、引き続き、市民科等を中心としまして指導を行っていきたいと考えております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川の本の貸出冊数は２３区の中で低いのかなと思いますので、読書をすることによって、その辺をぜひ進めてほしいと求めました。そして、なぜいけないかということをぜひ教えていっていただきたいと質問いたしましたので、その点についてもあらためて伺いたいと思います。","respondent":"熊谷指導課長","answer":"いじめにつきましては、なぜいけないかということを、まず絶対に伝えていく。１～６年生も７～９年生も、どちらも８０％以上を超えているということから、そういった場を設けていくようにしていきたいと思います。","id":"exchange-002"},{"speaker":"こんの委員","kind":"質問・要望","question":"児童・生徒アンケートが４回目ということですが、そもそも論をまずお聞きしたいと思うのですが、保護者のほうは平成２３年度から始まっている。","respondent":"熊谷指導課長","answer":"は継続する意味があるのかということもあると思うのですけれども、同じアンケート項目で意図的に実施してきたところがあります。ただ、今後につきましても、過渡期ではありますので、質問内容の見直し等も含めて検討してまいりたいと思います。","id":"exchange-003"},{"speaker":"こんの委員","kind":"確認","question":"地域と学校とご家庭とが、どう子どもの教育環境をつくっていくかというものの参考にしていくと理解したのですが、それでいいかどうか確認いたします。文部科学省は、一貫教育においてどういった点で課題抽出をねらっていたのか、その辺をもう少し教えていただけますか。","respondent":"熊谷指導課長","answer":"これを通じて学校がコミュニティ・スクールを核として、地域、保護者と連携していくための資料であると考えております。そして２点目につきましては、文部科学省から、まずはアンケート調査が課せられたです。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問","question":"品川区独自のこれからの教育、今回でいう教育施策の成果と検証という形で、実施したということで理解しました。選ばれる学校、分析をするというようなアンケートの設問があってもいいのかなというふうに思うのですけれども、いかがか尋ねました。","respondent":"熊谷指導課長、篠田学校計画担当課長","answer":"品川教育検討委員会も開かれていたところですけれども、当時の状況について確認していくということも必要ではないかというふうに思います。今回は平成２８年度、平成２７年度保護者アンケート等を参考にしながら、保護者の意見は非常に大きなファクターになりますことから参考にしつつ審議を進めているところです。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"これだけ様々な設問があるアンケートですから、当然、学事制度審議会のほうでも参考にされているということだと思います。教育要領の改訂にもやはり分析結果を反映していくべきだと思うのですけれども、その辺との関係というか、どういうお考えなのかの説明を求めました。","respondent":"熊谷指導課長","answer":"やはり一番重要なのは、次期品川区立学校教育要領に、こうした保護者や児童・生徒の意見も反映していくことが重要だと考えています。考えがあるのか、そういったものもしっかり踏まえながら、教育課程の編成に活用していくということが重要ではないかというふうに思っております。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"だからこそ、アンケートの設問に、現下の教育課題を分析をしていけるような内容が必要なのかなと思います。では、教員が求めている現状の課題抽出というところをもう少し掘り下げるような設問が必要なのではないかと思うのですが、最後にいかがか尋ねました。","respondent":"熊谷指導課長","answer":"これまで経年でというところに着眼点を置き、アンケートにおいて重視してきたところですけれども、ちょうど変革の時期でもありますので、どういった内容を設問として入れていくかということにつきましては、引き続き検討し、次年度に生かしていきたいと思います。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"読書というのは低学年だけの課題ではないわけですから、また、そういう時間が必要なのではないかと思っているのです。いじめや、そういうことを教育委員会としては本当に大事にしていただきたいなと思いますのでご見解を伺っておきたいと思います。","respondent":"大関教育総合支援センター長","answer":"１点目ですが、学校の現場での対応等ですが、メールあるいはＳＮＳの怖さという部分を小学生段階から取組むようにしております。２点目となりますが、漫画への対応というような部分につきましても、話を聞きたい人はこれを選んでくださいというような対応もしています。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"それをしっかり品川区がやっていっているわけですから、このデータはすごい財産になっていくのかと思いますから継続してほしいと求めました。","respondent":"熊谷指導課長","answer":"今のご質問ですけれども、［２０］の「学校を選択する際、指定校以外を希望申請しましたか。」と［２１］が指定校以外を希望した人のみに問うているかというご質問だと思いますけれども、どのように選びましたかということで質問しています。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"希望申請しないで指定校に入学した方と、希望申請してという方の思いというのは、切り分けて考えないと何のデータにもならないのではないでしょうかと苦言を呈するようですけれども、そこはしっかり切り分けて考えてもらわないとものさしにならないのかなと思うのですが。","respondent":"有馬学務課長","answer":"実際に希望選択した方には、その時点で、アンケートを別途調査をとっております。それはきちんと分析をして、こちらの全体の像と、実際に希望選択した人たちの違いということもあわせて分析をしています。","id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"この部分で何が言いたいかというと、例えば、市民科は、よい学習ですかと聞かれても、市民科がいいか悪いかという判断はなかなか難しいと思うのです。","respondent":"熊谷指導課長","answer":"この［３４］の質問については、私どもでも課題と認識しております。こちらの質問については補足で説明を入れるですとか、今後も引き続き学校に対して、それについては指導していきたいと考えています。","id":"exchange-011"},{"speaker":"渡部委員","kind":"意見","question":"どういう聞き方がいいかというのは非常に難しいですけれども、しっかり様々な分析と検討をしていただいて使っていただければいいなと思います。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問・要望","question":"確認なのですけれども、児童・生徒に対しては３年生から上の学年になりますが、１・２年生の部分を除いた理由を確認で教えてほしいと求めました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"１・２年生については、これは教員がきちんと具体的にかみくだいて説明をしていかないと答えが難しいのではないかということで、３年生以上という調査にして行ってきたところであります。なかなか塾、習い事、スポーツ活動などとバッティングすることもございまして現状として課題に考えているところです。","id":"exchange-013"},{"speaker":"松永委員","kind":"意見","question":"それもなかなか活用されていたのかどうかもあれなのですが、今後検討課題の１つだと考えていますので、しっかりと取組んでいただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"７年生が不登校になったり、７年生に自己有用感というか、自己肯定感を身につけてもらうには具体的にどういうふうにお考えなのかと思いました。そして３つ目は英語学習についてで、好きですかというところで、やはり７・８・９年生で好きではないという子が増えている。","respondent":"熊谷指導課長","answer":"７年生、少し自分の長所よりも短所のほうを自分の中で大きく捉えてしまうというような発達段階もあるのではないかというふうには思っています。９０％近くいるのですが、その部分も含めて、英語科の授業のあり方についても引き続き検討してまいりたいと考えております。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その学校で中身を細かく把握していただいて、学校ごとそれぞれ特色があると思いますので、対策を打っていっていただきたいというふうに思います。７年生の様々な部分が中学校への適応に関連してくると思いますので、ぜひ今後に生かしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"先ほどちょっと答弁をいただけなかったような気がしたので確認したいのが漫画、雑誌、読書のところで除くとなっていたその点について、どういうことなのかともう１つが、学校図書館の司書の配置は、今、どの程度になっていたのか、改めて、この際、確認したいと思って。","respondent":"熊谷指導課長、有馬学務課長、横山品川図書館長","answer":"漫画や雑誌を除くといったときに、もしかすると子どもの捉え方として、歴史漫画も除いてしまったりしている部分があるかと思います。主幹教諭などが研修を受けまして、学校図書館司書というような資格を取るというか、そういった研修を受けた主幹教諭等がその職務に当たっているです。学校図書館に関しましては、区立図書館からの支援が入っておりまして、学校図書館の運営支援要員を派遣しております。","id":"exchange-017"},{"speaker":"南委員","kind":"確認","question":"最後のところの確認なのですけれども、そういう方が配置されている理解になるのですか。あまりよくわからなかったです。","respondent":"熊谷指導課長","answer":"司書教諭いわゆる学校図書館司書教諭ですけれども、主幹教諭などをもって充てる形となり、学校図書館法において１２学級以上は置かねばならないという定めがありますので、必ず配置の段階で司書教諭がいないという状況がないように、人事面でも配慮しています。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、１２学級以上あるというのは、ちょっとごめんなさい。当区に何校ぐらいあるのかを教えていただきたいのと、読みたい本、司書として現状どういうふうにやるのかということを教えてほしいと求めました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"初めに、後半の部分を私からお答えいたします。毎月１回、それから校務分掌として図書館を担当している教員を必ず各学校１名、もっと工夫点がないのかなどについて話し合いを毎月行っております。学校図書館司書教諭ですけれども、これは昨年度、平成２８年度のものですが、３４校に配置しております。この１２学級以上というところですが、これは特別支援学級も１学級として数えますので、配置している学校数が多くなってあります。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"日常的に授業との関係、子どもの読みたい本や資料を提供してもらいたいなど、そういう関係はどうなっているのか聞いたのですけれども、もう一度ご答弁をお願いします。","respondent":"大関教育総合支援センター長","answer":"どんな本を増やしたらいいですかということも各教員にアンケートのような形で担当教員が取りまとめて図書館スタッフと相談をしながら管理職のほうに必要な購入図書について、案といいますか、推薦をいただいたりしているような形です。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"配置されているのが３４校ということで、予想よりは多いのだなというふうに認識したのですが、やはり全校配置が必要だと思うのです。図書に触れる、そういう点では、その方向性についてはどういうふうに考えているかを伺って終わりにしたいと思います。","respondent":"横山品川図書館長","answer":"先ほどご案内しましたけれども、学校に図書館支援スタッフを配置しておりまして、実質上、全校で司書の資格を持っているものが主に活動しているような状況になってあります。","id":"exchange-021"}]},{"id":"topic-02","title":"平成３０年度～３１年度品川区立小学校・義務教育学校（前期課程）使用教科用図書の採択","agenda":"平成３０年度～３１年度品川区立小学校・義務教育学校（前期課程）使用教科用図書の採択","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"経過措置で２年、３年、４年のスパンで合わせていくのかひとつお教えほしいと求めました。そして、来年度以降、どういうふうに扱っていくのかということをあわせていま一度教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"その際に改めて道徳の教科書についても採択を行いますので、そこでずれは解消される見込みです。現在ある市民科教科書だけでなく、道徳の教科書も併用だという前提で改訂に当たっていきたいと考えております。","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"今までの教育の中でもしっかりといわゆる道徳という部分に関しましては品川の教育でなさっていたので承知しております。しっかりと今以上と言いましょうか、今までどおりと言いましょうか、生かして進めていただければということはしっかり要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"私の小さい子どものころの通信簿では、先生の意見を書く欄がある、そういうところに記載するということになるということなのですか。他の人の関係と違うような、そういう危惧があるかなと考えているのですが、その点についてどうなのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"今後、表記につきましても、原則的には従来どおり文章表記で担任が表記をしてまいります。次年度４月以降、現場の混乱のないように進めていく予定です。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"だからこそちょっと心配かなと思ったりしているので質問をさせていただいているのですけれども、例えば、そんなふうになるのですか。４０人近い子どもたちを見ていて、そんなことも心配するので、教育委員会としてはどうやって見ているのか聞いておきたいと思います。","respondent":"大関教育総合支援センター長","answer":"ステップ１からステップ５まで段階を経て、実際に自分でどのように考えるか、そしてそれを実践をしてみてどうであったのか。本人はどのように考えて、そしてご家庭でもその部分を理解していただいて、話し合っていただくという部分が大切かと考えます。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"それだけ先生方のご苦労、配慮というか、負担増につながるのではないかと思っています。道徳的な面でどうこうと子どもを判断するということよりも、きちんと指導を適切にしていくという、意見として表明をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"通知表に文章で書くということなのですが、これは進学の際とかの内申点とかにも影響してくるものなのかを伺いたいと思います。参加者が約３０人ぐらいいたということでしたのですが、そういった配慮をぜひお願いしたいと思うのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長、品川庶務課長","answer":"１点目の教科書採択の際の採択理由ですが、そういった記載は子どもの考えを縛ってしまう可能性があるので、受けとめております。教育委員会室、大体これぐらいの部屋と同じぐらいの部屋の規模でやっておりますので、基本的にはマイクは必要なかったかとは考えておりました。入学者選考の内申の点数の部分ですが、文章表記の内容を点数化することはできませんので、国語や数学などのように点数として載せる欄はございません。","id":"exchange-027"}]},{"id":"topic-03","title":"難聴通級指導学級（中学校・義務教育学校後期課程）の新規開設","agenda":"難聴通級指導学級（中学校・義務教育学校後期課程）の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この難聴の通級指導学級ですか、授業内容がどういったことをやられているのか、改めて説明してほしいと求めました。それから、これは区内では初めてのものになるのかというところもお聞きしたいと思います。","respondent":"大関教育総合支援センター長","answer":"週１回程度、普段は通常の学級の中で十分学んでいる子どもですので、必要な内容は一人ひとり個の実態に応じて自立活動を行っております。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"マンツーマンでやっているような形になるのでしょうか。そういうこともぜひ教えていただきたいのと、あと、そういったところをどうされていらっしゃるのかも伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"例えば、そのために、例えばオージオメーター等の設備が整えられている台場小学校の聴覚防音室の中で特別に１対１で対応したりなどもしています。現在、利用者は区内全部合わせても５名しかおりませんので、現実的には１対１で対応ができている状態です。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"ありがとうございました。そうすると、今後、難聴通級学級を全校にというか、区内全域に広げていく考えなのか今後の見通しを伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"区内だけでなく都内全部でも、例えば中学校区部では、まだ８つしかないのが実態です。実際に対象者も小学生１年生から６年生まで合わせて５名である現実からも考えますと、各校に同じような学級を設置するのは。","id":"exchange-030"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"先ほどのお話を聞いたら、１名しかいないのに小学校で五、六名だとかと聞いたのですけれども、３名以上また別にいらっしゃるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"今、台場小学校の通級を利用しているのが、２年生、３年生、４年生、６年生合わせて５名です。２年生が１名、３年生が２名、４年生が１名、６年生が１名の内訳です。","id":"exchange-031"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"プライバシーにもかかわりますが、もしも可能でしたら、基礎疾患や、聴覚障害が出た理由などをご説明していただけるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"個々の内容につきましては、この場ではご説明ができませんが、一人ひとりの就学相談を経て、実際に聞こえの部分から難聴の通級の対象者が適切であるとなっています。","id":"exchange-032"}]},{"id":"topic-04","title":"（仮称）品川区子ども・若者計画（素案）","agenda":"（仮称）品川区子ども・若者計画（素案）","exchanges":[{"speaker":"南委員","kind":"質問","question":"質疑をしたいものが幾つかあるのですけれども、２時間経過したので休憩後はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"原因、５行のところで、もう少しここについては品川区としてどういうふうに分析を深めていらっしゃるのかを具体的に伺いたいというのが１つあります。","respondent":"高山子ども育成課長","answer":"専門委員会を開く中でも、言葉の表現はそれぞれ違いますけれども、同じような認識であったかというふうに考えております。ですので、お集まりいただく方々にとってはなじみ深い言葉ではなかったので、検討委員会という表現は会議の名称上使わせていただいた上で。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"ですので、こういう計画をつくるに当たって実態調査は欠かせない条件だと思うのです。パブコメも９月に行うという話なのですけれども、実態調査をするべきだと思うのですけれども、その点についての見解はどうか尋ねました。","respondent":"高山子ども育成課長","answer":"品川区ライフスタイルに関するアンケート調査を実施しておりまして、この調査結果につきましては、本年５月の文教委員会でご報告をしています。計画冊子の中に、そういったものから見えてくるものも、この計画を策定する過程で検討委員会の中の検討委員の方々とも共有しています。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"やはりきちんとした現実的な状況が反映できるような、改めて実態調査をぜひしていただきたいということを強く要望をしておきたいと思っています。","respondent":"高山子ども育成課長","answer":"例えば、基本方針１には、「すべての子ども・若者の健やかな成長と社会的自立の支援」という１つ目の基本方針があるのですが。言葉としては３行ではあるのですが、この背景には、そういったものの新しい課題認識と理念の共有といったものをまず最初としたいと考えています。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"区の、そこに目指していくということは大事だと思いますので、ぜひ検討していただいてつけていただけるように要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"こんの委員","kind":"質問・要望","question":"特に第１番目の「保健、具体的にどういうふうにしようとイメージしているのか、そこを２点目に教えてほしいと求めました。もしこの総合的に緻密に連携をしという体制がどういうふうに具体的にされていくものなのか、イメージを教えていただきたいのが２点目です。","respondent":"高山子ども育成課長","answer":"早期の支援という意味で言えば、いわゆる政府が言うようなほど楽観視できるようなものではないというふうな認識に立っております。そういう方々との連携が行政だけでは実現できないような様々な支援策をつくり上げていく。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問・要望","question":"４０歳以上の方々への、楽観視していないというお考えも伺いましたので、この計画を推進してほしいと求めました。そうでないとしたら、そうした体制も必要ではないかと思うのですけれども、いかがか尋ねました。","respondent":"高山子ども育成課長","answer":"２点目の個別の支援という形に踏み込んで、相互の連携を密にするという中におきましては、従来どおり進めてまいりたいと考えております。この基本方針の３本目の柱となりますが、自治会の支援、自治会が地域支援をしてくださることも大きな品川区において支えでもありますし。","id":"exchange-039"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこはそこの会議体としては、ぜひ今後も活動を強めていただきたいと考えています。自治会の皆さんの地域資源を協働という形で品川区もこの子ども・若者計画を実行していただきたいと、最後に、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それから、当事者の子どもや若者の方々のご意見を伺うというのは、そこのところをどういったことを想定しているのでしょうか。それからもう１つは、そういった計画の大もとのところを協力しながらやられたのかどうかという質問です。","respondent":"高山子ども育成課長","answer":"よりシンプルに、より効率的に進めていくような会議体については、引き続いて検討してまいりたいと考えております。今後、手法については検討してまいりたいと考えております。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"の２つは、こういう計画があるのですがというような形で周知していっていただき、意見を聴く場を設けてほしいと求めました。様々な部署でそういった意見を聞く機会をつくるということを進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"渡部委員","kind":"質問","question":"ですから、子ども全般の物事に関して、いわゆる親支援みたいなものと本人支援みたいなものをこの２つの計画に分けていくのか。聞き方も下手なのですけれども、何かむず痒さが解消しないというところがあるのですが、いかがか尋ねました。","respondent":"高山子ども育成課長","answer":"そういった意味での地域のかかわり、絡みというのは、決して小さなものではないというふうに考えているところです。","id":"exchange-043"},{"speaker":"渡部委員","kind":"意見","question":"ある程度、若者に対する定義が３０歳とかとなっていて、それぞれ諸問題を抱えている方々で、この中で何とか青年とありましたねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"渡部委員","kind":"意見","question":"問題を抱えた方々で４０歳ぐらいまでおられて、やはり包括的なといいましょうか、様々な分野の方々での議論も必要なのかなと思いました。会議体を進めていったほうが、様々な手段、方法などが出てくるのかなというふうに個人的にはご答弁を聞いていて思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"この計画は５年間の計画ですけれども、この計画に追加していくのかというところを改めて青少年問題協議会でも聞いたのですが、伺いたいと思います。それとあと、いかがでしょうかということをお伺いしたいと思います。","respondent":"高山子ども育成課長","answer":"それこそ年次の青少年問題協議会の場における実施状況の把握といった点検の中に盛り込むことは可能だと考えております。会議体の機能でありますとか、委員の識見などを最大限活用いたしまして、その会議体を活用を視野に協議会の設置について引き続き検討してまいります。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"計画の見直しについては、５年以降の見直しということだったのかどうかを確認したかったので、改めて質問させていただきました。センターをつくって、そこに行けば支援が受けられるといった場所の設置も必要だと思うのですけれどもいかがか尋ねました。","respondent":"高山子ども育成課長","answer":"先ほど、総合相談の窓口であったり、そういった拠点のありようについては検討してまいりたいと考えております。その上で既存の東京都の施設との連携も含めて検討してまいります。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"都内に１カ所あるということですけれども、品川の若者は行きやすいと思いますので、ぜひやっていってほしいと求めました。推進体制の整備のところで、調査研究を行っていく記載もありますので、こういったところもしっかりと進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-05","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"南委員","kind":"質問","question":"あるいは、この程度だったらいいだろうというふうに思っておられるのか、その辺についての認識を伺いたいというのが認可保育園についてです。","respondent":"大澤待機児童対策担当課長","answer":"保育園が近隣の方にとって迷惑施設という認識がされてしまっている部分もございまして、説明会や個別訪問のときに、なるべく音が。例えば保護者の方からクレームがあったりですとか、けが等の事故があったときには、計画以外の指導検査も実施しているというような状況です。","id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"東京都の１２.６％というこの数字は、品川区はどのくらいの数字か、具体的な数字を教えていただきたいと思うのです。他は何をしているのだと思うわけで、きちんとした数字を委員会で報告をしてほしいと求めましたので、よろしくお願いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"先に２点目の指導検査等につきましては、今、手元に数字がないので、また後日改めてということでよろしいでしょうか。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"そういう努力はしてほしいと求めましたし、園庭を確保するための財政的な支援、そういう方向性についてはどうなのでしょうか。ぜひ区として、あと、園庭の確保についての支援を改めてお願いをしたいと思いますので財政的支援をするかどうかお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"こんの委員","kind":"質問・要望","question":"今のお話を伺って、私は課長のご説明、よくよく理解できました。それは非常に難しいところなので、この公園の現状も変わるのではないかと思うのですが、まずはこうした声は事業者から入っていますか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"私立園長会等で公園の使い方については何度かお話をしたことがありますので、ときどき重なってしまうという状況は理解しております。既存園同士の調整等は、今、できていないということが現状だと考えております。","id":"exchange-052"},{"speaker":"こんの委員","kind":"質問","question":"やっと晴れて公園に行ったら、もう公園に人が集中して遊べない、何園も来ていて、公園ですから一般の方々も使っていらっしゃる。非常に混雑して、年長児などは思い切り走れないというような声も聞いておりますので、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"今すぐにこのようにするといいという案はないのですが、確かに調整の必要を感じておりますので、今後、研究してまいりたいと思います。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"先に計画変更のほうを伺いたいのですけれども、サクセスアカデミーがライクアカデミーになったということで、ただの名称変更で、運営とかには関係はしてこないのかぜひ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"今回、３歳以上も受け入れるということで、そういったところへの配慮や支援はされているのか伺いたいと思います。この新規園開設に向けて、人材確保についてはどうなっていらっしゃるのか伺いたいと思うのですけれども、。","respondent":"大澤待機児童対策担当課長","answer":"そちらのライクのブランドに統一するため、８月１日に変更することが、７月２８日の株主総会で定款変更が承認されたと聞いております。会社の経営上の方針として、平成３０年の開設につきましては、都内で３カ所すべてを第一住宅とやるということで伺っております。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"人材確保については今後やっていくのでしょうけれども、大変だと受けとめさせてほしいと求めましたけれども、引き続き、支援も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問","question":"いつ頃どういう形でやるかということを改めて計画が欲しいなと思ったのです。正副のところで検討してほしいと求めました。","respondent":"つる委員長","answer":"正副で検討します。","id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"そういう認識を教育委員会として持っておられるのか、その辺を大くくりの質問なのですけれども、伺いたいというのが１つです。今のこういう求められる教育内容から見て、３０分から１時間でいいのかなと、本当に身につくのかということを私はすごく心配するのです。","respondent":"熊谷指導課長","answer":"１５分掛ける３回、週に３回帯でとるという形を品川区学校教育要領では設けていこうというふうに、検討しているところです。ですので、大きく変わったというよりは、整理をしたというほうが正しいのではないかと考えます。","id":"exchange-058"},{"speaker":"南委員","kind":"質問","question":"改めて伺いたいと思っているのですけれども、そこを改善させていかないと、主体的な学びにいかないと思うのです。国のことですから、別にここで論争してもしようがないので、指摘にとどめておきたいと思います。","respondent":"熊谷指導課長","answer":"やはりもっとさらに進めて、もっと学びたい、もっと難しいことに挑戦したいという部分も必要ではないかと思っています。ただ、そこを乗り越えることで楽しい、また主体的に学習に取組む態度につなげていけるように指導していきたいと思っています。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"そういう得意となるものを１つでもいいから持っていただいて、できる喜び、そこを体得してもらいたいと思っているのです。だから、そういう捉え方はしていただいているとは思うのですけれども、ぜひそこのところは大事にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問","question":"教員の方々が抱えている授業のあり方、子どもへの楽しい、わかりやすい授業をどう展開していくのかというサポートが必要ではないかと思います。されているのであれば、どんなことをされているのかの説明を求めました。","respondent":"熊谷指導課長","answer":"様々な部分がありますので、そういったときに対応できるように、土曜授業を今後も続けていくことを考えています。それから２点目なのですけれども、１つは、いわゆる主体的・対話的で深い学びを実施してきたところだと思っています。","id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"第２と第４は増えるかどうかというところは、それとも第２と第４も土曜授業を復活させるのかというところが、もう一度お聞きしたいと思います。各学校、校長先生がいわゆる学校経営として教員の方々へのサポートをするため、授業などを見ていらっしゃるのか尋ねました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"それから後段ですけれども、先にまず私のほうからご説明しますと、実際に校長、副校長は、毎日授業観察を行っています。特別支援教室もスタートしましたので、そちらのほうの活用も含めて各方面で工夫をして進めているところです。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問・要望","question":"見回ってほしい反面、もう１つ、それから先生方が持っている理念的なものがあるのでぶつかるという話を聞いたことがあります。そうしたところのフォローをしっかりしていただいていると思いますけれども、一層その辺についてもサポートを要望させていただきまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問・要望","question":"そうではない部分で、何かが理由でそのような大きな変化があったかどうか、まず１つ教えていただきたい。ですから、連絡をとろうとしたときには、どうしても夜の時間帯を利用しなければならないわけで、先生方に、早く帰れと言っても帰れないわけです。","respondent":"熊谷指導課長","answer":"２点目の働き方ということですけれども、保護者の方も、お電話をされたりということもあろうかと思います。様々あろうかと思いますけれども、既に７月からＰＴを立ち上げて、検討を進めてきているところです。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問・要望","question":"どうすればいいのだろうというような対応策を持っているわけではないすが、ただ、それはまた別問題なのでわからないのです。教育は難しい問題を抱えていると常に思いながらですけれども、またみんなでいい意見があれば、話していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"高橋（し）委員","kind":"質問","question":"移行期が３５時間になるということで、それともこの１５時間分を、その部分をどういうふうに対応するのでしょうか。特に５・６年生です、新学習指導要領との関係で、品川の学校教育がどのようになるのかというところを方向性で結構ですのでお願いします。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"ところが、本区の場合は、始まってすぐから給食を開始してということで、３５週計算をしているということ。場面の中で道徳的な価値項目について扱う場面の中で、教材の１つとして、今後は道徳の教科書が活用できるようになっていくと考えております。この５０時間の生み出し方についてですけれども、現在、ステップアップ学習を行っている時間を英語科の授業として移行して行うことにしています。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"学び方も規定したり、この資質・能力が経済界が求める人材づくりのためのものではないかという危惧があるわけなのですけれども、伺いたいと思います。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"子どもたちのよりよい学びを行っていくためには、こうした主体的・対話的で深い学びの授業の構成が必要になってくるというふうに考えています。しっかりとそこを行ってほしいという国の考えで出てきたわけでして、その中で道徳の内容を当然これまでどおり扱ってまいります。あくまでもこれは市民科の授業の中で、オリンピック・パラリンピックの開催を活用して、障害者理解をしっかり行っていきたいという授業です。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"少人数学級をさらに進めて、ぜひそういったことも進めていってほしいと求めましたけれども、いかがでしょうか。もう１つ、部活動で銃剣道が入ったというお話があると思うのですけれども、品川ではやっていくという検討をされているのか伺いたいと思います。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"ですので、これをこうしなければならないというのではなくて、それこそ教員の腕の見せどころがここになってくると思っています。剣道連盟の協力を得る中で行っております。総合的に各学校の教育課程を校長が編成する際に考えてまいりますが、今のところ、大きく何か新たなという相談は受けておりません。","id":"exchange-068"},{"speaker":"松永委員","kind":"確認","question":"１点だけ確認なのですけれども、この主な改善事項の中で、部活動のあり方の見直しというのは、教員の負担増のことを見直すということなのか、それとも今までの部活動のあり方を全面的に何時から何時までとか、そういう時間数を決めて変えていくのか。","respondent":"熊谷指導課長","answer":"それを社会教育関係の団体、地域、大学など様々なところと連携しながら部活動のあり方を考えていきましょうということです。１つの学校だけで行うのか、そういったことも今後検討していきますということで、今後検討を行っていくかと思います。","id":"exchange-069"},{"speaker":"松永委員","kind":"質問","question":"では、先ほどの教員の働き方改革を８月にＰＴを立ち上げたというのは、７月でしたか。それとはまた別のことになりますか尋ねました。","respondent":"熊谷指導課長","answer":"今後、そうした部活動の顧問のあり方ですとか、そういったことも関連づけて検討していきたいと思っています。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203794?Template=document&Id=4920#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":87226,"voices":191}},{"id":"h29-20170821-5","meetingId":"h29-cm08","date":"2017年8月21日","dateIso":"2017-08-21","committee":"総務委員会","time":"午後１時００分～午後 ２時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"「」を聴取いたします。 まず、(1)の品川区長期基本計画の評価・検証","agenda":"「」を聴取いたします。 まず、(1)の品川区長期基本計画の評価・検証","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"区内の団体等のインタビューというのは、どういった団体が対象なのか。教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"郵送のアンケートなのですけれども、今月初めに発送いたしまして、８月２５日までにご投函いただきたいとお知らせをしています。関係ある団体のところにお声がけをしながら、１０団体ぐらいは実施したいと思ってありますが、これから選定作業に入るところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"検証の視点をどこに置いていくのかということを１点、お伺いしたいのと、パブリックコメントを行っています。この点はいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"これから細かく検討、さまざまな活動といいますか、ご活躍をされている方のご意見をお伺いしていきたいと思ってあります。前回の第４次の総合実施計画から、評価、検証をしていきたいと思ってあります。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一方では、声が聞こえているのか、区が吸い上げられなくて、届かない部分の声も、ぜひくみ上げていってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"人の入れかえなのでしょうか。これからも、１０年というスパンで計画を立てていくおつもりなのか尋ねました。","respondent":"柏原企画調整課長","answer":"今後の新しい計画を考えていくときに、果たしてこの１０年というのがいいのかどうかというのは、確かに議論は必要であろうと思ってあります。１０年というのは、どういった変化があったかというのも見えてまいりますので、議論をしながら考えていきたいと考えています。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"どうぞ、そして、品川区の住民を支えていくような動きをしてほしいと求めました。高齢者関係もそうですが、大変なことも多々あると思いますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問","question":"区内の在住者等に対するアンケート調査等は行っていて、また、各種団体へのアンケートもやっているのですが、区内企業のご意見というのはどこに入ってくるのかを１点だけの説明を求めました。","respondent":"柏原企画調整課長","answer":"インタビューをどういう形でやるか、今は検討中ですけれども、その後ろの段階で企業の方々の話を聞いていきたいと思っています。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"区内団体というのはまた別にインタビューされるようなので、それから、３,０００人の中にこの方たちも入っているのかどうかを教えてください。その３点をお伺いします。","respondent":"柏原企画調整課長","answer":"今の予定では、４割ぐらいの回収率を想定していますけれども、３,０００人で４割ぐらいの回答がとれれば有効であると。それから、パブリックコメントにつきましては、今後の計画をつくっていく中で、その手順の中でパブリックコメントを行っていく予定です。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"例えば人口とか標準的な職員数とか、わかりやすく標準区というものがどういうものなのかを教えていただきたいのが１点です。２ページ目は単純なのですが、精算分は、さっき過年度分の精算と言われていましたが、どういう中身があるのか教えてほしいと求めました。","respondent":"秋山財政課長","answer":"標準区の小学校が３４校なので、その辺の微調整はありますけれども、その程度であると考えていただいてよろしいかと思います。平成２７年度の調整分ということで、８１億円が差し引かれるものです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に経常経費とか投資的経費のバランスとか、事業の中身などに対して、評価が何かあったら教えていただきたいのが１点です。対策とか、意見をどう述べているのかとか、その辺があったらの説明を求めました。","respondent":"秋山財政課長","answer":"平成３１年度に消費税が１０％になった場合に、平準化した場合に１,０００億円程度ということで、影響が大きくなっていくだろうと考えています。都市部から地方部へという形で表れておりますので、今後とも、その影響は大きくなっていくのだろうということを想像しています。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"既に特別区長会などでも、意見をたくさん述べていると思うのですが、頑張ってほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"意見","question":"２番目の街角メッセージなどは既にケーブルテレビで見られると思うのですが、関心を高めてほしいし、お考えを聞かせてくださいとの意見を述べました。","respondent":"木村報道・プロモーション担当課長","answer":"こういう事業を実施しております、実施いたしましたという形のリンクを貼る、ご覧いただけるようにするという形。今、こういう動画を制作して発表していますという形で、区民の方がご覧いただきやすい形を考えてあります。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺を教えていただきたいのと、１のところの辞退をされた理由をお聞かせいただきたいのが１点です。どういう方法なのか教えてほしいのが１点と、区内のうち、そのうち工事が完了しているものはどのくらいあるのかを教えていただきたい。","respondent":"立川経理課長","answer":"勝島の１丁目、２丁目ということでございまして、勝島といった地域が対象となっています。残るところは、山手通りの道路を新しくしておりますので、あの隣接する部分がまだ未実施だと聞いてあります。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうやって接続部とか大事な部分を工事するのかというイメージが全然浮かばないので、わかったらでいいので、教えてください。上下水の工事の必要な箇所の何％ぐらいが終わっているのか、概略でいいので、教えていただきたい。","respondent":"立川経理課長","answer":"全体で何％終わっているかということにつきましては、所管から情報を取り寄せておりませんので、ここでは答えることができません。それより詳しいことは、まだ聞いておりません。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけです。７ページの３と４の会社の辞退の理由の説明を求めました。","respondent":"立川経理課長","answer":"こちらは、先ほどもお話しした配置技術者の調整がつかなかったということと、あと、事業者側の積算と予定価格が違ったです。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"辞退の理由というのは、どこかできちんと書面とかで出されるのかということを教えていただきたいのが１点です。十分、気をつけてやっていただきたいと思っていますが、いかがか尋ねました。","respondent":"立川経理課長、小林施設整備課長","answer":"辞退理由ですが、これは書面で出していただいてあります。そういうことをやって、あとは定例会議を開いて、意見を聞いて進めております。","id":"exchange-016"}]},{"id":"topic-02","title":"荏原南公園改修工事請負契約","agenda":"荏原南公園改修工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろ思い描いているものと、実際に設置をされるものがどういうものなのかというところの確認で、どのようにされているのかというのが１点です。位置はわかったのですけれども、どういったものなのか、わかったら教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろな意味で意見が出たほうがいいと思うので、ぜひ、担当においては、より概要などを把握して出ていただきたい。そういった意味では、中身もよく伝わって、契約というところに持っていきたいと思っていますので、これからも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"工事内容には、透水性ブロック舗装が１２８平方メートルとあるのですが、平面図で見つからないので、教えてください。こうなっているのだと思うのですけれども、もし、その趣旨がわかったらの説明を求めました。","respondent":"立川経理課長","answer":"実際、どの部分であるのかというのは、この図だけではわかりません。これは所管課で作成したものですので、その辺については後ほど確認しまして、お伝えしたいと思います。","id":"exchange-019"}]},{"id":"topic-03","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"だから、２１人の方ということなのかが１つです。よく理解できなかったので、債権の放棄に至るプロセスは、どういったチェックがされて放棄に至るのかの説明を求めました。","respondent":"齋藤会計管理者","answer":"金融機関にお勤めの方、４人の委員の方で債権管理審議会というものを構成して、附属機関を設けております。１件１件、こういったものを債権放棄するということで、書類あるいは口頭でご説明しています。","id":"exchange-020"},{"speaker":"吉田委員","kind":"確認","question":"今ご説明いただいた、そういう作業、措置をするのに必要なのが、この条例で定められた１年間と理解してよろしいのでしょうか。だから、その１年間のそれらが全部終わった後、債権の放棄という手順でいいのか、確認させてください。","respondent":"齋藤会計管理者","answer":"今回お示しした奨学金の場合のように、裁判所で免責してもらうことで債権放棄をさせる決定する場合もあります。債権回収の見込みがないということがわかって、資力の回復には見込みがない、あるいは債権回収が見込めない場合。","id":"exchange-021"},{"speaker":"吉田委員","kind":"確認","question":"それが相当の期間ということで、品川区の場合は条例で１年と定めているという理解でいいのか。もう一回、確認させてください。","respondent":"齋藤会計管理者","answer":"条例上は相当の期間という言い方をしておりまして、実務上、１年を見てあります。場合によっては、それを縮めることもあれば、長引くこともあると考えております。","id":"exchange-022"}]},{"id":"topic-04","title":"衆議院小選挙区選出議員の選挙区の改定","agenda":"衆議院小選挙区選出議員の選挙区の改定","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"おおよそどのくらいいらっしゃるのか教えてほしいのと、例えば第３区がどうなって、第７区がどう改善されるのか。実際に、何をどう示されて、周知をされるのかの説明を求めました。","respondent":"安井選挙管理委員会事務局長","answer":"地元の町会に説明をしなければいけないので、大崎第１地区の町会連合会に説明をし、特に大崎第１地区だけの回覧でお示しをしていこうと思っています。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"意見","question":"あまり品川区では経験していないので、多分、大変なことだとは思うのです。地元のお声をたくさん聞いていただいて、よりよい方法をとっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"意見","question":"その点に関しては、今回のこの区割り変更後、第３区部分と第７区部分の選出の国会議員を２名お呼びになるのかどうか。そういった部分に関してお知らせくださいとの意見を述べました。","respondent":"米田総務課長","answer":"今後、そういう形で選挙が行われて、選出になった場合については、全区行事につきましては、当然、２選挙区の衆議院議員が関わるという形になりますので、それ相応の対応を図っていくことになります。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、選挙はいつになるかわからないのですが、お金がかかっても、区から個別に郵送をして、きちんと周知していただくことは大切ではないか。本当に職員の方も大変だと思いますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これは年に何回かはテストしているのでしょうか。その辺、どうなのか、わかる範囲での説明を求めました。","respondent":"米田総務課長","answer":"定期的な訓練ですけれども、防災課所管になりますけれども、年に１回程度はきちんとやっておりまして、今のところ支障はないと聞いております。そういう設備の確認というのは、常時、行ってあります。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"意見","question":"１つ思い出したのですが、前回の委員会のときに、東京都議会議員選挙の投票率の中身で、特に１８歳選挙権になって、若者の投票状況がどうなっているのかを知りたいという投げかけをさせていただいて、その時はまだ出ていないということだったのですが、いつぐらいに出てとの意見を述べました。","respondent":"安井選挙管理委員会事務局長","answer":"今、データをほかのものと合わせて集計している段階です。なるべく早く、次回ぐらいに出せればいいと考えています。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2084#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":27359,"voices":98}},{"id":"h29-20170822-14","meetingId":"h29-cm08","date":"2017年8月22日","dateIso":"2017-08-22","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ４時４０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/172349?Template=document&Id=6034#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":1037,"voices":5}},{"id":"h29-20170823-18","meetingId":"h29-cm08","date":"2017年8月23日","dateIso":"2017-08-23","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時４７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"自転車専用レーンにする場合には、駐停車の問題にも対応が必要ではないかと思うのですけれども、その点についてどういう状況か伺いたいと思います。","respondent":"多並道路課長","answer":"今後につきましても、そういう観点からも警視庁とよく連携しながら整備後の駐車対策についても進めていきたいというのが今の考え方です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言だけ意見を述べますけれども、安全な自転車専用レーンにしていただきたいと、またこの駐停車の問題も徹底をしてほしいと求めました。エスコートゾーンについて、東京都がというお話ですけれども、しっかりと整備が進むようによろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問","question":"警視庁を中心にして今後どうしていくかというのも大切なことであって、ただ、要するに反則金を取るのが警視庁の役目というのでしょうか。１車線が生きるわけですから、恐らくそういう現象が起きてくるので、やはりもともと行こうとしているところ。","respondent":"中村都市計画課長、小川オリンピック・パラリンピック準備課長","answer":"これは港湾局のほうも既に数年以上前から認識をしているところでございまして、今後港湾の整備の中でこの駐車場の整備というのが掲げられております。引き続きそれがしっかりとなされるように要望してまいりたいと考えております。２０１９年のテストイベントですが、各競技会場となるところの約１年前に本番さながらの同じ国際大会を各競技連盟、組織委員会等が大会をするです。","id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問・要望","question":"コンテナふ頭も含めて待機場所の確保などを要望で挙げていますので、ここ以上に待機レーンからオーバーレーンしてしまうというのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今、計画はされておりますが、具体的な日付等は確定されてございません。必ずしも競技によっては同じ会場でできない可能性もありますし、そういったことで現状、組織委員会のほうは調整していると聞いてあります。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"柵をつくるということの確認と、それからこれも先ほど話が出たのだけれども、コンテナヤードの整備というのはどうしても必要だと思うのですよ。","respondent":"多並道路課長、中村都市計画課長","answer":"私からは、自転車レーンについてご説明します。ぽこっと５０ｃｍほど出っ張った形のブロックを積み、その上に柵をつくりまして、車が入ってこられないような専用レーンをつくる予定です。今港湾局のほうで今後整備する予定としまして、港湾計画というのがございまして、その中では護岸の耐震工事ですとか。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この交通量が減り、期間中だけでもいいと思うのだけれども、きれいな駐車場を求めてくださいとお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"すみません、単純な質問なのですけれども、先ほどセミフラット方式というふうに説明をいただいたのですが、私、セミフラット方式といってもちょっといまいちイメージが湧かないので、もう少し詳しくご説明をお願いします。","respondent":"多並道路課長","answer":"１０センチから下ってきますから、その中で新しく出てきたのが、セミフラット方式というのがあります。歩道から横断歩道に行くときにも、歩いていく、通っていく方向の段もフラットになるようにしていくというのがセミフラット方式です。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"確認","question":"私も確認なのですけれども、また無電柱化とかというのは当然品川区と一定程度連携をとりながら同じような感じでやっていくものと思うのですけれども、その確認をお願いします。","respondent":"多並道路課長","answer":"我々と同じタイミングなのですけれども、予定ですと３月には品川区と大田区両方とも電柱が抜けるのが今の計画ということで、同時並行となっています。それから、道路整備についても一緒に整備しておこうということで、今協議しながら進めているところです。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"臨海斎場の先なのか、臨海斎場の手前のところなのか、どの辺までやるのでしょうか。もしわかればの説明を求めました。","respondent":"多並道路課長","answer":"それは今年度終わっています。そこから左側というのでしょうか、それ以外については今のところ我々としては把握しているところでございません。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"これまでの何年かに１回やってきた中にもあったのですが、輸送計画などにかかわってくると思うのですが、交通手段なのですね。","respondent":"中村都市計画課長","answer":"優先レーンというものを設けまして、大会関係者が優先的に通行できると、そういったレーンの仕方で今運用する予定だと聞いております。シャトルバスといった代替手段を考えていくというふうに聞いておりますけれども、まだ検討中ということで、今後の結果が待たれるです。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"先ほど視察させていただいたときに伺ったのですが、６両編成で６００人ですね、全員が全員おりるわけではないのですが。その辺も含めて、そういったところについての整備はどういう考えで今進めているのか、観光という視点も含めてちょっとの説明を求めました。","respondent":"中村都市計画課長","answer":"それから、バスにつきましても既に品川区内のバス路線につきましては１００％ノンステップ化が完了しております。区といたしましてもそれぞれ鉄道事業者、バス事業者、公共事業者に協力を引き続き求めていきたいと考えております。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"今ご答弁いただいたように、そうしたバリアフリーを必要とするような方も含めたアクセシビリティに配慮していただきたいなと思います。観光についてはまた別の機会にお聞きすることになると思うのですが、その辺はぜひ積極的に考えていただきたいなと思います。","respondent":"多並道路課長","answer":"ただ、一番はやはり利用者の多いところのデータをとる考え方と、もし活用するにしても活用できるところの場所の選択というのはあるのかなと思います。ただ、設計の中でもそういうものを取り入れて今後進めていく計画になっており、そういう観点で今後も進めていきたいです。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"そうしたログだとか動画での確認だとかそういったところは非常に大事な観点になってくるかなと思うので、ぜひ積極的に活用ほしいと求めました。","respondent":"多並道路課長","answer":"遮熱舗装ですけれども、今予定していますのは車道の舗装です。ブロック舗装をやる予定なのですけれども、なかなか今、あと滑りにくい製品など様々な観点を含んだものが出そろってない段階であります。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"すみません、１点だけ要望させていただきたいのですが、この会場周辺整備に当たりまして、道路の中央分離帯のところに植木の植え込みがあります。これは要望させてほしいと求めましたが、いかがか尋ねました。","respondent":"多並道路課長","answer":"ということで、まず中央分離帯自体は改良する予定です。ただ、やはり１つは信号無視されることが一番いけないことなので、その設計の中でちょっと考えてみたいと思っているところです。","id":"exchange-014"},{"speaker":"新妻委員","kind":"提案","question":"具体的な提案ができないのですけれども、事故が起こらないような体制をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"インターロッキングみたいな形の舗装になるわけですか。この委員会の中でパラリンピックと考えたときにどうなのかなとちょっと思っているのですけれども、その辺はいかがか尋ねました。","respondent":"多並道路課長","answer":"港湾局がやる工事の予定なのですけれども、そこと今様々調整しながら、どのようにしていくかということを調整しているところです。ただ、今のご意見を踏まえて、舗装材を選ぶときにはよく注意していきたいと思っているです。","id":"exchange-016"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"当然プロの方がやっているからその辺は心配ないと思うのですけれども、ぜひお願いしたいのと、もう一点ここに自転車専用レーンをつくっていただくのですけれども、自転車専用レーンをつくる意味はどういう理由でつくるのかの説明を求めました。","respondent":"多並道路課長","answer":"先ほど車で通っていただいたときにも見えたところもあるのですけれども、路面表示として通るようにしているところと２つあります。","id":"exchange-017"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"駐輪場は都のほうの問題かもしれないけれども、その辺をどう考えていくのかなお聞きします。公園の中だから答えにくい部分なのだけれども、その辺ちょっと両方絡みで教えてほしいと求めました。","respondent":"多並道路課長","answer":"まず大きな考えとしましては、品川区の中ではその計画の中の１カ所ありまして、いわゆるオリンピックの会場周辺のルートということで示されています。ただ、自転車の駐輪場のことについては、そういう中でまたそういうのはあるのではなかろうかなということで今は考えているです。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のお話を伺っていると、どうしても聞き役というかこういう風に考えていらっしゃると思いますよとか、そういう形が多いようにすごく思うわけです。","respondent":"多並道路課長","answer":"その中で１社を選んで、スタイリッシュな案が出ていまして、それに沿って今設計を進めています。品川区のほうでこういうことをやったということで説明したことで大田区にもご理解いただいて、他区を巻き込みながらやっていっているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"提案","question":"４点目ですけれども、大井ふ頭中央海浜公園について、都立公園を地元自治体である品川区に移管をすることを東京都に要望したいと思います。以上、４点提案したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"提案","question":"だから、例えば新しい課題が出てきたらこうだとか、それから新しい要望はこうではないかということがあれば出すべきではないかとふと思ったのですよ。一度まとめて出したことは事実だから、それを踏まえた上で議論したらいいのではないのでしょうかと、そういう思いだけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要望した内容についての何か東京都から議長や議会にこうしますとかああしますとか、検討しますとかそういうご返事があったのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ、これはお願いなのですけれども、東京都からの競技場などに関する情報提供資料、２９年８月吉日とかあるではないですか。それから希望を出していくというのもありかなと思っているのですが、その辺はどうなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"その辺を踏まえた上で要望書をつくっていきたいと考えておりますので、その辺の周辺整備も要望に入れるべきではないかということも考えております。行政側にどういう回答が来ているかはちょっと確認しなかったので、そのぐらいの形しか報告は来てないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"すみません、様々要望書を出された結果ということでお話があったので、１点だけ聞かせていただいてもよろしいですかね。城南地区の障害者スポーツセンターの設置も要望されていますけれども、それについても返答というのは一切ないのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"城南地区での障害者スポーツの設置と要望ということを出しています。実は、これについては１回だけではなく、何度も複数回出していますけれども、現在のところ回答は特にないところです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後も引き続き求めてほしいと求めましたし、やはり気軽にスポーツを楽しめるように、これは意見として言っておきたいと思います。そういった施設整備の検討もしていくようにということで要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"いながわ委員","kind":"提案","question":"東八潮というのですか、今後の品川区の発展に寄与するのではないかと思いますので、これは要望というか提案をします。とにかくオリンピックに向けてこうした道路のデザインがいいんじゃないかとか様々な意見を多分発想の中で要望として挙げていくと思うのですけれどもとの意見を述べました。","respondent":"多並道路課長","answer":"やはりオリンピックに向けたということで、そういう学校の教授のご意見をいただいたりして、我々もやはり一つレガシーという観点は考えています。","id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"様々な面から品川区がハンドリングできるぐらいに、東京都にこうですよと言ってそれを実現してもらうような口調で進めてほしいと求めました。ご答弁ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"提案","question":"斜めのそういうものが入れるものをつくるとか、そういうことも頭に入れながら提案をするというのが、私はありかなと思っていて。そういうものをぜひ考えてほしいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、なぎさの森が整備がされるというご答弁がありましたので、ちょっと１つだけお伺いします。そういう現状があるということを区が認識されているかどうか、まずちょっと確認させていただきたいのですが、いかがか尋ねました。","respondent":"多並道路課長","answer":"ただ、いまおっしゃった、多分そういう段階で様々な課題があればこれから解決していくと思うのですけれども。ただ、今の件については、私のほうでは把握しておりません。","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問・要望","question":"ちょっと話がずれてしまったかもしれませんが、現実そういう声がありまして、地元からそこはちょっと対応してもらいたいというようなご要望もいただいておりますので、そういうご認識もぜひしてほしいと求めました。","respondent":"木村委員長","answer":"ご意見につきまして、一旦正副で調整させていただきたいと思います。皆さんの手元にはないと思いますけれども、この資料というものをまた後ほど皆様にもお配りしたいと思います。","id":"exchange-031"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひ品川区へなんて話もしてきたわけですから、というかぜひやってほしいと求めましたので、よろしくお願いいたします。何かあれば一言お願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今年の２月には戸越体育館を会場に車いすバスケットボールの交流、このような形で今回トルコチームが機会を得ました。当然事前キャンプの誘致は区もかねてより考えているところですので、様々な場面で誘致については積極的に今後も展開してまいります。","id":"exchange-032"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"すみません、東京都から大井ふ頭の事前の情報提供の件なのですけれども、この図面の中で、第一球技場と第二球技場の工事とテニスコートが出ているんですけれども、真ん中の大井スポーツセンターのところは東京都から何も話はないのかわかる範囲での説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今のところまだ予定をしているというものは聞いていませんし、全体の大会前にどういった工事の内容になるかですとか、細かい情報が今まだ届いていないという状況です。","id":"exchange-033"},{"speaker":"新妻委員","kind":"質問・要望","question":"すみません、ドッグランの件、１点だけ確認させてください。しっかり使えるようにしていただきたいと考えていますが、何かドッグランに関して情報がありましたらの説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"７月から９月にかけて新設の工事中だというふうに伺っており、１０月からは完成し、直ちに使用できるような形になるというふうな情報は得ております。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"どういう趣旨でこっち側だけつけたのかなということを伺いたいのですけれども。これで両面の内容がわかるのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"こちら、このチラシのところに切り込みが入っておりまして、視覚障害者の方がこの切込みを頼りにＳＰコードを通すような形になっております。そのようなことで障害者福祉課と確認をいたしまして、この両面の情報についてはこちらのほうで読み込めるようにしております。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"工事の件なのですけれども、テニスコートＣというのはどういったことに使われるのか伺えればと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"図面に当たりますＣの部分、ちょうど大井スポーツセンターの間の部分に電気設備が入っているということを聞いております。今回こういった工事に入るということで利用休止になると伺ってあります。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645888?Template=document&Id=6520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":29544,"voices":75}},{"id":"h29-20170824-10","meetingId":"h29-cm08","date":"2017年8月24日","dateIso":"2017-08-24","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"広報会議からの報告事項","agenda":"広報会議からの報告事項","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"例えば質問の内容云々、質問内容が本人が言ったとおりですねと、最終的にそれを判別するのはどなたがやるのですか。例えば言っていることと、逆に不適切な言葉が入ってしまったり云々という可能性もなきにしもあらずだと思うのですが、その辺はどうなのか尋ねました。","respondent":"鈴木（真）議員","answer":"それが広報会議の役目であって、非常に大切な作業であるということで、それはこの会議の各メンバーも十分承知している話です。それは各会派の中でまたご協力いただかないと、広報会議のメンバー、事務局、大変な作業になってくると思うので、よろしくお願いいたします。","id":"exchange-001"}]},{"id":"topic-02","title":"平成３０年度予算（議会費）","agenda":"平成３０年度予算（議会費）","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"１番と２番は継続的なものでありまして、早急にやはり立ち上げてほしいと求めましたので、予算の要望はさせていただきたいと考えています。補助１６３号線整備事業の話があったり、質問等はどうするのかということが、この部分については提案をさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"塚本委員","kind":"意見","question":"２番目が、議員だけではないのですけれども、不便があるのではないかということで挙げさせていただきました。そちらのほうに意見として伝えていただくという形でもいいかと考えていますけれども、以上２点を挙げしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"５点目は委員会室のテレビにブルーレイ再生プレーヤーを設置することということについては、ブルーレイを整備したらどうかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"今のもわかるのですが、１点ちょっと議会改革にかかわることで、先ほど自民党のほうから海外調査費の予算要望がありました。できればこういう調査費は、私は出してほしくないと、それだけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"研究もして、海外調査もしていて、それをちゃんとマスコミの方もどうぞ来てくださいと。それぐらいの形で行くこと自体が、それが議会改革に対してマイナスだとか世論に対してどうだということは、大変さびしいお話だなと思っていますとの意見を述べました。","respondent":"渡部委員長","answer":"今もございましたように、各会派から出てきたもののご紹介をさせていただいて、これをもむ場ではございませんで、申し上げましたように議長一任とさせていただき、次回、議長より検討・調整の結果をお伝えするですので、そこはくれぐれもご理解をよろしくお願いいたします。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ということは次回、議長提案ということで、これを踏まえた上での提案が出されて、それをこの議会運営委員会でもう一回検討するという場が持たれるということで、確認させていただいてよろしいか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自民党としてはこのようにいきたいということで予算化を要望するということであれば、海外調査ありきでこのような予算要望ということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういう形のものをつくっていったらどうですかということで、それこそ議会運営委員会の中では全会一致で、じゃあ、いきましょうと。そのための予算は必ずつけてほしいということで、継続して出させていただいているということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どれぐらいの回数でやるのかですとか、そういうことを検討するということもなしに、ただ予算化というのはなかなか難しいかなと思ったのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"提案","question":"スタートをするための予算を継続してつけているということで、議長が提案したらそれでもう強制的にいくということにもなっていないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"おおよそわかりました。議長が提案したことを、そこの確認だけ、ちょっと質問をさせていただいたというところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5236#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":13482,"voices":44}},{"id":"h29-20170920-10","meetingId":"h29-cm09","date":"2017年9月20日","dateIso":"2017-09-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"同じように議員各位、それから品川区議会議長の公印を省略しておりますので、確認をお願いします。最後に１点、９月２２日の本会議終了後に、クラウド文書共有システムの使用方法を確認するための模擬委員会を実施する予定であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5238#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":9380,"voices":49}},{"id":"h29-20170922-4","meetingId":"h29-c-settlement","date":"2017年9月22日","dateIso":"2017-09-22","committee":"決算特別委員会","time":"午後 ２時５０分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/392487?Template=document&Id=1434#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":2040,"voices":17}},{"id":"h29-20170925-6","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"区民委員会","time":"午前１０時００分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"第５９号議案、平成２９年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第５９号議案、平成２９年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"当初は平均５００万円を上限に５件をはめ込んでいたけれども、この補正を組んだ趣旨というのでしょうか、そこについて伺いたいと思います。検証といいますか、効果というのでしょうか、そういうのはどうやって測るものなのかなというところです。","respondent":"鈴木文化観光課長","answer":"何件か個別に相談いただいたもので予算の活用の見込みをお聞きした上で、しっかりと年度内の事業についての支援を継続するというのが趣旨です。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問","question":"補正の考え方について伺いたいというのが１点と、必要に応じて予算を超えることは否定は全然しませんけれども。そして事業者から補助金制度申し込みが何件あり、何件助成を受けられなかったのか、それぞれの説明を求めました。","respondent":"鈴木文化観光課長","answer":"今年の３月下旬に、この制度をご説明いたしまして、取り組んでいる皆さんのいろいろな観光事業の促進に支援をすることで。そのうちの１件は、その単独ブースでは来場者見込みが３,０００人いかないということで、違う支援のご紹介をしたところです。","id":"exchange-002"},{"speaker":"田中委員","kind":"意見","question":"この事業の場合はどうだったのかということと、予算額を超えた場合は按分になるなど、今回のこの事業の場合はそういう募集ではなかったのかどうかとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"３月、４月早々にご活用いただけるということで、締め切りも設けないで随時相談をいただくという方式でスタートしたものです。補助率が５分の１下がった額で継続申請になりますので、基本的には４年間先まで、一度申請をいただいた団体については予算の目途が立ちます。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"最初、予算額を超えたときのことは、最初から超えるものだと思って予算をつくられていたのか。予算額を超えたときのことをどう考えていたのかということと、年内途中は締め切りがないということで募集が続くということか尋ねました。","respondent":"鈴木文化観光課長","answer":"予算を超えた場合にどのように対応するかとか、それで取りまとめたのが今回の４件になりますので、ひと通り把握をしているという認識です。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"補正のことに関してです。第５条に「補助金の額は、予算の範囲内において、今回の補正に計上された補助金額は予算の範囲内という枠に当てはまるのか尋ねました。","respondent":"鈴木文化観光課長","answer":"今年度は制度を開始した年度ということで、初年度に関しては補正の対応も前提として、年度の総額という考え方で今回は立てしています。先ほど申し上げましたように、次年度以降はご指摘のとおり、規定の文にあった予算の範囲内でという形で進めたいと考えております。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"次は４００万円、２００万円で、４年間で２,０００万円を１事業の企画団体に補助金交付するという理解で間違いないでしょうか。当初予算と補正予算を合計すると４,７００万円、来年には５,０００万円ほどの予算をつけるのかということを、２つの説明を求めました。","respondent":"鈴木文化観光課長","answer":"最高額で継続をした場合、４年間継続して申請をした場合には、１事業当たり継続４年で２,０００万円になるのはご指摘のとおりです。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"１事業者に４年間で２,０００万円ということですよね。行政に求められている公平性という観点から、ちょっと逸脱しているのかなとも思えてしまったのですけれども、そこら辺の見解を伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"１団体が４年間で２,０００万円が公平性に欠けるというのが、趣旨がよくわからないのですが、基本的には先ほど、事業として交付要件を満たす事業であれば、どの団体でも同じ機会で交付を受けられるようにしておりますので、公平性は担保できていると考えております。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"水辺議連というものが、この資料には募集の対象者が書いてあるのですが、議員連盟はこれのどこに当たるのかというのをお伺いしたい。最初の募集のあり方の質問に戻ってしまうのですけれども、そこら辺の説明を求めました。","respondent":"鈴木文化観光課長","answer":"ご指摘の当初予算が２,５００万円、支援制度分１,０００万円、もともと品川区と大田区で水辺連携事業というのを数年前から実施しておりました。つまり、自分たちの実施分の申請をいただいたですので、１事業に補助が１,５００万円ということでは決してございません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"この予算見積書には水辺議連分と書いてあるのですけれども、これが間違っているというか、詳細がきちんと書かれていないということか尋ねました。","respondent":"鈴木文化観光課長","answer":"これは予算編成のときに財政部局に説明する資料ですので、当初もともと文化観光課で想定をした支援事業で計上したものと、議連が支援をすることで連携をして行う事業というのを、枠として分けただけですので、内訳として特に問題はないかと考えております。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"わかりました。２個ぐらい前の質問なのですけれども、同じ事業者の複数応募というのは、基本的にありなのか、なしなのか。","respondent":"鈴木文化観光課長","answer":"別事業になりますので、１団体当たりの申請数の制限というのは、現在のところはかかっておりません。その辺は今、申請の具体例がないのですけれども、また個別にその内容をお聞きした上で判断することになるかと思います。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"でも神事ですよねと伺えば、神事ではありませんと役所は答弁するしかないと思うのです。もう出ているわけですから、神事ですかという質問から入って、答弁していただけますか。","respondent":"鈴木文化観光課長","answer":"それから群馬県老神温泉の３つのイベント実施主体が合同でサミットをするそのイベントについての区の補助ですので、今のところ。一本線を引いた基準を設定できるわけではありませんが、宗教色一色でない事業であれば、相談の上で進めたいというのが現在の考え方です。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"この白蛇に関しては、上神明天祖神社の宮司さんをはじめいろいろお考えになって、こうやって補助金をあそこはもらえたわけです。もう少しハードルを下げていっていただきたいと考えていますので、もう一回、その辺について。","respondent":"鈴木文化観光課長","answer":"基本的には、先ほど申し上げた地域のにぎわいや来訪者増加につながって、純粋な宗教事業でなければよろしいというのが基本的な考え方です。申し訳ありません、新規事業か実施２年目以内の事業なので、その辺は検討の余地があるかと考えております。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっとわからないので、見積書の水辺議連の１,５００万円と、説明資料のしながわ・おおた水辺の観光フェスタの合計が１,５００万円。この辺の説明がちょっと難しくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"大井第三区民集会所の休館","agenda":"大井第三区民集会所の休館","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"理由のところで、トイレ改修工事とあわせて便所となっているのですけれども、トイレと便所の説明をしていただきたいのと、予算は幾らか尋ねました。","respondent":"伊崎地域活動課長","answer":"予算につきましては、２,７２０万円、工事予算として計上しています。排水管工事につきましては、便所排水管という名称がありますので、そのまま使わせていただいております。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"便所と言うと「えっ」と思われるときがあるので、用語なのですけれども、その辺についてはいかがですか。そうしないと、毎回これが出たときに、どちらなのですかと質問しなくてはならないような気もするので、その辺についていかがか尋ねました。","respondent":"伊崎地域活動課長","answer":"委員ご指摘のとおり、イメージということは確かに大きな印象ですので、今のご意見に関しまして、私がこの場で立場上お答えしかねるものですので、また必要な検討をいたしまして、対応を進めたいと思います。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういった要望があって、どういった工事を行うのか、その内容について伺いたいと思います。例えば雨水を使って排水をするとか、何かそういう対応も含めてなのか確認と、工事の内容についてご説明ほしいと求めました。","respondent":"伊崎地域活動課長","answer":"女子トイレが非常に暗く狭く、用を足すのも結構姿勢が大変だという状況もありますので、そういったところを対応していきたいと思っています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろ工夫をしてほしいと求めましたけれども、そうした声に応えるトイレにしていただきたいと、これは要望しておきたいと思います。最後に１点だけ、それともトイレの改修の順番を変えるのか、そこだけ最後にご説明ほしいと求めました。","respondent":"伊崎地域活動課長","answer":"トイレは１階と２階にありますので、順次行うということで、特に仮設は予定しておりません。","id":"exchange-017"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"ここのトイレの確認なのですけれども、洋式と和式の現状と、工事を行ってからどうなるのか、数の面で洋式と和式を教えていただきたいのですが。","respondent":"伊崎地域活動課長","answer":"スペース上の問題がありますので、数を増やすのは難しいと伺っております。ですので、それぞれ１つずつになりますので、洋式トイレということで見ております。","id":"exchange-018"},{"speaker":"塚本副委員長","kind":"質問","question":"既に洋式ですか、現状では和式はないということか尋ねました。","respondent":"伊崎地域活動課長","answer":"今、洋式トイレが１つずつですので、そのままです。","id":"exchange-019"}]},{"id":"topic-03","title":"交流都市地方物産展 千葉県物産展フェア","agenda":"交流都市地方物産展 千葉県物産展フェア","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"それともう１点は、いいのですけれども、ここまでいくのですか。１週間ぐらい物産を売ることで、ここまで千葉の各市町村とこういう形まで持っていけるのか尋ねました。","respondent":"伊崎地域活動課長","answer":"この後２月頃に別途開催を予定しておりまして、それにプラスして今年、全国シティプロモーションサミットの時期に合わせて行うという考え方です。この後２月頃を予定しておりまして、違うところで実施をする予定で、検討を進めているところです。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"１つだけ確認させていただきたいのですが、たしかわっくわくランドも連携の一つだと思ったのですけれども、そういう意味合いで考えていてよろしいのか尋ねました。","respondent":"伊崎地域活動課長","answer":"わっくわくランドは主催が子ども育成課ですので、子ども育成課の趣旨を持っていると思われます。協力しているということを聞いておりますので、そういった意味では、こちらの全国連携プロジェクトの趣旨にのっとった形であると捉えております。","id":"exchange-021"},{"speaker":"渡辺委員","kind":"質問","question":"これが１回こっきりで終わるのではなくて、交流を仕掛けていくではないですが、続けていこうということがあるべきだと思うのです。これまでの縁がある自治体、あるいはこれから縁を深めていこうという品川のイメージ、希望はあるのかどうか、の説明を求めました。","respondent":"伊崎地域活動課長","answer":"こちらから千葉県の町村会を通じて呼びかけを行ったところ、そちらにあります出店自治体からのご回答をいただいたです。今後ですが、今後も交流の機会を増やしていけたら、こちらの交流都市地方物産展の趣旨にも適っているかと考えております。","id":"exchange-022"},{"speaker":"渡辺委員","kind":"質問","question":"先ほども質問が出ていました阪急でやったときの、もうちょっと見せ方のところで、品川と連携している感が部分的にもあるべきかなと思いました。行政として品川区のかかわりとか演出面を含めて力を入れるべきと思うのですが、その点、コメントを下さい。","respondent":"伊崎地域活動課長","answer":"今年といいますか、今回の千葉県物産展はイトーヨーカ堂で開催をいたします。ご指摘ございましたように、掲示の仕方等も工夫をして、先方と相談しながら検討してまいりたいと考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"単なるフェアではなくて、どういう意味合いがあるのか、どういう背景があるのか、そこを伺いたいと思います。別にやってはだめだとか、そこまで強く言うつもりはないですけれども、区としては今どう思っているのか、そこをきちんと伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"特別区全国連携プロジェクトにつきましては、私からは特別区全国連携プロジェクトの趣旨、そちらのご説明とさせていただきたいと思います。各２３区での事業分野としまして、また東京２０２０オリンピック・パラリンピックを契機とした活性化、地方物産展に取り組んでいるです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"何で物産展フェアにつながるのか、そこを改めて伺いたいと思います。そういう方向を求めていくというのが本来であって、こういう物産展というのは、そこについてお伺いしたいと思います。","respondent":"伊崎地域活動課長","answer":"品川区民の方が今までなかなか触れなかった地方の物産に触れることで、またそこに興味を持っていただくということも大事なことだと考えております。","id":"exchange-025"}]},{"id":"topic-04","title":"品川歴史館特別展 大崎・五反田─徳川幕府直轄領の村々─","agenda":"品川歴史館特別展 大崎・五反田─徳川幕府直轄領の村々─","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"学芸員のご努力というのは、どういうふうに特別展の企画を組まれているのか、そこを伺いたい。この間ご説明ありますけれども、見通しはついているのか、いつ頃から考えていらっしゃるのか、そこも伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"特別展につきましては、ご指摘のとおり学芸員が中心となりまして、毎年度様々なテーマを設定して実施をしております。課題、今後のオリンピック・パラリンピックを踏まえた歴史館の活用について検討をしていて、お話をさせていただければと考えています。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区立の施設ですから、今１００円取っておりますけれども、これについても子どもは無料にしてあげていいのではないかと思うのです。","respondent":"鈴木文化観光課長","answer":"小・中学生全部無料というのは難しいかと思いますが、この料金体系を設定したときの当時の状況も踏まえて確認をして、今後改定の余地があるのかどうかは確認をしたいと思います。","id":"exchange-027"}]},{"id":"topic-05","title":"イルミネーション事業","agenda":"イルミネーション事業","exchanges":[{"speaker":"田中委員","kind":"質問","question":"２０１５年度の事業費は約５,０００万円で、２０１６年度が６,２５０万円だったと思います。今回またどうして増額されたのかなというのは、イルミネーションの設置について、今後のプランなどがあるのかということの説明を求めました。","respondent":"鈴木文化観光課長","answer":"今再開発の工事が入っていたり、イルミネーションの設置にふさわしい状況であれば考えたいというのは、項目としては予定しています。そういうことも含めて、プランといいますか、何年度にどこというしっかりとした計画を立てているものではないのが現在です。","id":"exchange-028"},{"speaker":"田中委員","kind":"意見","question":"今回の新規追加の部分が阪急前ですよね。阪急の方との話し合いも当然されたと思うのですけれども、そこではどのような協議がされたのかということを聞かせてくださいとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"１点目の、予算配分をお答えできるものではないのですが、区全体の予算配分のバランスを設定していると考えているところです。今までの経過と、毎年設置するときにお声かけをしたときにいただいた意見を踏まえて、中身を少しずつ変えているというのが現状です。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"イルミネーションに関してというのは、効果測定が難しいと思うのですけれども、どのようなところでこの効果を測っていくのかということの説明を求めました。","respondent":"鈴木文化観光課長","answer":"大井町と目黒川と西小山、基本的には連携をしながらイルミネーションを実施することで、数字としては目に見えやすいものになるかと考えています。品川区の魅力を改めて認識して、ある程度継続した後に、そういう情報をもう少し調べてみたいとは思っております。","id":"exchange-030"}]},{"id":"topic-06","title":"八潮北公園スケートボード場およびフットサル場のオープン","agenda":"八潮北公園スケートボード場およびフットサル場のオープン","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"なぜ子どもがスケートボード、フットサルをするのに、子どもからお金を取るのか。有料はやめて無料にすべきだと思いますけれども、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"フットサル、ミニサッカーということで利用されているところですけれども、こちらの料金と同じ形での料金設定ということにさせていただいてあります。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が聞いたのは、フットサル場について、なぜ小学生・中学生からもお金を取るのか、改めてその理由を伺いたいと思います。どういう検討の結果、有料としたのか、その理由について改めてご説明ほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"スケートボード場につきましても、無料のところもございましたし、有料のところもございました。小学生以下を１００円、第２回定例会のときに条例を議案ということで提出して、皆様のご審議をいただいて決定をされてきた経過があります。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"スケートボード場についても、どういう検討をしたのかということを伺ったのです。そして、どうして子どもがスケートボードとフットサルをやるのにお金を取るのか、そこをしっかりとご説明ほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"こちらに整備したフットサル場のほかに、フットサルもしくはサッカー等ができるものとしまして学校の校庭等のいろいろな施設があります。競技として対戦するような形で整備していますので、ある程度の受益者ということで、負担をしていただくという形になっているものです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"そうした取組みがひいては豊かな社会をつくり、人間関係をつくり、そしてオリンピックという世界的な平和の祭典にまで発展していく。ぜひ考え直していただきたいし、品川区のスポーツ政策というのは一体どういう考えで行われているのか、しっかり伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"障害のある方と障害のない方が一緒に楽しめる場所ということで、スポーツの振興を進めているところです。いつでもどこでも誰でもいつまでも、そして障害のある方もない方も、一緒に楽しめるスポーツの振興ということで進めていきたいと考えております。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"その子どもから、小学生以下１００円、中学生以上２００円。これはぜひ考え直していただきたいと強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"質問しますが、まず、スケートボード場に来てくださる人数はどのように考えているのでしょうか。こういう形になったら大変ですから、その辺についてはきちんと仕組みができているのかの説明を求めました。","respondent":"池田スポーツ推進課長","answer":"おそらく１日当たり数十人ということを予定していまして、２００円ということになりまして、楽しんでいただくということを前提としています。ヘルメット、あとは、実際にやる前には登録をしてもらって入っていただくという形をとる予定になっております。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"改めて数十人という数を出している根拠を教えていただきたいのと、先ほど質問しましたが、予想しておいたほうがいいと思います。こういう形で施策で下りてきて、どういうふうに活用して普及していくのかというのをお答えしていただきたいので、その点についてお伺いします。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"２,０００名という数が来た場合にどうなるかですけれども、そういうところがありましたら、それなりにつくるような形になってくると思います。プランのときからオリパラの担当部局にも情報提供がありまして、一緒にプランにもかかわったことです。オリパラ担当といたしましても大変歓迎すべきことでありまして、今後の機運醸成事業には様々に活用していきたいと考えております。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"スケボーを課長がやられたことがあるかどうかわからないですけれども、結構みんな、危ないというのもあるではないですか。２,０００人ではなくて、その辺についてどうですかということを伺っている。","respondent":"池田スポーツ推進課長","answer":"今のご質問、確かに定員についてはきちんとしなければいけない部分だと考えています。実際にまだできておらず把握できていませんので、こちらは工事完了と同時にきちんと、何人程度が限界かなというところでやりたいと思います。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"スケートボードをやられている方から「うわさで聞いたんだけど、本当にスケートボード場ができるの」という感じで問い合わせがよく来ます。今回のオープン、供用開始日と、記念イベントの日の周知方法はどのようにされるのかということを伺いたいです。","respondent":"池田スポーツ推進課長","answer":"周知方法ですけれども、オープンの周知につきましては、１０月２１日号の広報紙で載せる予定です。同様に、フットサルのことと、スケートボード場の初心者のためのスケボー教室のご案内も、同時に載せる予定になっております。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"このイベントのスケボー教室とサッカー教室なのですけれども、これは１０月２１日の広報紙ということですが、募集とかになるのですか。それとも、誰でも受け入れるような形になるのかということを伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"スケートボード初心者のためのスケボー教室は、広報紙によって募集ということで、たしか先着ということを聞いております。面数も１面ですので、教室自体を少年少女のサッカーの協会に依頼して、参加者を募るということを考えているところです。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/824061?Template=document&Id=2790#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":36253,"voices":125}},{"id":"h29-20170925-7","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件整理しています。","topics":[{"id":"topic-01","title":"の２、議案審査、第５９号議案 平成２９年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"の２、議案審査、第５９号議案 平成２９年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう防犯対策にということでの補助金なのか、それとも違う中身で使えるものなのかということについて一つ教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"自治体によってやる区やらない区ありますし、実施するにしても補助率の問題というのはそれぞれの区によって違っているようなところです。それから、区立については昨年度の補正予算で１１０番通報について実施をしたところですけれども、鍵をつけたりそういう作業もしています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう虐待事件に対しての抑止という意味もあって今回出されたのかということをもうちょっとお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"中には３点全部つけたいというところもありましたし、あるいは１１０番通報のみというところもありました。それから、防犯カメラを幾らで金額を設定しているかですが、工事も入れて単価２５万掛ける２カ所ということで、一応設定しています。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから今回の津久井やまゆり園の事件にしても、職員ということからすると、外部からの侵入者のところだけを防犯するというだけで抑止になるのかというふうなあたりについての考え方はどういう考え方なのかということについてもお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"逆にそういう不適切な対応があったときに注意をできる、し合える環境であったりとか、虐待の対応はされるべきなのかなというふうに考えております。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと同時に、そうはいってもそういうふうな事件がいろいろあるわけですから、そういうふうな対策は必要だろうなという思いがしております。虐待の問題も今ちょっと、その対策というのは何かされているのかということについても、ちょっとお聞かせいただけたらと思います。","respondent":"中山障害者福祉課長","answer":"ご様子、そういう方につきましては行動観察等をさせていただき、不安なく今のところお過ごしいただいているということをまず確認したところです。区としては、今現在そういう対応をしたところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"本当に虐待というのがかなり件数としても増えているということで、ぜひ今後ともきちんとした虐待の対応というところでお願いしたいと思います。","respondent":"中山障害者福祉課長","answer":"委員ご指摘のとおりで、昨年度の補正予算で取りました１１０番通報のことです。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"防犯カメラ１台２５万円というお話があったのですが、これは区として同じ機種を考えているのか、それとも各施設ごとでばらばらに選んでいくのか。その辺はどうなっているのか尋ねました。","respondent":"中山障害者福祉課長","answer":"実際に設置するのはそれぞれの施設の運営事業者になりますので、設置についてはお任せをし、特に同じ機種ということでは考えておりません。大体どこの防犯カメラも設置できるというふうな見積もりがとれておりますので、上限という形で設定させていただきました。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっとほかとの絡みもあるのですけれども、これ、どのぐらいの耐用年数を考えていくのか。今回は一遍にやるから１件１件区が助成していきますけれども、その辺どういうふうに今捉えているかとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"防犯カメラについての耐用年数とその後のお話かと思います。防犯カメラ自体は、防犯カメラを一度今回の補助事業で設置してその後壊れたときに、また区がもう一度設置するかどうかというところまで。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"所管は違うのですけれども、各町会に防犯カメラをつけたときの耐用年数の問題も既に出てきているという話もあるので、その辺が気になったので。今後またその辺を調査しておいてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これ、その辺の障害者に対しての見方の研修みたいなのがされているのかどうなのかというのをちょっとお聞きしたいのですけれども。そういう取り組みがされているのかということと、その点についてもの説明を求めました。","respondent":"中山障害者福祉課長","answer":"区の取り組みとしては、２年に１回ぐらいにはなるのですけれども、そうした虐待予防であったり人権研修等を障害の分野でやっています。そのほか、各法人におきましては法人の取り組みという中で、当然虐待防止研修、人権研修というのを実施しています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この事件がそもそも何だったのかというふうなところに立ち返って考えるというふうなことが必要なのではないかというところでの質問をしました。その障害者権利条約について、職員が学ぶ場というのがあるのかだけちょっとの説明を求めました。","respondent":"中山障害者福祉課長","answer":"当然福祉を学ぶ者としては、条約の中身あるいはその基本的な考え方、そういうところについては理解をしていると考えています。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は障害者権利条約というのは本当に障害者福祉をこれから充実させていく大もとの基本になるものではないかと考えていますので、区としても障害者権利条約を職員が学ぶ機会というのをぜひつくっていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほどの質疑の中で、区によって補助率が違うというお話があったので、ちょっとそこを詳しくお聞きしたいと思います。人感センサー等とありますので、この「等」の内容も確認をしておいたほうがいいかなと思いますので、お聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"ほかの区では４分の３の補助率であったり、２分の１の補助率であったり、あるいは実施しないという区もあるような状況です。人感センサー、そうしたものに幅広く対応できるように、「等」という言葉にさせていただいているところです。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"改めてこの補助率がなぜ区によって違うのかというところをもう一回確認をさせていただきたいのと、あと「等」の中身を今聞きました。","respondent":"中山障害者福祉課長","answer":"そうしたものを全部提示した中で、それぞれの施設で対応したいという具体的な希望をまとめたものが今回の補助の中身ということになっております。それから、一度施設の中を点検していただきましたので、まずは今回の補助金を使って対応したところで様子を見ていくつもりです。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"１カ所、工事を伴う防犯カメラというところで、工事を伴うというのはどういう意味なのかというところを教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"工事を伴うというのは、今簡易型ですぐ取り付けて対応ができる防犯カメラが２万円ぐらいからあると聞いております。それについては今回は補助の対象からは外させていただいたです。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"なぜ２万円の簡易型のものでは防犯というところの抑止力を高めるところには至らないというところなのかどうかを教えていただきたいのと、教えていただきたいのですが。","respondent":"中山障害者福祉課長","answer":"やりたいけどやれない、ある程度お金のかかるものということの考えでおりまして、工事を伴うものというような形にさせていただきました。先ほどご答弁申し上げましたとおり、いましばらくこれを使ってみてのことで、その後については今後の課題というふうに考えています。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"新規だけということですが、もうちょっと新しいもののほうがいいなという施設があれば、それはこの補助金を使ってかえられるのかどうか。それともそれはもう既に設置しているものなので、各法人でやってくださいということなのか、その辺だけの説明を求めました。","respondent":"中山障害者福祉課長","answer":"今回は新規に設置ということで、既に防犯対策を行っている事業所も確かにあります。そういうところは逆に防犯カメラはもう既に設置しているので１１０番通報を入れてほしいというような形でご要望いただいています。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"この区内、希望をとって設置ということだったのですけれども、これ３つ全部を希望するということもできるのですよね。そうなると、３つ全部を希望した施設というのはどれくらいあるのかということを聞かせてくださいとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"そのうち全体で３３カ所が今回手を挙げてくださったということになります。それで、３つ全部を希望されたところですが、全部で１９カ所になります。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この３つ全部を希望したところというのは、先ほどほかの委員からもありましたけれども、ついているけれどもさらに充実をさせたいというところなのか、全くつけていなくて今回こういう機会があるからつけようということになっているのかを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"新規ということでお願いをしているので、今まで防犯対策のそこができていなかったという事業所になります。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほども質疑がありましたけれども、こういった事件が頻繁に起きている中で、人員配置というのはどうなのかなと。職員の配置、人材確保がすごく大変だというのもお聞きするのですけれども、あとは少し増員したというところがあったのかどうか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"こういった障害あるいは児童福祉の支援については人員配置基準というのがありまして、そこの基準は当然各事業所とも満たしているところになります。","id":"exchange-019"}]},{"id":"topic-02","title":"平成２９年請願第１１号 品川区障害児・者福祉計画の策定時における当事者の参画機会の確保に関する請願","agenda":"平成２９年請願第１１号 品川区障害児・者福祉計画の策定時における当事者の参画機会の確保に関する請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ私は委員会の審査の前にお話を伺って、そして審査に入るというほうがより障害当事者の、また家族の方の声を直接お聞きして、そしてこの審査ももっと深い形での審査にすることができると思いますので、ぜひ意見陳述は冒頭にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"若林委員","kind":"意見","question":"これまでの慣例に従って、委員長からご案内のあったとおり、後ほどということでお願いしたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この請願そのものが本当に障害者、多くの当事者の意見を聞いてまた意見交換の場を設けてほしいというような項目もありますし、ぜひ。もし冒頭ではなくて、後のほうがいいというのであれば、後のほうがいいという理由もちょっと教えていただけないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この４年間で大きく社会情勢というのが変わっていると思うのですけれども、区はどう捉えたのかということを一つお聞かせいただきたいのと、あと。そういうさまざまに抱える課題や多様化したニーズをどう計画に反映するのかと、その点についてお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"そうした課題にどう対応していくかというところは、相談支援というものが入っておりますので、実際にサービスというものを組み立てているところです。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことも含めてせっかくこういうふうな形で計画を立てるわけですから、本当に全てを網羅できるというふうにならないのではないかと思うのです。","respondent":"飛田障害者施策推進担当課長、中山障害者福祉課長","answer":"ただ、大切なことだと考えていますので、次回のアンケート調査のときは児・者も含めて行いたいと考えています。アンケートをとる時期も少し早目にというふうに検討していきたいと考えています。平成３０年度からつくりますよというのは出ていたのですが、実は指針というのがなかなか出てこない状況もございました。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に品川区は自立支援協議会でこれを策定するということになっていますが、自立支援協議会が３回しかないではないですか。本委員会の中でも求めて検討していただくということで、ホームページも９月１５日に掲載されましたので、私も見せていただきました。","respondent":"中山障害者福祉課長","answer":"１回目の自立支援協議会のときに、それから国が求める成果指標、そうしたものを第１回の自立支援協議会に諮らせていただいたところです。なので、その２回目の審議が有効にかつ無駄なくいい会議となるような、そうした取り組みを事前にしていければと考えております。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうものをまとめたものはないのかと伺ったときに、え、実績のまとめはあったのですねという思いがしているのですが。６月の段階でこの実績のまとめができていたのに、７月の委員会の中で私はそういうまとめというのはないのですかと聞いたときに。","respondent":"中山障害者福祉課長","answer":"アンケートはアンケートとして取りまとめて集計したもの、そして分析したものを自立支援協議会の中でご報告する予定です。実績ということでまとめたものを自立支援協議会の中でお示しし、前回の自立支援協議会ではこうしたお話をさせていただきながら、共通認識を持ち。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしたら、これが出てきたのでそこのところはどうなのですかと聞いたので、ちょっと答えてほしいと求めました。そして、私がそういうふうにまとめたものはないのですかと聞いたときにないと言っていた、その点についても改めての説明を求めました。","respondent":"中山障害者福祉課長","answer":"実際にはこれに平成２９年度も既に８月実績分までは見えてきておりますので、そうしたものも見合わせながら計画値には反映をさせていく予定です。前回実績としてまとめたものはないとお答えをしたというのは、こうしたものは毎年作成をしています。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はそういうふうなところで、多分何回か、ないのですかと、２回ぐらい議会で聞いたと思うのです。この計画実績についてどういう状況なのかというのを、議会にもぜひ報告をしていただきたいと思うのですけれども、その点についてもの説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"今回、障害児のほうでアンケート調査させていただきました。それに伴いまして実績、それからアンケートについてもまたこちらで報告をしたいと思いますので、よろしくお願いいたします。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者運動の大きなベースになっているわけですから、家族の皆さんと一緒に計画をつくるという姿勢をぜひ貫いていただきたいなと思うのです。","respondent":"中山障害者福祉課長","answer":"２回やる予定なのですが、それからあとは７団体だけではなくいろいろな区民の方のお声を聞いている相談員がいるので、両方設けようと思っています。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"７団体は会長と一緒にどういう形でということを相談するということなのですけれども、例えば、全ての会員を対象にした意見を聞く場を設ける。","respondent":"中山障害者福祉課長","answer":"それぞれの会の会員の集まっているところに行ってお話等もさせていただいているところですので、そこは引き続きやっていければと考えています。それから、いつぐらいというところなのですが、まず７団体の会長会は１０月の中旬までにはという形で日程調整を今しています。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしましたら、ぜひ団体の方が全ての会員を対象にということであれば、応じていただけるということで、ぜひよろしくお願いしたいと思います。私は全区民を対象にした説明会、この計画が、その点についてはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"全障害のある方を対象に説明会をということになりますと、今の計画策定のスケジュールですと実質的に難しいと考えております。パブコメ前の計画に対する区民全体への説明会ということですけれども、一応パブリックコメントを実施する中で広く当事者の方、家族の方。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"目黒区は障害者の方の全てを集めた要望を受けて、また意見交換をする場というのがかなり保証されていると聞きました。何で品川だけがやらないのかなといつも思っているのですけれども、やらない理由というのは何なのか尋ねました。","respondent":"中山障害者福祉課長","answer":"個別の説明会というところでは、現状のところ考えてはおりません。やはりこの計画をつくるということ、パブリックコメントで多くの意見がいただけるように、そういった周知をしていきたいと考えています。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区の行政自身も、家族・関係者、区民から広く意見を聞いて受けとめるという場をぜひつくっていただきたい。そのためにも、区民への説明会をぜひやっていただきたいと思うのですけれども、そういう観点からはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"障害のある方のご理解を進める、あるいは民生委員の皆様にこの内容について説明をするとか、広く周知していくつもりです。ただ、その計画に際して、一般の皆様に向けての説明会については現在予定をしていないです。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"説明会をやらない理由というのは何なのでしょうか。ほかの区はみんなやっているのに、品川区だけやらないというその理由は何なのか、の説明を求めました。","respondent":"中山障害者福祉課長","answer":"策定の中でいろいろな方のご意見を聞くということはとても大事なことだと考えています。ただ、なかなかできたものをパブリックコメントの前に説明して、そうしたスケジュールをしていきたいと考えております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区だけがつくっているのではなくて、どこの区もつくっているわけなので、品川区だけタイトなスケジュールということではないと思うのです。ほかの近隣区全部が説明会をやっているわけですから、関心をさらに広げる、ご検討いただきたいということで要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もちろん会派の中でいろいろ勉強した上で質問が多岐にあったのですが、今大分出ていましたので、重ならない部分でお聞きしていきたいと思います。先ほど、予算面だけでなく指針が出てないということもあったということ、その辺はご理解はいただいているのか尋ねました。","respondent":"中山障害者福祉課長","answer":"対応した者に確認したところ、そこまでの話はさせていただいていないとのことでした。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問","question":"改めてそこら辺はきちんと説明していくべきだと思いますし、その時点ではなくその後の時点で説明はなさったのかどうか。その辺はまだ理解されていないのかどうか、の説明を求めました。","respondent":"中山障害者福祉課長","answer":"この請願をいただいて、この間ちょっとこちらの団体ともお話をする機会がなかったので、改めて団体とお話をする場を設けさせていただければと思います。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"委員会でこういう話もあったし、その辺はよくこれからご説明をしておいていただきたいので、これはお願いします。それから、自立支援協議会に当事者の参加という話なのですが、メンバーとしてどういうメンバーかもう一回確認をさせてください。","respondent":"中山障害者福祉課長","answer":"自立支援協議会のメンバーですが、それからあと特別支援学校の校長、それと区の各障害施策に関係する部長級職員で構成されるものです。それと、公募の委員、区民委員を２人設けているところです。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"７団体の中の当事者という扱いがどういうふうにとられるかということが課題かなと思ったのですが、ご本人自体が当事者というケース、ご本人が当事者という方がこのメンバーに入っていらっしゃるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"今の自立支援協議会のメンバーの中に当事者の方はいらっしゃいます。立場としては、あと医師という立場で入っていただいているのですが、実際に車椅子の方がお二人委員でいらっしゃいます。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いろいろなお話を伺っていても、例えば当事者との会合、その辺を強くやってもらいたいなと感じております。この３年間の間にいろいろな立場も変わって、その辺をもう一度意識を持った上で今後の方向性についてはもう一回ちょっとご確認をお願いします。","respondent":"中山障害者福祉課長","answer":"当事者の方の意見が十分反映されていないではないかという思いがこの請願にあらわれていると考えていますので、そこは反省をし、できるだけ多くの方のご意見を聞く場を設けていきたいと考えております。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"今回いわゆる当事者の方から請願が出されたというふうな流れを一つ確認をしながら、特にこちらの第５期の障害福祉計画にどのような影響があるのか。実態に沿った計画と果たしてなるのかどうかというところが、今の何点かの、質問についてまずはご答弁をいただきたいなと。","respondent":"中山障害者福祉課長","answer":"第４期は特にやはりグループホームの設置ですとか、それから日常生活の支援、緊急時の対応や介護者のレスパイトということでショートステイ。第５期、相談の中の声としては基本的には第４期がベースになっているのかなと考えております。","id":"exchange-041"},{"speaker":"若林委員","kind":"確認","question":"３年ごとに調査をする、私は請願者の声を聞きながら、単純にそうだよなと思うところがすごく大きかったのです。３年後、毎回の３年ごとにしっかりとアンケートという形で声をお聞きするということをどのように今お考えか、これはちょっと確認させてください。","respondent":"飛田障害者施策推進担当課長","answer":"今、委員がおっしゃったとおり、障害福祉計画、障害児福祉計画ですか、次回、また３年ごとこれから続きます。ですので、そのときは前もって障害者・児、両方アンケートを実施していきたいと考えております。","id":"exchange-042"},{"speaker":"若林委員","kind":"確認","question":"請願項目の２番目にある、他区と品川区の違い、これについていま一度確認をさせていただいて。ただ、そういう場も設けることはやぶさかではないという理解でいいのかどうか、ちょっと確認をしたいと思います。","respondent":"中山障害者福祉課長","answer":"実際には区民向けの説明会をやっている区、現在やらない区が１４区、区民向けのというところではやっていないというところになります。その中で区民の方の意見をお聞きするというのも大切なことだとは思ってはおりますが、説明会までは考えていないところです。","id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"その第１期から第３期のところではニーズ調査をしなかった期というのはあるのですか。第５期は調査しませんでしたということなので、第１期、第２期、第３期のところではニーズ調査は毎回やられてきたのか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"それで、第１期、第２期、第３期にニーズ調査をしたかですが、これについてはニーズ調査はしておりません。第４期の福祉計画を立てるときに初めて区としてニーズ把握をするために調査をやったというような状況です。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この基本指針に即して市区町村、都道府県がこの障害福祉計画・障害児福祉計画を作成するというふうになっていますよね。第７期、第８期、ニーズ調査はしていくという姿勢なのかを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"今後につきましては、障害児・者もニーズ調査というのはこの節目ごとにやっていきたいと考えております。","id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"つくるべきではないかという質問もあったと思うのですけれども、私もいろいろ要望の聞き取りなんかを障害者団体の皆さんからさせていただいて。次回になってしまうかもしれないのですけれども、ぜひ一度やってみてはいかがかなと思うのですが、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"全体スケジュールの中でできるだけ多くの声を聞くためにどういう聞き方、どういう手段があるかもう一回検討し直しかなと思っています。今後についてというところですけれども、ちょっと検討課題とさせていただければと思っています。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"確認","question":"自民党・子ども未来としては、請願者の方から先にお話を伺いまして各種資料もいただきました。先ほどの発言の中でも言った、私どもの会派でもいろいろ研究してどのような課題があるかということを確認をとった上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はぜひ当事者の方の意見をお聞きしたいと思います。そういう点では、私たち自身がより理解を深めるという意味からも、ぜひとも意見陳述を受けていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"大倉委員","kind":"意見","question":"私たちもご説明を受けて資料もいただきまして、会派の中でもさまざま議論させていただきました。そうした中で、このまま意見陳述をしないで進めていっていただいて構わないのかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党・子ども未来の態度としては、今、この委員会での質疑が相当されました。私どもとしても当事者意識というものはものすごく理解をしておりますので、全体としては理解した上で趣旨採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"若林委員","kind":"質問・要望","question":"２番の区民説明会ということで今質問もさせていただきました。これについては区の答弁も了としながら、全体として趣旨採択ということで結論を出したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ニーズ調査も当然すべきというところで、ぜひこれを生かして今後につなげていただきたい。より多くの、全ての当事者の方々に意見を聞く場というふうなところもぜひつくっていただきたいと考えていますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"要望があればしていくということで、この辺のネットワークもしっかりとつくりながらニーズ把握をぜひやっていただきたいと思うところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-03","title":"平成２９年陳情第１０号 品川区障害児福祉計画策定において、厚生労働省の定める「障害児等のニーズも勘案した見込み量設定」の徹底を求める陳情","agenda":"平成２９年陳情第１０号 品川区障害児福祉計画策定において、厚生労働省の定める「障害児等のニーズも勘案した見込み量設定」の徹底を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ぜひ私は先に意見陳述をしっかりと受けとめて、それからその思いを受けとめた上で議論するというほうが本当に議論が深まると思うのですよ。ぜひ、先に受けていきたいということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"若林委員","kind":"提案","question":"委員長のご提案のとおり、先ほどと同じ形式で進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"実態・意向調査、ニーズ調査を反映をさせるのかというところを、まずお聞かくださいとの意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"今回のアンケートですが、現在集計中でございまして、今のところアンケートのデータを１０月中旬までにいただくとなっております。現在、障害者福祉課の福祉改革担当で取りまとめているところです。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"自立支援協議会の資料の中にあった１つの部門のところで、専門部会、そこのところで入れるということなのですか。このニーズ調査をどういう形で誰がどう判断をして計画の中に入れていくのかということの説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"福祉改革担当は、障害者福祉課にあるものです。先ほども言いましたけれども、各団体と各相談センターや相談員、そういうところのご意見を反映しながらまた考えていくというふうになります。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ということは、障害者福祉課の職員がこのアンケートをもとにして計画に反映をさせていくという仕組みで、それをもとに骨子案として自立支援協議会に提案をするという仕組みだということなのか尋ねました。","respondent":"中山障害者福祉課長","answer":"アンケートの集計をまとめた上で、庁内の療育支援ネットワークもありますし、自立支援協議会の下に子ども部会というのもあります。そういうところでもご意見をいただきながら取りまとめを福祉改革担当がやるという説明になります。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"せっかくこれだけのアンケートをやるわけですから、そこら辺のところがどう担保されるのかということをお聞かせをほしいと求めました。５日という、この今までの５日というのはどういうことで５日というのが出てきたのか、その考え方についての説明を求めました。","respondent":"中山障害者福祉課長","answer":"平均的なところを見てこの最初の障害福祉計画の中の児童福祉法のサービスについては５日という設定をさせていただいたところです。ただ、そのときから、実際に１０日を超えて必要のあるお子さんについては放課後等デイサービスの受給者証を発行しておりました。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、今お聞きしたのは、今までは上限１０日だったのが上限が外れて基本１０日ということになりました。１人当たり平均５日というのではなくて、もっと多い形で、それを勘案した形で組まれていくのかという考え方の説明を求めました。","respondent":"中山障害者福祉課長","answer":"対平成２６年度比、そこのところについて次期、初めてつくります障害児福祉計画の中にも数値は反映させていくことを考えています。そうしたものと今回とりましたニーズ調査から出てきた意向、それらを合わせまして最終的に数値の目標というのは立てていきたいと考えております。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それを支援するプロセスを組み込むことが求められる」ということで、それから厚労省の通知からしても、していくことが求められていると思うのです。","respondent":"中山障害者福祉課長","answer":"放課後等デイサービスの役割と、あと学校教育との役割、こことの連携ですとか、今できているかというとなかなか難しいところではあります。児童発達支援のほう、やはり療育という他者との関係性ですとか、あるいはお子さんの育ちを支えるために２３日必要と考えています。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このガイドラインの中にも、多分品川区独自のものではないかと思うのですけれども、この１０日の根拠を教えていただきたいというのが一つです。","respondent":"中山障害者福祉課長","answer":"それで、２３日を超えて支給をできるという留意事項の書き方からは、当然読み取れます。ただ、やはりご家庭の状況から、そういうような状況のときにはやはり必要に応じてサービスを出しているケースがあると考えているところです。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その２日の根拠がわからないということでお聞きしていますので、その週２日の根拠を教えていただきたいと思うのです。もともと大田なんかはこういう要綱そのものがないということで言われていましたので、改めて２日の根拠も教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"放課後等デイサービスが放課後児童健全クラブのバックアップ支援体制もやるというような形で留意事項の中では書かれておりますが。五歳児はとにかく毎日就学前ということを意識してきちんとした療育の体制をとる必要があるだろうということで２３日ということにしています。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして健全な育成、そういう観点からぜひ必要な量を支給できるような形での計画にしていただきたいということを強く要望をしておきたいと思います。ガイドラインの中にも事業者の自己評価を行うように求めていますけれども、区にも報告がされているのか。","respondent":"中山障害者福祉課長","answer":"そういう中で、事業所でどういう取り組みをしているか、あるいはちょっと気になることがあったらそういった場面場面でアドバイスなどもしています。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に半年に６カ所もできているということで、しっかりと把握も指導もされて、質的にも確保できるように力をぜひ注いでほしいと求めました。","respondent":"中山障害者福祉課長","answer":"実際にはまず区内の保育園、幼稚園に説明会を行い、その上でモデル的なケースから１ケース始めました。相談の中でこのサービスの説明もしながら、少しでも提供体制が整うように、利用者が増えるように考えていきたいと考えています。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう資格の方が何人ぐらいという体制になっているのかちょっと教えていただきたいのと、保護者からの依頼に基づくという事業です。放課後児童クラブとか、そういう中で品川区としては第５期も未就学児ということで進めていくのか、その点についてもの説明を求めました。","respondent":"中山障害者福祉課長","answer":"開始したときが児童学園のみということで、今、事業所のほうで学齢期に向けても対応しようかなというご相談が来ているところです。要綱のほうは変更の準備を進めているところですので、今委員がご指摘したような年齢というよりは提供場所というような形での変更を予定しています。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これが自分の子どもに合っているかどうかというふうなところでこのサービスを使おうというのはなかなか難しいのかなと思うのです。その点いかがでしょうとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"そうしたときに、そこで療育を受けたいというご希望が実際には多いのかなと考えています。発達に特性のあるお子さん、そうしたお子さんに対する受け手側の支援というのもあわせて、障害福祉政策だけではなくやっているところです。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この陳情は、その中でさまざまな障害のあるお子さんを持った親御さんからのニーズというものが出てくると思うのです。最後の確認なのですけれども、それを勘案した形で見込み量は設定をされていくということで確認をさせてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"冒頭説明させていただいたようなほかのことも含めて、今回アンケートをとらせていただいたニーズも含めて数値に載せていきたいと考えております。先ほど半年で６カ所と言いましたが、児童発達支援が６カ所増えていて、放課後等デイサービスは４カ所増えている状況です。","id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今、いろいろお聞きした中で、今十分サービス量は対応しているということでよろしいのですか。そこと実態の数字というのはどう捉えているのかというのを確認させてください。","respondent":"中山障害者福祉課長","answer":"毎年補正も組ませていただきながら、必要なサービスについては受けていただいている状況です。今現在の平均の数、そうしたものを勘案しながら数値には載せていくので、必ずしもアンケート調査の数字そのままが載るものではないと考えております。","id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今アンケートをとっている最中、集計は終わっていないでしょうけれども、仮で、今現状の段階でアンケート量と実態の数字にどの程度の乖離があるのか、その辺を確認させてもらいたい。","respondent":"中山障害者福祉課長","answer":"アンケートについては、まだ集計が出ておりませんのでちょっと今この場ではご説明できないような状況です。この間だけ見ていても、それを見ながら実際には平成３０年度から平成３２年度の数値目標もつくっていく必要があるとは思っています。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"言えないということが意見陳述を聞くことで明らかになると思うのです。ぜひ私は意見陳述を聞いていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"鈴木（真）委員","kind":"質問","question":"会派の中でもいろいろ検討を先にさせていただきました。最後にちょっとお聞きしたところで、そこに十分対応されているというところから判断して、今回は不採択ということで判断をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"若林委員","kind":"意見","question":"１年１年しっかりとこの量で果たして的確なのか、必要なものについては補正予算を組む、このことをしっかりと繰り返していくことが大事なのかなです。したがいまして、本陳情については不採択ということで結構だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それはそれとしてそのニーズに応えられるという方向をどうつくっていくかというふうなところが、やはり施策としても求められていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"大倉委員","kind":"意見","question":"態度については、先ほど来皆様おっしゃっているように、障害児のニーズを十分把握した計画というのはまさに必要な部分であります。でも、非常に難しい中で行っているのかなということが十分わかりましたので、この件に関しては不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/999880?Template=document&Id=3486#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":49799,"voices":185}},{"id":"h29-20170925-8","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"建設委員会","time":"午前１０時００分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件整理しています。","topics":[{"id":"topic-01","title":"第６０号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第６０号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"そこら辺はここの駐輪場においては、どのように意識をされ、どのような形の駐輪ラックを設置されるのか教えていただきたい。","respondent":"桑波田交通安全担当課長","answer":"駐輪ラックの既に設置してあるところ、そちらのほうに区画線だけを引いて、そのスペースに置いていただくようにするものです。新設する６３台につきましては、こういった大型車にも既に対応できるように、設置幅の広いラックを設置して対応できるようにやっていくものです。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"どのようなことが予想され、あるいは、どのようなことを想定されているのかの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"今回、２カ所の歩道上に設置をしますけれども、まず、駅前ロータリーにつきましては幅４ｍということで場所を確保しております。自転車に関しても、この辺のところは、降りていただいて駐輪するようなご案内も、今後していくように考えているところです。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"２カ所ありますうち西大井広場のところ、先ほども冒頭にお話をしましたように、最近つくられている自転車は非常に頑丈にできております。昔の自転車と違って、そこらあたりに十分配慮しながら計画を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"６３台の設置で足りるのか、どういう方なのか、把握していらっしゃるのか伺います。もう１つは、その教訓はどのように生かしていくのか、また整備計画に反映させたのか伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"大きいものに対応できないものも多数ありますので、そういった方、キャンセル待ちの方は使用できるようになると考えております。歩道上に設置するのですが、また、それを拡大して周りの離れたところも６町会あわせてご説明をさせていただきました。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"１日１５０円かかるとなると、せっかくつくるのであれば、そういった現在の利用者の方のニーズを合わせていく必要が今後あると思うのです。当日利用だけというのは、ちょっと見直したほうがいいのではないかという気もするのですが、そこら辺についてはいかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"あわせて既設の駐輪場も当日利用がありまして、そういったところを既設の駐輪場の中の当日利用も一部定期のほうに変えてやるということで、そういったふうに当日をつくることによって定期の方もカバーするという考えで実施しています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"２時間枠とか、無料枠とかを設けるべきだと思うのですけれども、そこら辺は設ける考えはおありでしょうか。設けていただきたいと思うのですけれども、設けないというのであれば、なぜなのか、その理由も伺います。","respondent":"桑波田交通安全担当課長","answer":"料金につきましては、やはり区営の駐輪場ですので、通勤・通学でお使いいただく方に受益者負担という考えで使用料をお支払いいただくと。こちらは無造作に短時間としますと、本当に真に使いたい、無料ということは現在考えているところではございません。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこの１点確認。何か少し歩行者と自転車をとめる方との事故がないような看板ですとか注意を促すようなことを少ししてほしいと求めましたが、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"既設の駐輪場の中にも当日と定期がありまして、こういったものを改修することによって、キャンセル待ちは解消されると読んでおります。それと、注意喚起ですけれども、こちらについては、看板等を設置しながら注意喚起は図っていきたいと考えております。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"放置自転車に対しての今後の鉄道事業者との協力のあり方について確認をさせてほしいと求めました。改修していく際に、そういった方向で今後やっていくのかどうかという、全体の方向性を確認させてほしいと求めました。","respondent":"桑波田交通安全担当課長","answer":"いろいろ各種キャンペーンや広報活動を通じながら連携を図っておりますので、撤去活動とあわせて、その辺は連携を図っていきたいと考えております。差があるのですが、そういった全体的なものを来年度以降いろいろ調査しながら、どうあるべきなのかというのは考えてまいります。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"利用率が高いというような、今、データが入ってきているということでお聞きいたしました。定期利用、その辺のフレキシブルに対応していただきますように、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"お聞きしたいのは、この増設、６３台とありますが、通勤の方々を対象としたものとして考えているのでしょうか。そこをお聞きしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"定期に入らない、本当に毎日ではなくても週に何回かぐらいしかお使いいただかないという方もいらっしゃいますので、そういった方にもお使いいただけるように考えて計画しています。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"結局そこの対策がされていないから流れてきてしまうということがあるわけではないですか。それから、全体の状況の責任をどういうふうに考えて、放置自転車への対策を考えているのかということをお聞きします。","respondent":"桑波田交通安全担当課長","answer":"ジェイタワーの前だとか、こういったところもやはり放置しているということで、地元の方のお声もいただいております。鉄道事業者も含めまして、そういった問題の共有ですとか、話し合いの場を設けながら対策等も今後も進めていきたいと考えております。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"そうなったときに、なぜあそこを締め出すのですかという話です。自分たちの店に来ているお客さんに対して、自転車対策をなぜとらないのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"そういったものはやはり店舗の顧客の方ですので、その辺のところはお店もなかなかすぐにだめだということは言えないような心境的にはあると思います。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"あそこは３階でしたか、屋上まで入れると３階、それ自体をもうちょっと大きくするとかということは可能なのでしょうか。６３台でオーケーとなるのか、もっと将来的には、あと２００台、３００台という対応をしていかなければならない現状なのか、そこの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"とりあえずは、今、６３台設置することによってキャンセル待ちの方はお使いいただけるようになるというふうに読んでおります。今後、新しいマンションの建設等があれば増えてまいりますので、いろいろな区内の駐輪場の需要等も考慮しながら検討していきたいと考えております。","id":"exchange-013"},{"speaker":"いながわ副委員長","kind":"質問","question":"何点かお伺いしたいのですけれども、有人ではなくて無人のそういった感じのものがここにできるというイメージでいいのかどうなのかということが１点。","respondent":"桑波田交通安全担当課長","answer":"精算するときに精算機にお金を入れていただいて解除されて引き抜くというようなものを入れる予定です。そういったものもありますし、現在実施しています幅を広げることによってスペースをとって出し入れしやすくするようなものがあります。","id":"exchange-014"},{"speaker":"いながわ副委員長","kind":"質問","question":"自重が重いので、自転車もだんだん変わってくる中に対応できる駐輪場に早急にしたほうがいいと思いますので、その辺について教えてください。ご答弁を。","respondent":"桑波田交通安全担当課長","answer":"この写真で入れさせていただいていますこの手前のほう、４ｍと書いてあるこの植栽のところに１台設置するように計画しております。そういったものも含めまして、今後また新しく増設ですとか改修をする際に、そういったものに対応できるように改修していきたいと考えております。","id":"exchange-015"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"公園前の歩道で２カ所端のほうに精算機をつくるというのですけれども、端は端でいいのですけれども、これは１００ｍぐらいあるのですか。僕はわからないですが、そんなにないか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"公園前歩道につきましては、２つ合わせますと全長で６６ｍほどございまして、その手前側のほうの１個と、奥のほうは、この中間点あたりにつけるように計画しております。","id":"exchange-016"},{"speaker":"西本委員","kind":"確認","question":"この地図の中で確認だけです。西大井保育園はここか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"地図が間違っておりまして、申し訳ありません。地図でいきますと、現在は、「森前」と書いてありますこちらのほうに移転しています。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"先ほど、質問で述べさせていただきました。地域ぐるみでという意味での放置自転車対策を心がけて、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"第６１号議案 品川区道路標識の寸法に関する条例の一部を改正する条例","agenda":"第６１号議案 品川区道路標識の寸法に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今後も新たな標識が増えたり、道路が新設されたら、こういった条例改正が必要になるということなのか伺います。これからも頻繁にありそうなことなのかどうか伺います。","respondent":"多並道路課長","answer":"今のご質問のとおり、必要が生じれば、もちろん条例改正が必要です。全部で７０ほど標識がありまして、その中で寸法に関するものということですので、影響としては大きくはないかと思っているところです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"つくり直す場合に、どこの予算で、誰がつくり直すのですかということ。この目的はどういうものをもっての目的があって、品川区にとってどういうメリット、デメリットがあるのかの説明を求めました。","respondent":"多並道路課長","answer":"その標識が寸法で縛っているもののうち、うちの区道に関するものが先ほどご説明した内容です。それが逸脱するということができない場合があるので、そういうものを全体的に参酌して可能にする、そういう内容です。","id":"exchange-020"},{"speaker":"いながわ副委員長","kind":"質問","question":"区民生活にどうこうというものではなく、先ほどちらっと話が出たのですけれども、ここにサイズが書いてあるではないですか。新たに標識番号をつくって、また狭いバージョン用といいますか、そういった標識をここに追加をする感じになるのか尋ねました。","respondent":"多並道路課長","answer":"今おっしゃった形でやるとしますと、条例改正ということで、寸法を変える形で……。","id":"exchange-021"}]},{"id":"topic-03","title":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の追加にあらわれる今の実態として、狭隘な道路に面した戸建て住宅の建替えが進んだ結果ということでよろしいのでしょうか。伺いたいと思います。","respondent":"鈴木建築課長","answer":"今現在のところですけれども、全体のうちの７３％ということですので、木密地域の防災性の向上が進んでいるです。","id":"exchange-022"},{"speaker":"筒井委員","kind":"意見","question":"当初の見込みと比べて６,７００万円増えたということなのですけれども、一見すると、かなり大きな差額に思えるのですけれども、なぜこのような差額というか、予想より差が出たのかということを具体的にお知らせくださいとの意見を述べました。","respondent":"鈴木建築課長","answer":"過去３年間、平成２６年、平成２７年、平成２８年の平均を見ますと、１件当たりの整備費が約８０万円です。これまでの今年度の平均が約１００万円で２０万円ぐらい見込み上がっているというところと、これも４月に上がっているというところも影響しています。","id":"exchange-023"},{"speaker":"筒井委員","kind":"意見","question":"そういったことが過去３年間のデータを見ると、予想はできなかったということでよろしいのかということと、やはり今後の工事にあたり、１件８０万円ではなく１件１００万円ぐらいだという見積もりで今後事業を行っていくのか、この２点をお知らせくださいとの意見を述べました。","respondent":"鈴木建築課長","answer":"過去の３年間あるいは４年間の平均をとってやっているのですけれども、１件当たり１００万円前後の想定で、整備を進めていくということでの予算増額補正です。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"補助２８号線、補助２９号線も含めると、その上でのこの補正予算の成り立ちになっているのでしょうか。その上で今回の金額で今のところはやれるのかというところの見通しはいかがなのか尋ねました。","respondent":"鈴木建築課長","answer":"これはその後、契約ということになりますけれども、おおむね１２月ぐらいまでの見通しはついている。２、３月分について、今年度しっかりやっていきたいというものです。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"ここはいずれ整備しますと決まっているものがあるではないですか。それも１年ではなくて数年にわたっての計画が出てくるのではないかと思うのですが、そういう見方はいかがなのか尋ねました。","respondent":"鈴木建築課長","answer":"やはり１件当たりの規模ですとか、区内の二項道路の３割ぐらいの拡幅が進んでおりますので、要求をさせていただいているというものです。","id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"それと最後に確認は、お金の流れを、歳入のところは所管ではないということなのですが、この必要ですというお金が補正がかけられました。国の補助金ということで申請をするということと、決まってくると入ってくるという、そういう流れでよろしいのか尋ねました。","respondent":"鈴木建築課長","answer":"委員ご指摘のとおり、歳出分、増えた分について、都と国から歳入分が入ってくるというものです。","id":"exchange-027"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"やはり区民の方々が間に入っているわけですから、今後もその場に応じてしっかりやってほしいと求めましたので、よろしくお願いいたします。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"(5)大崎駅西口Ｆ南地区（大崎三丁目地区）再開発計画に関する都市計画案","agenda":"(5)大崎駅西口Ｆ南地区（大崎三丁目地区）再開発計画に関する都市計画案","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"Ａ３の書類のほうの２番の説明会のことで、もう少しお話ししたいと思います。出席者は７７名で、どのような方にどういう形でこの説明会を案内をされての７７名だったのかということをお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"こちらですが、地区内の権利者ということでございまして、土地所有者、それから借地人の方々に対しまして、ご案内の通知を差し上げまして説明会を開催したです。","id":"exchange-029"},{"speaker":"新妻委員","kind":"質問","question":"ここの地区内の全員の方にご案内をしてということでよろしいのでしょうか。それはポスティングか何か、また、書面か何かでご案内をされたということか尋ねました。","respondent":"稲田都市開発課長","answer":"この地区内の権利者の方、それから借地人の方に郵送でお知らせをしております。","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問","question":"ご案内はされていなかったけれども、周辺の方も参加されたということでよろしいのか尋ねました。","respondent":"稲田都市開発課長","answer":"そのとおりです。","id":"exchange-031"},{"speaker":"大沢委員","kind":"意見","question":"全員で７７名ということですけれども、説明あるいは今までの平成１８年からの時系列を追いながら、お答えできなければ結構ですとの意見を述べました。","respondent":"稲田都市開発課長","answer":"私の考えですが、説明等はこのようにやってきているところですけれども、引き続き丁寧に説明は行っていきたいというふうに考えております。","id":"exchange-032"},{"speaker":"大沢委員","kind":"確認","question":"「個々に」か、「個別」という単語が出ていて、この別にも「個々に」あるいは「個別に」ということは説明をされてきたのでしょうか。もう１回、確認をお願いします。","respondent":"稲田都市開発課長","answer":"事業者におきましても、個別に説明をしたり、また、区におきましても、原案説明会を開催前後ですが、いろいろとご心配等が来ておりまして、区や都におきましても説明はしています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"資料についてお伺いしたいのですが、地区内の方が何件何人、地区外の方からは何件何人だったのかお伺いしたいということが１つです。","respondent":"稲田都市開発課長","answer":"都市計画原案の説明を行いましたときに、意見書等で出てきたものの数字ですけれども、全部で３４通の意見が出ております。第１７条に基づきまして１０月１０日に実施するものですが、これは広く区民の皆様方に案内をして、広く意見を聞いていくというものです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"どのような内容だったのかということをざっと教えていただきたいのと、１項を読み上げますけれども、市町村は云々とあって。対象者をわざわざ第１６条第２項として、先ほども伺ったのですけれども、なぜ第１６条第１項でやらなかったのかということをお伺いします。","respondent":"稲田都市開発課長","answer":"第１６条第２項のときの説明会におきましては、先ほども申しましたけれども、高さの関係、それから風の関係等々が出ているです。しっかりと住民の皆様に説明をしてくださいというところで、１６日に、事業者による開発計画の説明会を行ってきたです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"７日、８日のときに、地区内の関係権利者だけを対象にしたのかの理由がよくわからなかったので教えていただきたいというのが１点です。","respondent":"中村都市計画課長、稲田都市開発課長","answer":"このような中では、地権者、当事者への説明が最初というのは、特に問題はないと考えております。こちらを安全に安心なまち、そしてにぎわいのあるまちをつくっていく、西口の駅前にふさわしいような地区にしていくというところでやるものです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"それともう１つは、原案と案、私が伺ったのは、原案が案になれば、より決定に近づくわけです。区民、利害関係者の方も入れるべきではないですかということを伺ったので、答えるよう求めました。","respondent":"稲田都市開発課長","answer":"区でやる説明会が、先ほどもご説明してきましたが、事業者による近隣への説明。第１７条に基づいて１０月１０日に説明して、広く区民の皆様にもご案内して、そこできちんと意見を言っていただくというふうなことでやっております。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、まちづくり、近隣住民に区が責任をもって説明をするというのは１０月１０日が初めてなのではないですか。それで間違いないのですかということを伺ったので、それはお伺いしたいというのが２点目です。","respondent":"稲田都市開発課長","answer":"その後ですが、予測との違い等で対応をしていくというふうな形でやっておりますので、地域の皆様のご不安等に対してはご説明をして解消していくです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"実は私も４月の説明会には参加しましたけれども、個別に事業者が近隣の住民の方に、数人のグループなどにも説明しているという話も伺いました。ですから、そうしたこともやってほしいと求めましたが、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"１０月１０日、説明会を行いまして、また公告・縦覧をして、意見を十分に皆さんから聞いていくという体制です。引き続き、地域の皆様等への丁寧な説明を十分にしてくれというところで指導も区としては行っていきたいというふうに考えております。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"１１月に都市計画審議会を開催すると、これは一旦白紙にしていただきたいと思うのですが、いかがでしょうかというのが１点。具体的に出した意見書は、案にどのように反映されるのか、そこは伺いたいと思います。","respondent":"稲田都市開発課長","answer":"４番、今後の予定ですが、１１月に区の都計審、それから１２月に都の都計審を予定しています。これはあくまでも予定ではありますが、この予定に沿いながら進めていけたらいいというふうに考えております。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"しっかりと変えなくてはいけない案件があると思いますので、意見書は案に反映させてほしいと求めました。長い期にわたるまちづくり、大崎のまちにかかわってくる大問題ですので、ぜひスケジュールありきで進めていただかないよう要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"先ほど、地区内の関係権利者、すなわち土地所有者、借地人の方が２７名いらっしゃるということなのですけれども、今回の再開発に賛成の方は何人いらっしゃるのか、それで、その賛成された方が準備組合を結成されたのかということをお伺いいたします。","respondent":"稲田都市開発課長","answer":"現在、仮の同意率というところでいきますと、２７名のうち２４人が同意をしているというような状況があります。まだ仮という状態です。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"仮ということですけれども、２７人中２４人が賛成をされているということです。同じ大崎地域に住む区民の方ですから、やはり良好な関係をぜひ保っていただきたいと私としては考えておりますので、区のご見解をお知らせください。","respondent":"稲田都市開発課長","answer":"周辺の皆様方には丁寧な説明、引き続き丁寧な説明をして、この計画のご意見等を伺いながらやっていきたいというふうに考えております。今後、基本的には、このような形で説明会としてはこれをやっていくものです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも周辺区民の納得が得られるようなご説明を引き続き何とぞよろしくお願い申し上げます。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"やはり青い地域を考えての中の１つだと思っているので、そういう将来にわたるビジョンについてはどのような考え方をして進められているのでしょうか。お聞きします。","respondent":"稲田都市開発課長","answer":"そういうところで住宅機能をもって、今回、まちづくりを進めていくです。準備組合で検討している段階ではありますが、具体的な取組みは、まだこれから進められていくです。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"そこの進め方については、どのようになっていたのでしょうかということが１つ。その上で、南地区、東地区、北地区の開発を進めていきたいと思うのですが、その辺のお考えはいかがか尋ねました。","respondent":"稲田都市開発課長","answer":"今もしていますが、今回この大崎三丁目地区におきましては、ＪＲ東京支社のほうにも計画等を十分に説明しております。鉄道事業者が対応するというところにはなるかと思いますけれども、安全な対策がとれるよう、ＪＲ等々と協議をというふうに思っています。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"この説明資料の中の２番の(1)、８月７日、８日のことの認識でよろしいのでしょうか。これは大もとの根拠は第２項ですか、第１６条第２項がそうなっているので、そこの法的なところの関係性をもう一度確認させてください。","respondent":"稲田都市開発課長","answer":"第１項が公聴会等を必要に応じてですけれども、先ほども申し上げましたが、事業者、国による説明等も行ってきております。説明もして話を受けるということで、１０月１０日に行うものは、広く区民の皆さんからご意見を伺うというところでやる予定です。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"準備組合の方々が権利者の方々に、どういう条件ですか、どういうお考えですかということを細かく聞いていると聞いております。そこら辺をもうちょっとわかりやすいように区民の皆様方に知らせる方法を今後とっていくべきなのではないかと思いますが、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"権利者説明会を法にのっとりながらやっていって、第１７条に基づく説明会もこの内容です。今後もより一層、地域の皆様には説明会の進め方等におきまして、わかりやすいような説明には努力していきたいと思います。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった意味で、そこは１０月１０日の前にしっかり区としてもっと早くやるべきだったのではないですかということなのです。お伺いします。","respondent":"稲田都市開発課長","answer":"説明会、説明会におきましても説明をして意見をいただき、ご心配やそういうものに対しても十分にこたえてきている。変更する必要があるというところにおきましては、取り入れていきたいというスタンスで臨んでおりますので、問題ないと思います。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"変更する必要がある場合はきちんと変更していただきたい。もしこの品川区の大崎駅のこの１４９ｍ、３９階建て、堂々と説明していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"平成１９年から組織をつくりながらして、地元の皆さんの自発、発意に基づいて行われるのが再開発であります。しかるに、この件に関しては、自民党・子ども未来としては願意に沿うことができないので、これに対しては不採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"新妻委員","kind":"意見","question":"平成１９年から準備組合が立ち上がって、この地元の当事者の方も２７組中２５人が加入をしており、ご説明いただいたとおりであると思います。よって、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"やはり、やはり周辺の方も含めて計画段階から早期に意見を伺いながらしっかりやっていくということがまちづくりの基本だと思います。採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"いながわ副委員長","kind":"意見","question":"今回の陳情に関しては、説明しているということで、不採択にしてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"筒井委員","kind":"質問・要望","question":"良好な区民関係維持のためのご努力はしていただきたいということで、引き続き、丁寧な説明をお願いしたいと考えております。結論としましては、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"そうは言っても、高層ビルが建つのはどうなのだろうか、まちづくりをつくっていくのが最も好ましいことではないかというふうに非常に感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]},{"id":"topic-05","title":"平成２９年陳情第８号 北朝鮮のミサイル発射に対して万全の措置を求める陳情","agenda":"平成２９年陳情第８号 北朝鮮のミサイル発射に対して万全の措置を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"かなり心配されている区民の方々がたくさんいると思うのですけれども、せっかくですから、陳情に至った思いを直接伺いたいので、できれば審査の前に私は陳述を聞きたいと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"大沢委員","kind":"質問","question":"ですから、前ではないということです。今、安藤委員の言ったことには反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"西本委員","kind":"意見","question":"この陳情を受けて、その議論をするということで、さらに説明が必要だというときにお願いするという形になると思うのです。なので、事前に聞くということは、この陳情、流れ、仕組みに関してちょっとおかしいのではないかと思っているので、大沢委員と同じように思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"２項目目の対処法というのがあるのですけれども、ミサイルが着弾した場合の対処法とは何か、具体的に伺いたいと。伺いたいと思います。","respondent":"川部防災安全担当課長","answer":"東京都から示されたときの消防、警察と連携した避難の実施ですとか、そういったものが着弾時の措置としては想定されているところです。２つ目の訓練はいかにですけれども、これも先ほど防災課長が説明したとおり、まずは訓練以前に。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"どういった措置を考えているのか、もう一度お伺いしたいのと、もう一度そこら辺をお聞かせいただけますか。訓練するということか尋ねました。","respondent":"川部防災安全担当課長","answer":"今申し上げたようなＪアラートが発動したときに、どういう措置を一人ひとりがとればいいのかというようなことをお知らせすることを想定しております。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"今、やるべきことで最大の危機は、このケースですと、米朝両国の軍事的緊張が今エスカレートしてしまっている。厳に慎むべきだと思いますし、エスカレートしてしまうということにつながりかねないと私は心配しているのですけれども、いかがか尋ねました。","respondent":"川部防災安全担当課長","answer":"まず１点、確かに直撃してしまえば相当な被害は避けられませんし、人間の力ではどうすることもできないこともあります。やはり区としての大きな責務にあると思いますので、今後そのあたりを肝に銘じて対処していきたいと、このように考えております。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば９条を変えてしまうとか、非核平和都市品川宣言を持ちながら政府に批准を求めるということも言わないとか、私は。そこに注力していただきたいと思うのですけれども、そちらのほうに力を入れてほしいと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問・要望","question":"その１つの手立てとして、それが可能なのかどうか、今お聞きしたいと考えております。これが３点目で、以上３点、ご答弁をお願いします。","respondent":"川部防災安全担当課長","answer":"先ほど来、お話が出ておりますＪアラートが発動した場合の対応ですとか、そういったものがわかりやすく記載されている部分があります。当初はまずは周知というように考えてはありますが、今後の訓練の実施方法等々について研究していきたい、このように考えております。","id":"exchange-064"},{"speaker":"西本委員","kind":"確認","question":"確認だけです。この陳情の文章の中の下から５行目、これは品川区というより国の評価ということかもしれませんが、失敗という認識なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"状況だけお聞かせ願いたいのですけれども、避難訓練を実施したのは秋田県ということで認識をしておりますけれども、それ以外に避難訓練をやったという情報なりは行政のほうでお持ちか尋ねました。","respondent":"川部防災安全担当課長","answer":"正確には政府と自治体の連携訓練ということだと思うのですが、島根県ですとか、各所で政府と自治体連携の訓練は既に実施されているところです。ほかにも最近では、東京都千代田区の小学校でＪアラートが鳴ったことを想定した避難訓練が行われたと、これは報道で認知をしています。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"となると、特別区ということで絞り込んでお伺いしますけれども、今、千代田区の小学校がＪアラートが発令されたという想定で訓練を行った。それのみで認識してよろしいか尋ねました。","respondent":"川部防災安全担当課長","answer":"私のほうも直接各区なりに当たったわけではないのですけれども、今現在、報道されているというところでは、その１件のみかと思います。自治体として、例えば何々区としてＪアラートが発動したときの訓練を行ったというようなことは今まで掌握はしてございません。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、先ほど来のご答弁の中で、まずはＪアラートについて、区民に周知がまず第一義、初段の段階だということで、先ほどのご答弁の中では、まだ全ての部分でしっかりとした対策に対する整備がまだできていないように感じましたけれども。","respondent":"川部防災安全担当課長","answer":"「北海道地方から太平洋に通過した模様です」というような地域的なことをより具体的に文言を改めまして政府の対応としたところです。まず国の対応自体も、検討しながら、このように考えております。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"確かに陳情者の１から４番については、国の危機に関することですから、今の課長の答弁があった。となると、これはまだ、これをさらにブラッシュアップする課題あるいはそのものに対する懸念が数多くあるというふうに認識してよろしいか尋ねました。","respondent":"川部防災安全担当課長","answer":"いろいろとやり方を研究、検討していかなければいけないということは確かなことだと思います。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"こうした生の意見を伺う機会はしっかりと保障していくといいますか、それがやはり議会改革にもつながることだと思いますし、私はぜひ積極的にこうした機会があれば受けていくべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"西本委員","kind":"意見","question":"私も、今回の質疑の内容で、現状、それから課題、これからしなければならないことが、対応していくだろうということも含めて理解した上での結論が出せるかと考えていますので、意見陳述は必要はないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"いながわ副委員長","kind":"意見","question":"国民保護計画があるということを区民の皆様に知っていただくということが大切なところだと考えていますので、それを今後やるという話も先ほどされておりましたので、特に意見陳述を設けるに至らないと私は思いますとの意見を述べました。","respondent":"たけうち委員長","answer":"ご意見が分かれましたので、意見陳述の実施について、挙手にてお諮りしたいと思います。","id":"exchange-072"},{"speaker":"大沢委員","kind":"意見","question":"ほかの部分については、他の１項目、２項目、４項目については、既に区におきまして行っているということです。したがいまして、この陳情については、願意に沿い難い、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"新妻委員","kind":"質問・要望","question":"結論としましては、不採択でお願いいたします。この周知が必要であるというご説明がありましたので、そのことをしっかりと行っていただきたいという思いを込めますが、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから万全の被害予防や被災者救援の対策が求められるのですけれども、人為的に引き起こされるものですから、逆に。区長もこれだけの危機を目の前にしているわけですから、みずから首相に今こそ対話に踏み切るべきだということを米国政府に説いてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"ぜひＳＮＳを含む、ホームページは見なければ見られないわけですから、発信をするということは非常に必要だと考えています。今いきなりこれをやると、まだ時期尚早なのかという部分がありますので、陳情の内容に関しては不採択でいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"筒井委員","kind":"質問・要望","question":"特に２項目目です、区議会だよりや掲示板等々、いろいろな媒体を使って徹底した周知を行っていただきたいと考えております。ということで、採択とまではいきませんけれども、この陳情者の思いを汲みまして、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"ただ、そもそもどういう訓練が必要なのかということが、まだ国として定められているわけではないのではないかというふうに思っています。本当にいいのですかというようなことがありまして、避難する経路がどうなっているのかという細かい準備がやはり必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"新妻委員","kind":"確認","question":"損害賠償額は保険からまかなわれているということを確認させていただきましたが、年間で見ると、この事故の件数は減っているのでしょうか。それとも毎年同じぐらいの事故が発生してしまっているのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"年間によってばらつきがあろうかと思いますけれども、昨年が、車の事故が４件、作業中の事故が２件ということで６件でございました。今年度はすでに、今、車の事故が２件、作業中の事故が２件ということで、そういった意味では、少し増えているような状況です。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"これは修理費だけなのですけれども、けがとかはいかがだったのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"けがの状況ですけれども、当日、救急車を呼びまして病院に運ばれたですけれども、その日のうちに退院した。しかしながら、重傷には至らなかったですけれども、胸の部分を打ったというお話を聞いておりますけれども、全治１カ月ということを聞いてあります。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"この治療費とかはどこで、ここには計上されないのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"その理由といたしましては、通勤の途上だったということで、会社のほうの通勤災害のほうでまかなわれるというお話をされておられました。そのような中で、私ども、示談をしたです。","id":"exchange-081"}]},{"id":"topic-07","title":"平成２８年度指定管理者による管理に対するモニタリング・評価","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"自転車の駐輪場のことでお伺いします。定期が少ないから当日を多くしようとか、逆に定期が足りないから当日を減らしてというような、そういうことは日常行われているものなのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"そういった改修工事も実施しておるところですけれども、そういったバランスを見ながら、各駐輪場のほうで実施しています。","id":"exchange-082"},{"speaker":"新妻委員","kind":"質問・要望","question":"かなり大きなところですけれども、人が周辺に増えたせいか、当日の利用枠が非常に少ないことが見受けられるのです。置く場所はありますので、定期のところをちょっとずらして当日枠を増やしていただく対応をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"ここは定期利用の利用率が非常に低い状況にありますので、その分、当日も多いという状況があります。この辺は指定管理者とも、そういった人員の関係等もありますので、その辺はよく調整させていただきながら検討していきたいと思います。","id":"exchange-083"},{"speaker":"安藤委員","kind":"確認","question":"そこら辺はどうなっているのかと、そこを確認したいのと、これは原因は何でしょうかというのが２点目です。それと、使用料と委託料の関係なのですけれども、お伺いしたいと。","respondent":"桑波田交通安全担当課長","answer":"大型車への対応が増えてきたことによって、やはり自転車の置く場所的に狭くて、使えるような状況が影響して年々下がっているという状況だと思います。そういったことと関連して、現在、駐輪場を広げるような作業を実施しています。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問","question":"すごいことだなと思ったのですけれども、毎日来庁して何をやっていらっしゃるのかお伺いしたいと思います。修繕費の出どころは、そうなると、自分たちでやりくりしているということなのか尋ねました。","respondent":"桑波田交通安全担当課長、長尾住宅課長","answer":"よろしくないことだと思いますし、また委託料につきましても、必要な数だけは指定管理者にはお支払いしてやっているところです。管理運営委託料も同様になっております。修繕のお話ですけれども、この指定管理料の中で組み込まれた形で指定管理者がこの予算の範囲内で行っているものです。","id":"exchange-085"},{"speaker":"安藤委員","kind":"質問・要望","question":"これらの意見や要望を住宅管理に反映させているというふうにあると思うのですが、具体的にはどのような例があるのでしょうか。お伺いしたいと思います。","respondent":"桑波田交通安全担当課長、長尾住宅課長","answer":"その後、時間が経過すれば、お金が課金されていくという状況になっております。本来必要な人が使えなくなるということがありますので、現在のところ、考えていないです。日常的な生活に絡みます生活音に関してのトラブルであるとか、あとは、自転車や駐車場の利用に関してのご意見や苦情等が挙げられます。掲示板等に、それに関しての注意喚起の掲示を貼るであるとか、そういった対応をしております。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"１分でも、入れたら出すときに１５０円かかってしまうという、それは何か工夫できないのでしょうか。いかがか尋ねました。","respondent":"長尾住宅課長、桑波田交通安全担当課長","answer":"それが長期的になってくる、また福祉的な観点の対応が必要である、区の住宅課も協議しながら適切な対応がとれるように連携して動いているところです。今年度にかけまして、上層部のほうも改修していきますので、放置の関係も改善されていくものと見込んでおります。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"最近は１５０円要るのだと思って使っているのですが、可能であるならば、そのぐらいの配慮はしてほしいと思うのです。そこら辺はある程度わかる可能性はあると思うので、そこら辺の考慮はしていただくことはできないのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"５分間無料だったということは把握がないのですけれども、それを使うために持ってきていますので、その辺は注意して使っていただければと思います。","id":"exchange-088"},{"speaker":"いながわ副委員長","kind":"確認","question":"これは、最終的に品川区の所管がそれを確認して、この総括シートに何か書くという感じで流れとしてはいいわけですね。この接遇に関するテストとは何なのですかという。","respondent":"桑波田交通安全担当課長","answer":"１年間の指定管理者の業務報告ということで、そういったものを冊子になっているのですが、こういったものでいただいております。こういったものは利用者への対応ですとか、個人情報の取扱いですとか、サービス向上に齟齬がないように努めるような内容のテストになっております。","id":"exchange-089"},{"speaker":"いながわ副委員長","kind":"質問","question":"要は、テストに１回合格してしまえば、もういいのですねという話にしか見えないのです。その中で１回テストをやって、１年間何もなかったら、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"これは管理員の方が新しく採用になりまして、どこかの駐輪場へ行く。事前の教養で実施されているものでありまして、いろいろな共有についても、逐一やっているところです。","id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594236?Template=document&Id=4212#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":70739,"voices":260}},{"id":"h29-20170925-9","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"文教委員会","time":"午前１０時００分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を96件整理しています。","topics":[{"id":"topic-01","title":"第６２号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第６２号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"今までもそういったものがあったということの確認と、あと、２００円や３００円という額の算定の仕方について伺いたいと思います。","respondent":"有馬学務課長","answer":"ですので、６,０００円を３０日で割ると１日当たり２００円ということで、配偶者は２００円となっております。それを３０日で割ると１日当たり３００円となるものでございまして、子どもは２００円から３００円に引き上げとなります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今回配偶者のほうが引き下げられて、子どものほうが引き上がったというところで、今までに品川区において、この公務災害補償を受けた方はいらっしゃるのか、また対象となる方が何人ぐらいいらっしゃるのか伺いたいと思います。","respondent":"有馬学務課長","answer":"これは以前、平成１３年度までは都条例ということでしたが、その後１件も公務災害に該当しているというものはありません。学校医等につきましては延べで２７０人ほどですけれども実数といたしましては２１５名の方が該当する学校医、薬剤師として働いているということです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"先ほどの説明の中で、大変申しわけないのですけれどももう一度説明していただけないでしょうか。経験年数が１０年から１６年未満と１６年以上ということについては、メモできたのですけれども、それ以降の説明のところの説明を求めました。","respondent":"有馬学務課長","answer":"アの配偶者の２００円というところはよろしいでしょうか。","id":"exchange-003"}]},{"id":"topic-02","title":"第６３号議案 品川区立図書館条例の一部を改正する条例","agenda":"第６３号議案 品川区立図書館条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、現在の大崎図書館は区もご存じのとおり地域の名士の方の邸宅跡を図書館にしてほしいという願いから建物計画などを。現在、この大崎図書館でいろいろ行っています読み聞かせなどは、いつ頃から行っているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"申しわけございません。読み聞かせの開始の記録については、開館当時からおはなしの部屋を用意していますので、開館のときから行われていたものと思われます。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"開館のときから行われていたということで、活発に読み聞かせなどを行っていたと思うのです。やはり子どもたちが日ごろ読書に親しみを持つことを気にかけている区の損失になるのではないかと思うのですけれども、この点いかがか尋ねました。","respondent":"横山品川図書館長","answer":"地域の方が交流するような場所を検討するという形で今進めてきているところでありますし、子どもの事業についても力を入れていく予定です。おじい様、おばあ様、大崎地区については子どもも大人もみんなで楽しめるような施設というコンセプトで進めてきている次第です。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"それだけやはり地域の方々に利用されている図書館をなくす理由は何なのか伺いたいと思います。この多目的室は図書館専用のものになるのか、もしならないとすると、貸室のような扱いということであれば使用が有料になるのかも伺いたいと思います。","respondent":"横山品川図書館長","answer":"産業支援交流施設、ＳＨＩＰが開設したことに伴いまして、北品川五丁目に用地の確保の見込みがついたので移転という形をとらせていただいております。空いたスペースについてはどのように地域の方と運営していくかについて、これから検討を進めさせていただこうと思ってあります。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして、地域の方が求めているのは、現在地に残してほしいということなのです。以前は品川区も改修で予算組みをしていたと思うのですが、移転に変わった理由というのは何なのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"その間、先ほどご説明しましたように北品川五丁目に新しい用地が取得できる見込みがあって。大崎駅西口方面に２拠点をあらたに設けて３拠点で支えるということでは、結果的には大崎地区の図書環境については向上するものと思ってあります。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"新大崎の閉架書庫が３万点ありますけれども、合理的に考えて移転にしたというところをもう少し詳しく教えてほしいと求めました。そして、この分館というのが、本館、いわゆる普通の図書館とどう違うのか、これは図書館法に基づくものなのかも伺いたいと思います。","respondent":"横山品川図書館長","answer":"こちらも全て新・大崎図書館もしくは平塚書庫のほうに移転する予定でございまして、今現在もそうですが、書庫からお出ししてお貸し出しするものです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"最初に分館について、図書館法に基づくものなのかということをお聞きしたので、基づくということでいいのかどうか確認させてほしいと求めました。","respondent":"横山品川図書館長","answer":"それから、また北品川に予定している大崎図書館にも子どものコーナーをつくる、もっと小さなお子さんからご利用できるような施設ということで。区としては基本的には東京都に協力する姿勢ですが、今後の状況を注視していくところと聞いております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"定義づけというのでしょうか、法令上の位置づけがどうなっているのか、今ひとつよくわからないので改めて伺いたいと思います。これら３施設が開設されていく中で、それに合わせて廃館になっていくのか、どういったスケジュールで何が行われるのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"今後のスケジュールにつきましては、来年６月に新しい移転先の大崎図書館が開館する予定です。その間、芳水小学校跡の図書施設の開設予定である平成３１年１月まで、西口の図書環境を支えていくような予定です。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"この大崎図書館では危険性があるということなので、どういったことか具体的に伺いたいと思います。現在、大崎図書館は平成３０年３月末で閉館というと、利用者の方にはそういったことをもう十分お知らせされているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"今、館内でお問い合わせにお答えできるようスタッフにいろいろなお答えをするような文言というか、統一的にお答えできるよう準備をしています。ご了承いただいた段階で、区としてはパブリックに公表できるということなので、こちらについて周知していきたいと考えています。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"この大崎図書館を廃館にして、老朽化に伴って廃館だというふうに主張されているわけですけれども、その点についてもう少し聞きたいと思います。その年限が３０年ということで、あった事例というのはどの程度あるのか、まずそこについて伺いたいと思います。","respondent":"横山品川図書館長","answer":"申しわけございません。具体的にお答えすることはできませんが、区の方針としまして、その現場現場で状況に応じて判断させていただいているところです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"きちんとした答弁を求めたいと思いますので、資料を用意してください。委員長、取り計らってください。","respondent":"つる委員長、横山品川図書館長","answer":"公共施設全体のことについては、所管がまた違うと思います。図書館に関してのことであれば、品川図書館長がお答えできると考えております。では、図書館のことだけでお答えしますと、年次年次で工事および補修に当たっているところです。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"なぜ地下の書庫の部品がないような状況まで放置されてきたのか、どういうふうにそれを見てきたのか、区民は納得しないです。そのところで、そういう経過を図書館としてはどういうふうに見ていたのか尋ねました。","respondent":"横山品川図書館長","answer":"３０年を超えた施設については改修、６０年については建てかえという原則はありますが、古い施設が多くあります。そして、結果として、部品等がなく補修がもうかなわないというところまで使っていたというふうにご理解いただければと思います。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"図書館は区の財産なのですから、区民の方にしっかり利用していただきたいということで、この大崎図書館はとりわけ利用がされていたと。だからここは閉館するしかないのだというのは、冗談ではないと区民が怒るのは当たり前だと思いますけれども、そう思いませんか。","respondent":"横山品川図書館長","answer":"考え方の違いだとは思うのですけれども、それを取りかえる場合には、施設の建てかえ規模の改修が必要になります。ご理解いただければと思います。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"今、品川区は、そういう指導を他の公共施設でも全部しているではないですか。では、なぜ図書館だけきちんとやらなかったのか尋ねました。","respondent":"横山品川図書館長","answer":"それは皆さんに使っていただきたくて大切にだましだまし施設を補修して使ってきたところです。老朽化についてはかなり進んでいる状況でございましたので、今回、このような判断をさせていただいたところです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"ですからそれに応じた適切な維持管理は必要だし、３０年しかたっていないのに使えない、こういうことで済ますわけにはいかないではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"問い合わせに対して答えているというのは説明会にならないのではないですか。説明会だというふうに認識されて答弁されたということか尋ねました。","respondent":"横山品川図書館長","answer":"説明会という形で説明したことはございません。ただ、地域の町会長の集まりであるとか、地域を代表する方の場において、今の状況をご説明するということはしています。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"先ほども申し上げたように利用者の方々、大崎図書館を利用しておられる方々、そして近隣の住民の皆さんに説明会をしたのかということを聞いたのです。それはしていないということで先ほど答弁されたというふうに認識していいのか尋ねました。","respondent":"つる委員長","answer":"そのとおりに聞こえますが、確認しますか。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"私は、やはり地域の住民が、特にこの地域は、地域の住民がつくってほしいと、しかも土地まで提供してくださっています。だからこそ、広くなっても現在地から８００メートルも先まで行かなければいけないようなところにつくっても、そういうふうには思わないか尋ねました。","respondent":"横山品川図書館長、本城教育次長","answer":"委員ご指摘のとおり、大崎の皆さんの熱い思いについては私も何度も足を運んで受け止めているところです。先ほど来、当初から経緯などを何度もご説明しているところではありますけれども、先ほどご説明させていただきました産業支援交流施設。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"長く使うために改修を行いながら、６０年間なり施設をきちんと維持しようと、そういうことでやってこられたではないですか。今後どうするのか改めて聞いたら、会員制のごく一部の人しか利用できないような施設に、そのことについて区の認識はどうなのか尋ねました。","respondent":"横山品川図書館長","answer":"１点目の説明会につきましては、先ほど来ご説明していますように、公表するようにご用意させていただいているところです。２点目のＳＨＩＰの開設につきましては、ＳＨＩＰの開設によってビジネス支援の本を動かすということはご説明させていただいておりません。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"近隣の図書館に行かなければいけない、そういう空白期間があることについてどう考えているのかについて伺います。自分たちの要求を押し通すためにそういうふうな無理を強いていただかなくてはいけなくなるということなのか、区の認識を伺いたいと思います。","respondent":"横山品川図書館長","answer":"地域の皆さんのお声につきましては、先ほどご説明しましたように町会長の会議であるとか、考え方について受け止めているところです。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ここから北品川５丁目に移転しますよ、大崎駅西口に取次所ができますよという説明、それは説明とは言わないではないですか。先ほども何回も言っているけれども、地域の要望が高まってつくった施設をなくしてしまうわけですから。","respondent":"横山品川図書館長","answer":"説明会についてなのですが、区の方針は議会のご審議を経てご了承を得た後、そのことについて皆さんにお諮りするのはこの議会だと考えています。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"ボタンを１つ、区民との関係ではかけ違えたと、そこはやはり認めていくべきだと思います。そういうふうに指摘をしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"こんの委員","kind":"確認","question":"まず確認が１点と、私も坂の多い地域だなと、こうした坂がたくさんある地域というのはより一層親しんでいただくための努力が必要だと思います。それから、分館ですから本館との間をオンラインで、分館で見られるようになっているのかということの３点をお聞きします。","respondent":"横山品川図書館長","answer":"ですのでご不便はおかけしないのですが、そういう意味での連携を他の地区館以上に、一体で運営する予定になっております。本館については館長がおりますが、分館には副館長に当たる者が施設長として赴く予定で、より連絡も強化して一体で運営する形を進めしています。","id":"exchange-025"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。その上で今、非常に借りやすい環境が生まれるのではないかと思うので、この辺のところをより工夫をしていただきたいことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"委員長、ほかになければ質問したいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"この地域は住民の要望がたくさんあったと、図書館がない地域だったので図書館をつくりましたと、そういう紹介もあるのです。","respondent":"横山品川図書館長","answer":"新・大崎図書館でも行いますので、こちらについては同等以上、より充実した形で子ども向けの事業を実施します。一般の図書環境につきましては、分館として図書館法上の図書館ですので、そういう意味では全く同等の機能を果たす形で予定しています。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"おはなしの部屋と児童室がどう違うのかよくわからないのですけれども、そこについてはどういうふうに維持されるのか、そこを伺いたいです。それはついていたのだけれども、今度２つに分かれたところでどのくらい確保されるのか、同等なのか、それを伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"それだったら同等の機能なんて言えないではないですか。その辺を指摘をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"相当地域の方からも要望がありましたし、私どもも近い議員にしても、区長にしても相当な英断・決断があってやっと本日議案が出てきたのだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"意見","question":"それは同等の機能ということはいまだにはっきりできないという状況ですし、しかも説明会もしていないというこういう点は、やはり賛成はできないです。反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-03","title":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今ある施設の定員数を教えていただきたいのと、今度は６人ということなのですが、その辺が２つ目です。この病児保育の場合は、１人当たりの保育室の面積の基準はどうなっているのか、改めての説明を求めました。","respondent":"佐藤保育課長","answer":"武蔵小山の駅前に定員が、今年度４名から８名に定員を増やした医療機関がございまして、全部で今２つの医療機関で実施をしております。実施スペースですが、観察室として大体３.３平方メートル以上の施設が必要ということになっております。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"そして病児保育ですから必ずしも同じ年齢とか乳児に限らないと思うのですが、０歳から５歳までいろいろな子どもが親御さんの就労状況等によって違ってくると思うのですけれども。","respondent":"佐藤保育課長","answer":"６０平方メートルを予定しておりますので、６人定員ですので大体１２平方メートルぐらいあるという形で施設としては十分要件を満たしております。２点目ですが、どちらかと言うと看護に近い面がありますので、児童おおむね３名に１名以上の保育士を配置しております。","id":"exchange-034"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"あるときはサポートするような、結構病児保育はトラブルが多いですから、その辺の対応というのはどういうふうにお考えなのか。病児保育施設が開設したことは、非常にいいことだと思って高く評価するのですけれども、その３点についてお伺いしたいのですけれども。","respondent":"佐藤保育課長","answer":"１点目のキャンセルの関係なのですが、どういったことができるかということを検討したいと考えているのですが、検討する素材がありません。","id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"私はわからないのでお尋ねしたいのですけれども、そういう契約上の、そういった開設期間の契約というのが私はわからないのでお願いします。","respondent":"佐藤保育課長","answer":"医療機関からも１０年以上、２０年近くやりたいというお話がありましたので、適切な年数を設定して長期的に開設していただくように求めてまいります。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"今回、今後も増やしていきたいということですが、具体的な方針として今の段階で言えることがあれば伺いたいと思います。現在の利用状況を教えてほしいと求めました。","respondent":"佐藤保育課長","answer":"３施設ぐらいは必要な状況だと認識しておりますので、今後できるだけ早い時期に医師会等と連携して、病児保育を進めていこうと考えております。２点目の実績ですが、平成２８年度ベースですと２施設で大体８００人ぐらいのご利用があります。","id":"exchange-037"}]},{"id":"topic-04","title":"平成２９年請願第１０号 大崎図書館を２９号線道路のためになくさないよう求める請願","agenda":"平成２９年請願第１０号 大崎図書館を２９号線道路のためになくさないよう求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"利用者の方の意見も聞きながらどうしていくべきかということをしっかりと考えていくべきだったと思いますけれども、いかがでしょうかと思います。","respondent":"横山品川図書館長","answer":"先ほどご説明させていただきましたように区で統一したご説明ができるようにマニュアルを用意してご説明させていただいているところでもあります。２点目の、図書館部局としましては移転を決定した後に行財政改革特別委員会等で検討しております話について伺ったところです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"そして、やはりそうではなくて利用者の方々の願いはこの場所に残してほしいということですから、これは区の姿勢としてどうなのかと思います。利用者の意見を計画段階から聞いていくといったことが必要だと思いますけれども、このお考えを改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者の方に意見を聞いてほしいということでして、そうしなかったために今こういった反対運動、廃止しないでくれということも起きていると思います。しっかりと利用者の方に広くお知らせできる方法として、他の方法も考えてほしいと求めましたが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"地元の代表でいらっしゃる町会長・自治会長にご説明するとともに、従来行っていますカウンターでのご説明、また広報しながわ等でのＰＲであるほか。よろしくお願いします。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり現地での整備を求めているということ、現地での存続という住民の声を区として取り上げてほしいと求めました。補助２９号線道路の関係でも、実質廃館ということになっていく点もどうなのかと、ぜひそういったところを考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"区は議会で都のほうから補助２９号線道路の関係の話があって、ここの表現のところをどういうふうに理解しているのでしょうかというのが１つです。協力していくという形をとりたいということはどういうことを意味しているのかということを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"区が議会で、都のほうから補助２９号線道路の関係の話があって、そういったところに協力していくという形をとりたいというふうにおっしゃった。私は、そうではないのですかと聞いているのです。","respondent":"本城教育次長","answer":"今ご指摘があった部分についてが教育部局の責任でお答えしたことではありませんので、繰り返しになりますが、私どもからの答弁は差し控えします。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"保留しなくちゃいけなくない。関係の部局の担当者をぜひ招いて、午後から調整していただいたらやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"しかも先ほどの説明には、わからないので質問したら担当ではないので答弁できないということであるのだから、この請願審査できないです。だから呼んでいただきたいというお願いを委員長にしているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"補助２９号線道路の関係の話があって、区はこの打診を受け止めて協力をしていきたいという形をとりたいというふうに答弁しているのです。ですからその関係の答弁をできる方に来ていただいて、委員長として判断してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"南委員","kind":"提案","question":"しかし、さきほどの答弁は差し控えたいということなのですから、それが現時点での教育委員会の見解なのだと思うのです。ですから、それ以上のことは聞けないので、関係の担当者に来ていただく、そういう計らいをしていただきたいというお願いなのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"移転が決まれば空き地はできるわけですから、それをどうこう、答弁がございました。このまま進めていくべきだと、議案を通したのだから、必然的にこの請願の答えなんか出ているでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"ですからそこをきちんと聞いて、そうではないのだという具体的な事実を示していただければ納得するかもしれません。それがないのですから、ここに触れざるを得ないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"渡部委員","kind":"意見","question":"誰が聞いてもわかりますよね。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"私の質問は全然解明されません。渡部委員がおっしゃったけれども、その見解とは違うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"だから、同じです。協力していくという形をとりたいというのはどういうふうに区は評価をしているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"南委員","kind":"質問","question":"大事な図書館行政の１つである、運動があってあの図書館ができたという、他の図書館にはない経緯があります。こういう理解を私はするのですけれども、教育委員会の理解とはどういうことか尋ねました。","respondent":"本城教育次長","answer":"もともと図書館長から再三ご説明させていただきましたように、大崎図書館の移転自体につきましては、何回も説明いたしました。そういう意味で、補助２９号線道路と結びつけた移転の判断を私どもはしていないということをご答弁申し上げたところです。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"そういう問題の１つだということを理解して、やはりきちんとやってほしいと求めました。ですから、私は実現できるようにあらゆる力を尽くして頑張っていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"終了していいのですけれども、次に行く前に発言していいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"渡部委員","kind":"質問・要望","question":"平成２６年からいろいろ始まっている中で、私どもの会派としてもこの件については地域の方々からの要望等もいただいて、そして芳水小学校の分館。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"こんの委員","kind":"質問","question":"移転しなければいけない理由、そうしたものが明確に示されましたし、説明を聞いていて理解もできました。ということと同時に、今まで以上にサービスを向上させるという対策も先ほど伺いましたので、この請願に対しては不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"先ほど来の質疑の中でそれぞれいろいろ質問をさせていただいたことが採択する理由ですので、改めて言いません。その理由は明確にするべき、それが付託された議員の責務だというふうに思いますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"松永委員","kind":"意見","question":"移転先付近にもＳＨＩＰが近くにありまして、連携や効率化を考えますと移転する必要があると結論いたしました。そのため不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのときに地域の方々の要望を踏まえ、趣旨採択という形で議会としてのそのときの委員の１人としても考えを述べさせていただきました。地域の方々の要望に対応したことで実現しているということもありますので、移転をするという形で、この請願は不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-05","title":"平成２９年陳情第６号「（仮称）キッズガーデン小山」（小山７丁目）の認可保育園の認可差し止め等を求める陳情","agenda":"平成２９年陳情第６号「（仮称）キッズガーデン小山」（小山７丁目）の認可保育園の認可差し止め等を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"私もこの待機児解消には保育園設置が大切だと思います。","respondent":"大澤待機児童対策担当課長","answer":"当該予定地の１キロメートル圏内において、そのうち５００メートル以内の方は４５名でありまして、保育需要としましては非常に高い地域です。川崎市として不正な請求を受けたこと、あるいは不正な疑いで調べたことはないということを確認しています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"補助金の不正についてはないということですけれども、そうするとこの川崎市で補助金の不正が係争中だということは勘違いだということなのでしょうか。補助金の不正はないということを改めて伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"当事業者は川崎市内にある保育施設の元職員１名から雇用に関して訴訟が起こされておりまして、合わせて書面による説明もいただいております。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"雇用についても今保育園では大変だということですので、そういったところもしっかりと配慮してほしいと求めました。こういった住民の声もまた大切ですので、引き続き住民の方の理解を得られるように努力してほしいと求めましたけれども、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"具体的に次回が１０月下旬、その後隔週での実施を考えているということです。ハード面、運営面も含めて調整に努めて、地域と連携が図れるよう今後も開園後も含めまして事業者への支援・指導をしてまいります。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"もしこの保育園が開設されたとすると、地域の住民の方との関係も子どもたちの成長・発達に影響を与えると思いますので、良好な関係がつくれるように区としても力を尽くしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"こんの委員","kind":"確認","question":"幾つか今のご説明と重なる部分もあるかもしれないのですが、確認も含めてお聞きしたいと思います。区としてはどのような立ち位置で、また区としてはどういうふうに説明の場に臨み対処していくというのが本来行われるものなのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"戸別訪問や説明会など具体的な実施方法や周知範囲について法的な定めはございません。保育所の新規開設のご提案があった場合、区が事業者に対しまして、近隣環境を踏まえて説明などを行うように指導しております。","id":"exchange-065"},{"speaker":"こんの委員","kind":"質問・要望","question":"決まったルールはないといっても、いわゆるこういうふうに近隣の方から説明を求められて、事業者としての説明がきちんと住民の方へのご納得いく合意を得ていくようなことができない場合は、区としてはどのような対応をしていくのが本来。","respondent":"大澤待機児童対策担当課長","answer":"事業者が戸別訪問により実施が適当であると判断しまして、２月から４月にかけて近隣１９件を対象に３回にわたって戸別訪問をしております。","id":"exchange-066"},{"speaker":"こんの委員","kind":"質問・要望","question":"結局説明が欲しいという要望で区が間に入り、きちんと説明会が行われて同席もされたということですから、区としてはどう評価されているか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"当初、２回の説明会を行って事業者としては２回で説明会を終了する予定だったのですが、区のほうから継続して説明会をするように指導しております。引き続いて今後も調整するように、話し合いについては継続するように要請をしています。","id":"exchange-067"},{"speaker":"こんの委員","kind":"質問","question":"その説明会での説明の仕方等で区が口を挟むということは、例えば、その場で説明をするということはあるのでしょうか。いわゆる説明の仕方で、そこはこういうことではないですかというふうに、その説明会の中で区が説明をするという場面はあるのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"基本的には事業者が説明をする説明会ではありますけれども、例えば先ほどの区内の待機児童の状況ですとか、区が答えるべきご質問に対しましてはお答えをしております。","id":"exchange-068"},{"speaker":"こんの委員","kind":"質問・要望","question":"で業者がやはりこの地で保育園を運営させていただきたいという区民の方への説明と、やはりここは業者まかせにだけはしてはいられないというのが１点と、それに対してはいかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"委員おっしゃるとおり、近隣住民の方のお気持ちも大変大切だと認識していますので、できるだけ住民の方の要望には応えられるように話はしています。これからもしていきます。","id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"５回ですか、そういう中でこの事業者の姿勢というのはどのような状況なのか、区としてどういうふうに評価しているのかを改めて伺いたいと思います。そのあたりの考え方も伺っておきたいのと、この際教えていただきたいと、この辺についても教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"事業者としましては近隣の方との検討会の中で妥協点を見出していきたいということを言っておりますので。それははっきりと入園の際にも入園説明会の際にも事業者が伝えておりまして、二度とこういうことがないようにということで申し上げております。","id":"exchange-070"},{"speaker":"南委員","kind":"質問・要望","question":"あるいはオートバイということでいいのかどうか、自転車以外の車両のことを言っておられるのかを確認したいと思いました。品川区も入って、ここも含めてどのような姿勢で臨んでいこうと思っておられるのか、その辺を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"そのためにも地域に受け入れられる保育園となるように、区としましても事業者としましても丁寧に説明しなければいけないと考えています。今、説明の方法についてその方法や範囲に国も都も明確な基準は定めていないのですが、その辺のことは今後検討していきたいと考えています。","id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"品川区の考え方というのをはっきり打ち出していくことが重要なのではないかと考えていますので、その辺の意思の確認をして最後に伺います。","respondent":"大澤待機児童対策担当課長","answer":"まだ具体的には検討してございませんけれども、説明会として開催をしてほしいという要望があった場合は、まだ検討段階ではあります。そして、近隣の方に理解を得ることですが、これは最大限、区としましても努力を続けてまいります。","id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"区がご近所の皆さんへの説明会によるアプローチというか、それについて本当にそこが一番基本だと思うのですよね。しっかりと理解していただけるような姿勢で、まず第一線に立ってやっていただきたいということと合わせて要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"陳情要旨の１番、２番、３番についての説明をいただきまして、そういう状況なのかということでわかりました。南委員やこんの委員の質問を聞いていましたので、説明会をこういうふうにやって検討会も行うという話を伺いますと、通常はどうなのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"説明会の回数としては、今まで区内で私が知る限り一番多かったのは５回です。この件に関しましては今後も継続していく形ということですので、恐らく最高回数になるのではないかと考えています。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはり近隣の地域の方々に愛される施設になってほしいというものであるから、では、そうしたら全て要望を聞いていかなければいけないのかと言ったら。２、３でいただいた部分に関しましては、そちらのほうで審査をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"渡部委員","kind":"質問","question":"この陳情の要旨につきましては都が認可主体であるということと、キッズ・スマイル・プロジェクトの適格性については承知をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"こんの委員","kind":"確認","question":"先ほども確認をさせていただきましたけれども、それから事業者としても住民の方との妥協点もその中で見出しているという姿勢も確認ができました。これについては差し止めてほしいというところでは、なかなか難しいのかなという、一方でそういうことも感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"南委員","kind":"質問・要望","question":"あるいは事業者、ご近所のみなさんに理解していただけるようにさらなる努力をしていただきたいということを意見として付していきたいと思っています。態度としては、陳情者の皆さんには申しわけないとは思うのですけれども、不採択というふうにしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"松永委員","kind":"意見","question":"不採択でお願いいたします。３番に関しても今後説明会を丁寧に行っていくということもありましたことを踏まえ、私たちの会派は、今回の陳情に関しては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３番についてはこれまでも区がかかわってきたということは理解しましたが、最大限努力していくというような今後の方向もお話しされていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"}]},{"id":"topic-06","title":"平成２９年陳情第９号 保育所職員に対しての処遇改善に関する陳情","agenda":"平成２９年陳情第９号 保育所職員に対しての処遇改善に関する陳情","exchanges":[{"speaker":"南委員","kind":"確認","question":"ですから、区としては先ほど答弁されたような足りているという認識にいるわけですから、改めて確認したいのです。平成２７年度には３万８,０００円で、平成２９年度にはいろいろプラスされてそれを超える額となっているのですが、その辺の認識はいかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"平成２９年度、今の年度途中でも突然足りなくなって困ったというようなこともございませんので、一定確保ができていると理解しております。","id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、５対１で基準どおりだからいいということにはならないわけです。基準だからいいのだというふうには、５対１としているからいいという認識でいらっしゃるのかどうか、ここについても伺いたいと思います。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"宿舎借り上げ支援につきましては品川区はかなり柔軟に対応しておりますので、こちらの活用が増えていくような状況です。１歳児が５対１の割合で、それ以外は国基準で言いますと、公立保育園で言いますと大体４６２名ぐらいの保育士が必要になります。","id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"一般企業からやはり一定の割合での格差があるという事実はあるわけですから、品川区は特に今、私立保育園を多く開設するようにしているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"こんの委員","kind":"質問","question":"そうするとどのように捉えていますかとお聞きしたいのですけれども、報道されているほどの実感がないのが現状です。それはどのように、いわゆる、これだけ区としてはしているけれども実感がないということについて区としてどのように捉えていらっしゃいますか。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月に区内で開設する事業者で今もう募集を始めている事業者の初任給の平均が２１万６,０００円で、平成２８年から比べると２万１,０００円上がっておりますので、それなりの成果が出ていると認識しています。","id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"は２番は既にもう５対１になっているということですので、私立保育園などは運営してくださっているという理解でいいのでしょうか。ここの陳情の内容とは違いますが、もう区としてはきちんと手当てをされているということか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"給与額など改善された額について個人別に調査をかけまして今集計中ですので、その集計が出ましたらまた改めてご報告させていただきたいと思います。全事業者がそれでやっていただいております。","id":"exchange-085"},{"speaker":"こんの委員","kind":"質問・要望","question":"引き続きお願いをして、ここに書かれている保育の生活の中での１歳児の動きというのも想像できますので、合わせてその点もお願いをしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"都の補助金により３万８,０００円アップしたところからどういう形で７万４,０００円になっているのかというところをご説明ほしいと求めました。小規模ですとか認証の配置というのも５対１ということになっているのか、そのあたりもお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"小規模の保育士の配置基準は１・２歳児に対しておおむね６人に１人で、園としてプラス１名というのが配置基準になっています。認可とは保育士の配置の計算方法が違います。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"都や国にも求めてほしいと求めましたし、区独自でもやっていただきたいと思うのですけれども、伺いたいと思います。次の報告を待ちたいとは思いますけれども、この調査の中には認証や小規模も入っているのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"調査につきましては認可、小規模、認証の全園を対象に実施しております。認証の配置につきましては、認証保育所そのものは東京都の施策ですので、区として配置基準を変えるというのは今のところ考えてはおりません。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"それは制度上もできないということになるのですか。これは都が担当という話ですが、何か工夫してできるという余地はあるのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"認証の配置基準について区で制度変更できるかどうか、今わかりませんけれども、恐らくできないと考えております。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"認可、認証での保育の格差と言いましょうか、差が出てきているということになると思うのです。認証についてもぜひ引き上げていくというところを考えて検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"渡部委員","kind":"意見","question":"結論を出します。２番は品川区は５対１でもうずっとやってきていますから、もうこれで十分かどうかは別問題としまして、今回の陳情に対しては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問・要望","question":"１番はきちんと処遇改善、それに対して職員の方にどのようにお金が流れているのかのチェックもきちんとしてくださっていることがわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"南委員","kind":"意見","question":"それから２番の人員の配置基準なのですけれども、５対１は都基準なのですけれども、やはり最低基準を見てもっと引き上げは必要です。したがって、これらの陳情内容については支持できる内容だと思いますので、採択をしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"松永委員","kind":"意見","question":"１番に関しては区独自の賃金加算ということでキャリアアップや宿舎借り上げなどの対策を行っているというところです。２番に関しても６対１から引き上げてくださいということで、今品川区では５対１で行っているということで、そうした理由から不採択をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１番はさまざまな賃金加算などをされていることも伺いました。２番のほうは５対１でされているということで、了解をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"}]},{"id":"topic-07","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"待機児ゼロに平成３０年度４月でなる見通しができつつあるというお話だったので、それについて具体的に教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203794?Template=document&Id=4922#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":64492,"voices":301}},{"id":"h29-20170925-5","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"総務委員会","time":"午前１０時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"視察","agenda":"視察","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ここの校庭は人工芝ではないのですか。最近人工芝の張り替えとかがあるのでどうなのかと思ったので、その辺の説明を求めました。","respondent":"小林施設整備課長","answer":"躯体だけでいくと２割か３割かそこら辺、すみません、今の時点でお答えできるのはその程度あります。今検討中です。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点、工事の時にそういった水質の部分まで管理をされているのかどうか、そこを聞かせていただきたいのが１点です。今日伺ったら、くれぐれも注意をして走らせていただきたいと思うのですが、いかがか尋ねました。","respondent":"小林施設整備課長、篠田学校計画担当課長","answer":"プールの水質に関しては、当然最新のものにして、一番メンテナンスのかからないものにするなど工夫して採用しております。特別支援教室ですけれども、３階に普通教室が並んでいるところの中で１教室使うという形になります。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１５ページの給排水設備工事のところに「太陽熱利用設備」とありますが、こういったものは普通に設置されるものなのかどうか。ぜひ新しい施設に関してはエコを重視して取り組んでいただきたいと思うのですが、ちょっと具体的にの説明を求めました。","respondent":"小林施設整備課長","answer":"太陽光につきましては、今のは電気のほうなのですけれども、これは屋上に１０キロワット程度の発電能力のソーラーパネルを設置する予定です。これも屋上に設置します。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今までもどこかで設置されていたのかどうか、費用がどのくらいかかるのか、わかったら教えてほしいと求めました。給食の調理室も地下１階というところではいろいろ配慮が必要かと思うので、その辺がどのように対策がとられているのか、の説明を求めました。","respondent":"小林施設整備課長","answer":"それとあと、非常用発電を今回この城南小学校でも設置をしますので、７２時間の稼働に耐えられる燃料も保管をします。もぐっているところの部分については、そこを空調を通して空気の入れ替えをするというようなことをしております。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"温水にしてほしいという希望もあるので、やはりそういうよいところはぜひほかにも活かしてほしいと思ってちょっとお聞きしました。アリーナのところは、やはり特段の給排気の考えを持っていていただきたいと思うので、これはお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"そして、今日、視察現場で埋蔵文化財発掘をやっていましたが、あの費用というのは別の課から出ているでしょうか。その辺をちょっとの説明を求めました。","respondent":"篠田学校計画担当課長","answer":"は総工事費に関してのご質問ですけれども、今回建築費が約４９億円となっています。それから、埋蔵文化財の経費ですけれども、こちらは教育委員会の予算のほうで実施しているものです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと見解をお聞きしたいのですけれども、この間ちょっと中学生に聞いたら、私立は体育館にエアコンがついている。やはりエアコンは、あくまで今後も区としては導入をしない方向で行くのでしょうか、の説明を求めました。","respondent":"篠田学校計画担当課長","answer":"私どものほうも検討しているところではありますけれども、学校の体育館の施設に関しましては空調設備等、導入をするという形にはなってございません。ですので、今後状況に応じまして、場合によってはそういう対応をとれるようにということで、今行っているところです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区はやはり教育が本当に進んで先端を行っていると思うのですが、やはりこういう子どもたちのことを考えて、また地域の人のことを考えて、やはりそれなりの準備、また設備というのを整えていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"今日、その方針は次の計画でも続けるというようなことを伺ったのですけれども、その辺についてはいかがなのでしょうかというのが１つです。私の図面の読み方が悪いのか、どのように避難経路を想定されての設計なのか、その辺についての説明を求めました。","respondent":"小林施設整備課長、篠田学校計画担当課長","answer":"１点目の雨水利用ですけれども、これは外構のほうで雨水タンクを設ける予定で計画をしております。今のご質問の雨水利用というのも一つの手だと思います。それから一番左のほうの校長室、２階の図面見ていただくと職員室からおりていくような階段があります。こちらのほうと、あとは通常の昇降口とありますので、３方向で外に出られるような形での設計となっています。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"さっき伺えばよかったのですけれども、その辺はこの図面からはちょっと読み取れないのですけれども、工夫はされているのか伺いたいと思います。","respondent":"小林施設整備課長","answer":"それを見ても当然わかりません。１階だとか昇降口だとかいうところにパネルで、どのくらい消費していますよというような装置・パネルを設置して、見える化を図っております。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いつも議会から要望しても、「いや、設置をしないのです」というような話ですけれども、何をそれほど拒んでいるのかなと。もう時代がこういう時代の中で、地域の方たちも、特に災害時のことも心配をしてそういうような要望を常に出されているのかなと思うのですけれども。","respondent":"篠田学校計画担当課長、小林施設整備課長","answer":"仮にお子さん方が増えても、多目的室ですとか、そういった様々な形の部屋を転用して教室等に対応することを考えてありますので。ちょっと補足します。今の備蓄倉庫なのですけれども、地下１階に約４０m2ほどの倉庫を現在計画しております。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"提案","question":"災害時に言われているのが１つは冷暖房の件ですけれども、以前にも提案をしていますけれども、よりよいものをつくってほしいと求めました。これは要望で終わりますけれども、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"先ほど確認すればよかったのですけれども、先ほど城南小学校のあたりは地下で水が出るとおっしゃっていたかと思います。一応の対策はしても、実際稼働させてみると何か結構かびの被害が出たりということを私自身も経験していますので、その辺どうなのかの説明を求めました。","respondent":"小林施設整備課長","answer":"水位が高いのですけれども、当然設計の中ではその止水だとか防水だとか断熱だとか、そういうのを含めて計画をしております。それを循環させて、湿気をなるべく外に持っていくというような空調をつけたりだとかして、検討して設計を今回進めたところです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"特別支援教室なので、この横長のずらっと教室が並んでいる動線の中で、できるだけ真ん中にしてほしいという希望が結構出ているのです。だから、もうこの段階なのですけれども、その辺が具体化されているのかどうか、１点お伺いします。","respondent":"篠田学校計画担当課長","answer":"特別支援教室に関しましては、まず教室の仕様は普通教室と同じものという形で考えてあります。ただ、これは学校運営上、実際に建物が開設されてから改めて整備をするのですけれども、基本的な考え方はそういった形で運営されることと考えます。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"もう一点、車椅子利用の児童の方のためのルートはどうなのかなという説明をしてください。エレベーターはあるのですけれども、その辺のバリアフリーの考え方の説明を求めました。","respondent":"篠田学校計画担当課長","answer":"一般のお子様に関しましては正門を入ってから階段を上がって２階の昇降口という形になりますけれども、その昇降口がある２階のバルコニーといったところがあるのですけれども、そこからエレベーターで上に上がれるような形での位置づけとなっています。","id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"質問","question":"８ページの躯体工事の改築工事のほうの入札なのですけれども、これは一般競争入札で３者で入札で、２者が辞退をして１者のみということ。","respondent":"立川経理課長","answer":"辞退理由ですけれども、１者が都合によるということでございまして、もう一者が予定価格を超過しているです。現在、オリンピック・パラリンピックが２０２０年に開催されるということがあって、区としては大変ありがたいと考えています。","id":"exchange-016"}]},{"id":"topic-02","title":"第６９号議案 天王洲公園ＡＢ面他改修工事請負契約","agenda":"第６９号議案 天王洲公園ＡＢ面他改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"そういう意味で、駐車スペースというのはもう少し何か工夫できないのかと思うことがあるのですが、いかがでしょうか。ちょっとご見解の説明を求めました。","respondent":"溝口公園課長","answer":"そういった中で駐車場ですが、やはりこれだけの運動施設を維持しながら、新たに駐車場を整備していくというのはなかなか難しいのが現状です。自転車等を使っていただくなど、そういったことをしていく中で、皆さんに快適にご利用していただけるようにしていきたいと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"あそこはなかなかいい場所で、お子さんたち、家族連れが散策するというところで、天王洲が日曜祭日などなかなか賑わっているような状況になってまことにうれしい限りなので、何かいい方法がありましたら、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"この間、区の施設ではないのですが、人工芝にしたらとても上が暑いと。そういう選択肢があるのかどうか、どのくらいのランクのものを選んでいるのかというあたりを、わかったらの説明を求めました。","respondent":"溝口公園課長","answer":"いろいろな人工芝の種類がありまして、芝生の長いものから短いもの、そういったものによっていろいろ変わってくるものと考えています。使用実績におきましては神宮球場とか、皆さんにスポーツを楽しんでいただく施設にしていきたいと考えているところです。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"今、老朽化に伴いというようなことでしたが、今までの人工芝よりもグレードを上げたと理解してよろしいのでしょうか。どれぐらいでまた張り替えの必要性が出てくると考えられたのか、その辺の見込み、計画があれば伺いたいと思います。","respondent":"溝口公園課長","answer":"人工芝が設置されてから１５年以上経過しているということで、使い方によってもいろいろ耐用年数は変わってくると考えております。ですけれども、今回も大体同じような１５年、または２０年ぐらいは使えるような形の人工芝を選んで、今回施工するものです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"もう１個、この透水性ＩＬＢ舗装が２７m2と、図面で見るとここだけということなのですが、これはどういうもので、どういう目的でこういう舗装をここだけするのかの説明を求めました。","respondent":"溝口公園課長","answer":"ベンチ等そういったものを今回新たにスタンドベンチを設置するところも出てきている現状ですので、それを復旧するところだけをＩＬＢ舗装として直すということで、必要最小限のところだけを施工するという形での工事を予定しています。","id":"exchange-021"}]},{"id":"topic-03","title":"第７０号議案 書架・カウンター等の買入れ","agenda":"第７０号議案 書架・カウンター等の買入れ","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"カウンターは大体イメージがわくのですけれども、どの程度の規模か書架について教えていただきたいのが１点です。芳水小学校の分館についてはここに含まれているのか、いないのか、の説明を求めました。","respondent":"立川経理課長","answer":"書架について説明いたします。続きまして、分館につきましてはまた別途提案するのですけれども、今回は新大崎図書館に関連する書架・カウンター等に限定されるものです。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっとイメージがわかないので、既存のところでいうとこの程度という規模があったら教えてほしいのです。特別な新しいタイプの書架ではないということなのか尋ねました。","respondent":"立川経理課長","answer":"イメージとしましては、１フロア１,５００m2、そうした中に書架を配置していくです。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"２７ページのところで、そちらのほうが利用しやすいのだったらそちらを選んでいたのかどうか、その辺をちょっと詳しく教えていただけますか。","respondent":"立川経理課長","answer":"いわゆる新しい図書館のレイアウトに合わせて、もう既に製品を選定した上で棚割りというのを確定します。ですから、入札に際しましては全てメーカーとかを特定した段階で、それで金額勝負してもらうです。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜなら、大崎図書館を現地でそのまま残してほしい。北品川の地域に新しい保育園を求める意見がたくさんあるのと、充実をするといった意味で、この議案に対して賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田委員","kind":"意見","question":"大崎図書館の移転については手続き的にそもそももう少ししっかり地域の人たちの意見を聞いて、手順を踏むべきだということで、疑問を持っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"人件費についてなのですけれども、様々な職種の方がかかわっているわけですけれども、この積算をしていく段階で、最低賃金のところがきちんと保証されているといった根拠というのは、区はどのように把握をされているのか、１点教えてほしいと求めました。","respondent":"立川経理課長","answer":"予定価格を算出するに際しましては、国が示します設計労務単価の最新のものをまず確認いたします。予定価格につきましては、国・都が示しました労務単価に沿って適正な価格ということで決まっているところです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"確認","question":"当然のことと思うのですが、そこの根拠はそうなのですが、区としてどこの段階でその辺がきちんと価格を積算するところで使われているか。そこのチェックというのは、区も同じことをやって確認して正しいと評価をするのか、そこのところの説明を求めました。","respondent":"立川経理課長","answer":"入札に際しましては、いわゆる積算の内訳というものを出していただいておりますので、当然その辺をチェックしまして、いわゆる労働者の賃金、下請けの支払いにつきまして適正であるかどうかというのを事前にチェックしています。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"そこで、１つここに書かれている会社が直接する部分ではなくて、一次、二次、三次とか下請けに出す場合の最低保証のところは、どこでどう把握するのかもの説明を求めました。","respondent":"立川経理課長","answer":"下請けがある契約につきましては、いわゆる工事全体の施工体制台帳というものを出していただきまして、そこでそれぞれ下請契約の金額等をこちらに提出していただいておりますので、当然その積算についてもチェックしています。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きちんと行っているかどうかというチェックを、やはり事業者任せではなくて区のほうでしていただくような仕組みにしてほしいと思っています。一般区民の方の貸し出しの利用料というのは、どこと比較して決められているのかわからなかったので、わかったらの説明を求めました。","respondent":"立川経理課長、松山高齢者地域支援課長","answer":"そこについては事業者のほうに働きかけをまた強めていっているところです。契約制度の中でどういった工夫ができるのか、そういうことにつきましては当然研究していかなくてはいけない課題と考えております。委員お尋ねの一般区民の利用料についてですが、こちらの施設の位置づけについて、今検討を図っているところですので、また利用料につきましては、決定次第お示しさせていただこうと考えています。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"何か非常に違和感を覚えるのですが、これはどういうふうに我々などが理解すればいいのでしょうか。全く同じ額もあるというのは何か不思議な気がするのですが、これに対して我々はどのように思ったらいいのか尋ねました。","respondent":"立川経理課長","answer":"入札金額につきましてはご覧のとおりです。接近している理由ですけれども、そうした積算に使うソフトが同じだった場合には、同じ金額になることもあり得るのかなと考えているところです。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"以前も聞いたことがあるのですが、区としてはこの予定価格を出すにあたって、どのように積算して、入札予定価格を決めているのですか。ちょっとそれだけの説明を求めました。","respondent":"立川経理課長","answer":"予定価格につきましては設計事務所が設計をして、そこで金額をある程度出しています。","id":"exchange-032"},{"speaker":"須貝委員","kind":"意見","question":"最後に１点だけ。資本金がかなり違っても同じだというのは、一般の区民から見ても非常に違和感を覚えますので、それだけちょっと一言言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"この図面で、私たちはいろいろな場面でユニバーサルベッドを求めているのですけれども、そういう設備があるのかどうかということが１つです。２階からの非常口というのは、１階の非常口が、どこから出るのか教えてほしいと求めました。","respondent":"小林施設整備課長","answer":"だれでもトイレの備品関係のお話ですけれども、ここについては委員のおっしゃった多目的シートについては設置をする予定です。ほかにオストメイト、洗面所、あとベビーチェア等を設置する予定です。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"では、１階のテラスはそこから出られる窓ということですよね。一般的に掃出し窓というか、そういう感じに理解してよろしいか尋ねました。","respondent":"小林施設整備課長","answer":"はい、そのとおりです。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"確認","question":"すみません。６ページの図面を見ますと、これはソーラーパネルなのかどうか、確認させてください。","respondent":"小林施設整備課長","answer":"別途電気工事の中で、屋上にソーラーパネルの設置を予定しております。","id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、これ、ソーラーパネルは建物の中のどの部分にソーラーパネルによる電気供給をするのか。わかる範囲で結構ですのでの説明を求めました。","respondent":"小林施設整備課長","answer":"通常ソーラーパネルを設置しますと、電気照明の補助等に使っておるところが一般的です。","id":"exchange-037"}]},{"id":"topic-04","title":"平成２９年請願第６号 固定資産税及び都市計画税の軽減措置の継続","agenda":"平成２９年請願第６号 固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"毎年このように意見書を出していますけれども、何とか恒久的になるような方向がとれればいいと思います。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"平成１４年度、区の認識はどうなのかというところをちょっと、区のその辺の認識をひとつお伺いしたいです。","respondent":"伊東税務課長","answer":"マクロ経済の認識ですけれども、先日１月とか４月時点の調査によりますと、地価のほうは若干上昇傾向にあるというような調査結果があります。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に中小、小規模の事業者の方々には本当に厳しい中頑張っていただきたいというところにおいては、この願いを届ける機会ではあるのかと受けとめました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"漠然としているので、職場によって多い順に１位から５位ぐらいまで、職場とどのくらいの人数がいらっしゃるのか教えてほしいと求めました。やはりこの辺がわからないので、ぜひお願いいたします。","respondent":"黒田人事課長","answer":"教育ですと教育支援相談員が２４名ですとか、学校の専科の指導員が３５名など、そのようなところが多いです。それからあと、清掃事務所の資源回収監視員とか清掃リサイクル指導員を合わせて３６名おりますけれども、こういったところが多い職場となっています。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"それぞれの職場はわかったのですが、職種はどのような職種なのか尋ねました。","respondent":"黒田人事課長","answer":"専門職員のほうは５５の職種がございまして、無資格者という形に分けてございまして、非常勤の職として１３ほどあります。保育士資格を持っていなくても補助という形で、無資格者ということで非常勤として雇用している場合もあります。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"正規職員とほとんど同じ仕事をしていて、均等待遇の対象者になってよい立場の人は何％ぐらいいるのですか。専門非常勤は１,４００円、一般非常勤が１,１４０円で、１０年間据え置きでいる理由がわからないのですが、その理由の説明を求めました。","respondent":"黒田人事課長","answer":"職によっては３時間ということもございまして、基本的な認識として、一般職員と全く同じ勤務というものはございません。３類で１,１０７円ということありますので、説明の中で申し上げましたが、報酬の水準については適正であると認識しているものです。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"正規職員と非正規職員が決定的に違うのはどの辺か教えていただきたいのと、例えば今回最低１,５００円以上にすることを求めると書かれているのですが、そのところもの説明を求めました。","respondent":"黒田人事課長","answer":"いわゆる時間には換算できない仕事も担っているという意味では、同じ労働条件というのはなかなか比較は難しかろうと考えているものであります。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"なかなか仕事の中身が時間では言えないという、それは専門的なところを担っている正規職員ならではのところは当然あると思うのですが、正規職員と大体同じぐらいの時間数を働いている方々は、この１,３００人のうちどのくらいいらっしゃるのか尋ねました。","respondent":"黒田人事課長","answer":"先ほどの答弁を少し繰り返しますが、同じぐらい働いている方はいないというものです。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２０１６年の正規職員のところで、東京都の春闘共闘キャラバンで自治体に求めた数字を集約している報告書、２０１６年正規職員数２,５６３人。お伺いすると、やはり還元をするべきであると思うのですが、その辺はいかがか尋ねました。","respondent":"黒田人事課長","answer":"プラス３１人ということで、当然人件費の部分が変わってまいりますので、そこで下がってくるということはあろうかと思います。今、経験を若い職員に伝えるということもしていますので、そういった中で正規職員と非常勤職員の役割分担で業務を担っていると認識しているものです。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"退職者と新規の差はどうなのですか。退職した分、採用がされているのかどうかというのを私は今ここで述べたので、比較するのだったら同じように比較してください。","respondent":"黒田人事課長","answer":"退職の人数につきましては手元に数字がございませんが、基本的には事務事業見直しをしまして、そこに必要な人数を採用しているですし、そういった中でいろいろ工夫を図って事業を執行しているというものです。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"ちょっと自分で知識が足りないものですから、今のご説明に加えて伺いたいのですけれども、請願の中に学校事務非常勤職員というのも出ています。学校事務非常勤職員というのはどういう仕事で、どれぐらいいらっしゃるのか教えていただけますか。","respondent":"黒田人事課長","answer":"いわゆる学校事務につきましては、いわゆる都の職員が学校事務でおりますので、区の関係につきましては非常勤職員を置いて、学校のそういった事務を行うということで、平成２９年４月１日現在で５２名ほどいらっしゃいます。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"どう聞けばいいですかね。例えば５年以上継続している人とか、そういうのがわかりますか。","respondent":"黒田人事課長","answer":"基本的に任用は１年ごとですので、繰り返し任用しているというところについては把握してございませんので、お尋ねの件についてはちょっとこちらでは承知していないです。","id":"exchange-049"},{"speaker":"須貝委員","kind":"質問・要望","question":"この最低賃金は、地域別に賃金改定しているわけですから、区内で働く非常勤職員の方の最低賃金も私は自然と上がってくると思います。ですが、やはり非常勤職員の方も少し我慢をしていただいて、民間がその賃金を出せるような時期まで辛抱していただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"あくつ副委員長","kind":"質問","question":"それと、常勤の方の給与も時間で割り返してみると、この非常勤の方たちとそんなに変わりはないということ、それはよくわかりました。具体的にはそれはどういう背景で、平成３２年度とおっしゃっていましたけれども、もう少しわかりやすくお願いします。","respondent":"黒田人事課長","answer":"この法律は本年５月１２日に公布されまして、地方公共団体における行政需要の多様化等に対応して、法改正したです。この辺につきましては、説明の中でも申し上げましたが、現在２３区全体で検討を進めているというものです。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"すみません、もう一点だけ。専門非常勤職員の内容をわかりやすく教えてほしいのと、フルで１週間は働けないけれども、この低賃金で使うというあたりも聞かせてください。","respondent":"黒田人事課長","answer":"あくまで専門非常勤職員につきましては職を規定してございまして、先ほど申し上げましたように５５の職務があります。報酬額につきましては、その職の専門性が高い者については報酬額の設定も違いますので、そういった中で職種に応じて設定しているというものです。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"戸籍のところと税務のところだけだったのですが、もうちょっと区民と接点のあるところはどのようなものがあるのか教えていただきたいです。そういうことだと、この１,４００円が妥当であるとお考えでしょうか、お尋ねします。","respondent":"黒田人事課長","answer":"介護認定調査員も専門非常勤職員ということでございまして、様々な職場で専門性があるものについて職を設定しているものです。１類の職員の初任給を時間で割り返しますと大体１,３８０円ですので、１,４００円という報酬の設定については適正であると考えています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"意見","question":"時間に直すと適正ということですが、様々な待遇の面で大きな差がある中で、この時給だけ比較して妥当であるというのは、私は違うと思います。この賃金が非常に安いという訴えが届いていますので、このことはしっかりお伝えをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"先ほど聞き忘れました。一般非常勤は１,１４０円が最低額とお聞きしたのですが、１,１４０円というのは最低ということだと思ったのですが、その辺はいかがか尋ねました。","respondent":"黒田人事課長","answer":"例えば１,５００円の設定をしていますし、これはちょっと勤務日数から割り返していますので少し端数が出ますが２,６１５円ということで、それぞれその職に応じて設定しているというものです。","id":"exchange-055"},{"speaker":"高橋（伸）委員","kind":"意見","question":"結論を出すでお願いします。平成３２年４月から新しく改正された法律が施行されるということで、今回の請願については不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"私も勉強したことがありますが、先ほどの議論の中であったとおり、なかなか難しい問題をはらんでいるということがあります。どこまで反映されるかというところで、反映をしていただきたいということを望みまして、この請願に関しては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大事な区政を支えてくださっている非正規職員の待遇改善、均等待遇というところをもう少しきちんと実態を調べて検討していただきたいと思うのが１点。賃金、時給ですから、妥当な金額であると思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（し）委員","kind":"意見","question":"それと、給与体系等については法改正があったのと、それに伴って区としても検討をされていくということ。正規職員の給与がマイナス改定をされている時に、我々としては今回のこの請願に関しては不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"須貝委員","kind":"意見","question":"結論を出すということと、先ほど申し上げましたが、東京都内の最低賃金が今度時給９５８円に改定されます。おのずと品川区で働いている非常勤職員の方の賃金も上がってくると思いますので、それまでは我慢をしてほしいということで、今回は不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"この趣旨はとても理解するのですが、今売り手市場というのでしょうか、労働者のほうが足りないという中では大変厳しい状況があるのも実態なのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2086#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":41488,"voices":223}},{"id":"h29-20170926-6","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"区民委員会","time":"午前１０時００分～午後 ０時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"人数について把握しているのかを伺いたいのですが、それと公益財団法人品川区スポーツ協会、それぞれ品川区からの天下りは現在何人在籍しているのか。人数を伺いたいと思います。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"区のＯＢ職員という捉え方ですけれども、１名です。文化振興事業団につきましては、ご質問にあった管理職ということで言えば、４名です。スポーツ協会におきましては、区のＯＢ職員ということに関しましては、８人です。管理するところでは、非常勤、常勤含めての数字です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ１人、４人、８人と、管理職のＯＢということでよろしいのでしょうか、確認させていただきたいのですけれども。","respondent":"池田スポーツ推進課長","answer":"大変申し訳ございません、管理職ですと、２人です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"私は、区民の理解も得られないし、やめるべきだと思うのですけれども、その点いかがでしょうか。２つの部と３つの課に分かれているので、誰にまとめてその考えを聞いたらいいのか聞きにくいので、３つの課それぞれに伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いたいのですけれども、例えば公益財団法人は公益性が高く、独立性も高い。そこもご説明ほしいと求めました。","respondent":"安藤文化スポーツ振興部長、堀越地域振興部長","answer":"決算もそうです。しっかりコンプライアンスと申しましょうか、法令順守のもとに運営しているということで、それで問題ないと考えています。私どもで何かルール化等について答える立場にはございませんので、評議員会等を経て、しっかりとチェックを果たして運営されているです。そういった意味で、適切かつ公正に運営されていると認識しています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"年間の決算と予算についての中身であって、そこは少し違うのではないのかなと思いますので、改めてお伺いしたいと思います。いずれにしても、チェックする側とされる側が、このような関係を続けているというのは問題だと思いますので、この点は改善を要望したいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"理事会の理事については、評議員が決定するという決まりになっています。それと、決算と人事の理事のほうです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"それならば、業務の１つなのですから(6)として書けばいいではないですか。それと、スポーツ協会も書いていないから、その他区長が必要と認めた業務は入っていないのですかという質問。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"例えば創業支援の支援メニューで、あるいは同時に、武蔵小山創業支援センターでは女性の創業支援などに取り組んでおりますので。政策等と連携するような場合には、その他区長が必要と認めた業務ということで、連携の業務をお願いする場合があるので入っております。指定管理業務の概要としましては、区と連携した形でやることはありますけれども、こちらの総括にはそういった形で載せていないということです。","id":"exchange-006"},{"speaker":"藤原委員","kind":"確認","question":"それと、地域振興部長にお伺いしたいのですけれども、あえて伺いますが、ビジネスクラブの利用率はすばらしいではないですか。その施策に対する利用率の評価を部長としてはどう考えているのか、その辺についてお伺いさせてください。","respondent":"池田スポーツ推進課長、堀越地域振興部長","answer":"平成２８年度につきましては、かけっこ教室や子ども向けの教室などいろいろなことをやっておりまして、事業自体は区民の方に喜んでいただける形でどんどん増えている状況です。ですので、まとめますと２点あって、貸しホールとしての評価は非常に高いということ。区からもしっかりと申すことは申して、かつ連携するところは連携してやっていきたいと思っているところです。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"あえて部長に伺ったのは、部長はいろいろな課の部長ですから、利用率の数字が区民に評価されている。もう一つ新しく質問をするならば、今日の本題とは違うかもしれないけれども、どう考えていくのかということを答弁していただければ幸いです。","respondent":"堀越地域振興部長","answer":"答えになっていないかもしれないのですけれども、きゅりあんもそうですけれども、基本的にはこれは非常にいい結果が出ていると思ってあります。","id":"exchange-008"},{"speaker":"塚本副委員長","kind":"確認","question":"予算額が余りましたということで、これは平成２８年度だけではなくて、平成２７年度や平成２６年度もそうだったのか。平成２８年度になって、そういうことに至ったということなのかということを最初に確認したいです。","respondent":"鈴木文化観光課長","answer":"基本的には、毎年少し余裕が出た場合には、返還というのは継続しております。すみません、今、手元に資料がないので具体的な額はお答えできませんが、毎年度、余裕が出た場合には返還ということでお願いしています。","id":"exchange-009"},{"speaker":"塚本副委員長","kind":"意見","question":"それに対して、指定管理料の返還になるのか、あるいは利用料を下げるという考え方も、運営の中ではあるのではないかと思うのですとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"これは最初に提案いただいたときに、予定する５年間の毎年の指定管理料の提案をいただいておりますので、基本的にはその額になります。それから、単年度で利潤が出たのでそれを使用料を下げるところに還付するという仕組みにはなっていないところです。","id":"exchange-010"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"このようにいろいろしている中で、なぜお神輿の写真を使ったのかをお伺いします。それと民泊について１点、生活安全担当課長にお伺いしたいのですけれども、全てがよしという形ではないと思うのです。","respondent":"鈴木文化観光課長、菅生活安全担当課長","answer":"年１２回の予定の半分を実施しているのですが、最初の写真の３回で、五千件程度。１万から１万２,０００件のアクセスをいただいたということで、その中で特に注目度の高かったお祭りの写真を載せさせていただいたです。委員ご指摘のとおり、企図している者が実際に民泊に泊まることも想定されておりますので、そういった問題があるのかなと考えております。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう一点は、あえて生活安全担当課長にお伺いして、このような課題がありますということを何点か答弁していただいたのです。それを伺って、課長はどのように思われるか。","respondent":"鈴木文化観光課長","answer":"先ほど口頭でご説明しましたように、９月８日に国の連絡会議がございまして、課題への対応についてもある程度の方向性は示されております。都への要請なり、意見調整も含めて、しっかりと対応したいと考えております。","id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"伺いたいのは、同性同士のダブルルームを拒否しないということを確認しているのかどうか、そこを伺いたいと思います。品川区内の４８施設は、同性同士のダブルルームは拒否しない、ウェルカムだということを確認しているのかどうかご質問したいと思います。","respondent":"鈴木文化観光課長","answer":"先ほどご報告した区内施設の状況です。観光振興協議会と国の調査の中で把握した情報でございまして、ご質問のＬＧＢＴ等の対応の可否については、これまでまだ調査をしておりません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"こういうことになっていますよ、拒否してはいけませんよということをお伝えすることが必要ではないかと思うのですけれども、お伺いしたいと思います。品川区としてこのような事業を進めていくわけですから、２点、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"旅館業法に違反ということが判例的に確定しているわけではございませんが、考え方として、やはり対応が必要ということは区も理解しております。皆様からも意見をいただきながら、今後、区内でしっかりとした対応ができるように情報共有や対応を検討したいと考えております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひいろいろ取組みを進めていただきたいと思うのですが、１点だけ。先ほどの答弁ではその辺がはっきりしなかったので、その点だけ確認させてください。","respondent":"鈴木文化観光課長","answer":"区でも人権を担当する所管がありますので、そこから正式に区でこのようにと言うのは、私の範囲ではないのです。ただ考え方としては、委員もおっしゃったように、そのことだけでの拒否というのは適切ではないと区でも認識しているという意味で申し上げました。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"旅館業法を取り扱う課ともよく確認、そこは確認してほしいと求めました、これは要望です。規制緩和ではなく、しっかりした安全ルールの確立が必要だと思っているのですけれども、その点についても区の問題意識をお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"今回の住宅宿泊事業法の規定では、以前の旅館業法よりもかなり条件等が緩和されて民泊事業が実施できるようになっております。の条例制定等も手続きがありますので、現実的には、民間が通常の事業として実施するほうがスムーズに移行できると考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"その点について、区はどのように考えているのか。区としての条例は考えていないというお話ですから、そういう住民の不安や旅行者の安全確保についてどのようにお考えなのかお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"防災面、衛生面については、具体的に今検討しているガイドラインの中で規定を予定しているそうです。区もそれに準じて、しっかりと区の権限の中でできることについては対応したいと考えております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"観光を楽しめるように、レインボーフラッグを掲げることや、宿泊施設との調整や理解を広げていくことを求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"田中委員","kind":"意見","question":"区内で事業開始に向けた準備を行っているという部分なのですが、地域の方からは不安の声が上がっているのです。事業者が民泊を始める前に、近隣住民への説明がどのように行われるとか、そのような具体的なことは何か決まっていますかとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"先日の説明会では、それから近隣の方への説明についても、そのような指導をするというところは方向性として聞いています。政省令にしてもガイドラインにしても今検討中で、そのような項目については認識をして、検討しているというところまでの報告だったので。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"住民の方たちが納得するようなちゃんとした説明と、民泊が行われる前にきちんと話し合いがされる場、住民の方たちの意見が聞ける場というのは必ず用意してほしいという要望をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"去年、私が電話でヒアリングしたときには、ＬＥＤの電球が幾ら、設置費用が幾ら、維持管理、撤去代が幾らということを伺っているのです。もっと具体的な内訳を書いてほしいと思います。","respondent":"鈴木文化観光課長","answer":"昨年度は事業を実施した後で、この４事業はこれから実施で、契約手続なり手配をしています。その辺は、今後、実施しまして、報告のときには詳細な内訳についてもご説明ができるようになるです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"シナモロールの切手について１点だけ伺いたいのですが、これは１,５００円で１,０００シートだから、１５０万円ではないですか。切手は１０枚だから８２万円ではないか尋ねました。","respondent":"鈴木文化観光課長","answer":"それから区の考え方としては、観光大使、協力してＰＲしていただくと区では考えております。これは、区がその事業の中でシナモロールを使ってもらってＰＲしていただくという考え方です。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"一応予算額がついているので、何となく大体幾らくらいというのはわかっていると思うので、次からはそこら辺までを書いてほしいと思います。なるべく情報はいっぱい欲しい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどのシナモロールの切手販売も、今回の体育の日の事業についても、報告事項ではなくてその他として扱う。それぞれしっかりやっていただきたいとは思うのですけれども、何だかなという思いが。","respondent":"本多委員長","answer":"最初から報告事項に上げられるような委員会運営に努めていきます。ほかになければ、以上でその他を終了いたします。","id":"exchange-024"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"現地でそのようなことは言いませんけれども、要するに安全のルール化、条件をどのように整理しているのか、その点について伺いたいと思います。具体的には、正副にお任せいたしますけれども、調整していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"渡辺委員","kind":"質問","question":"平日であったり、そのようなところをどのように取り組んでいるのかを細かく、世代や対象をどうやっているのか。当初の想定から、いざ実際やってみてが違うと思うので、そういうものが取材できたらいいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/824061?Template=document&Id=2792#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":38240,"voices":84}},{"id":"h29-20170926-7","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"厚生委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"南品川４丁目特別養護老人ホーム（法人立）の整備計画進捗状況","agenda":"南品川４丁目特別養護老人ホーム（法人立）の整備計画進捗状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、品川は、促進係数も１.５になっているということですけれども、そういうのも含めて、補助金が何床で幾らになるのかもの説明を求めました。","respondent":"大串福祉計画課長","answer":"先ほど最初の資料でもご説明しましたが、今も一宮市で特養を運営している法人です。メインになるのは、健康運動指導士を講師として行う体操教室を今のところは計画しております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"総事業費、総建設費というのでしょうか、それがわかったら教えてほしいと求めました。区がこの道路がないために買えないと言ってきたものが、法人だったらなぜこういうことができたのかについてもの説明を求めました。","respondent":"大串福祉計画課長","answer":"売却金額につきましては、申しわけありません、非公開ですので、私からはお答えしかねます。いわゆる西側のほうの前面の道路に接するところですが、幅としては６メートルです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"補助金として併設加算というのがつくと思うのですけれども、これ以外のところでは加算がつくようなものは併設されないのでしょうか。例えば、認知症対応のデイサービスだったりとか、そういうふうな併設加算がされるようなものがほかにはないのかだけ、確認をお願いします。","respondent":"大串福祉計画課長","answer":"今委員からありましたようなデイサービスとかそういった施設の併設は、今のところ考えていません、スペース的に少し厳しいといったところです。やはり９０床とるということで、そちらのベッドを確保することに法人のほうでも注力したところかと思います。","id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど道路の確保で法人の努力と言われていたのですけれども、区は努力できなくて買えなかったのかなというふうにも聞こえるので、そういうのは区が道路を確保することはできないのか、伺いたいと思います。","respondent":"大串福祉計画課長","answer":"金額、これに対してどういった活用ができるか、その中でどのような形で購入ができるかというところで区のほうとしては対応せざるを得ない。それを買う、あるいは活用するに当たっては、もうワンステップ、ツーステップあるということで、なかなか難しいところです。","id":"exchange-004"}]},{"id":"topic-02","title":"平成２８年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"６１ページなのですけれども、障害者グループホーム連絡会がつくられて年５回開催されたということなのです。区の職員もここにかかわっているのかについて、まずの説明を求めました。","respondent":"中山障害者福祉課長","answer":"これは知的・精神全ての区内グループホームの世話人に声をかけて実施しているものです。区の職員としましては、一応、係長を行かせています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そしてまた、ぜひ質の向上につなげていただけたらなと思いました。いろいろなところから社会福祉法人が入られて、すごく広がったと思うのですけれども、そういうところでの交流はあるのかの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"従来からの５法人につきましては、交流会というか、担当者会議、事業所会議みたいなものを継続してやっております。新しく入った法人につきましても、定例の事業所連絡会ということで加入していただいて、意見交換、情報交換を２カ月に１回開催しております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"されていないところがあったり、それから、認知症のデイサービスの利用率がこれだけ少ないことを区としてどう捉えているのか。今後どういう取り組みを考えられているのかもあわせてお聞かせいただけたらと思いますとの意見を述べました。","respondent":"寺嶋高齢者福祉課長","answer":"先ほども説明の中で触れたとおりですが、認知症デイの取り組みについての課題抽出ということで、実際に会議を持ちました。この辺を含めまして、第２回以降の認知症に関する検討会の中で掘り下げていければなと思っています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どういうことでこの額になっているのかという仕組みなのですけれども、要綱とかそういうのがあるのか、どういうふうにしてこの額が出てくるのか。そして、もし全くの民間だったら、これがないまま介護報酬だけでやるのか、その辺もの説明を求めました。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長","answer":"先ほども少し説明で触れたのですけれども、身体機能がある程度しっかりしている方は、認知症があっても要介護度があまり重く出ない傾向があります。私からは、障害者福祉施設の管理委託料の考え方についてご説明いたします。人数であったり、そういった幾つかの指標があるのですけれども、その指標をもとに民間に対して区を通じて１０分の１０の補助金が出てあります。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう基準で出ているのかということでは、要綱とかあるわけではないですか、その辺の仕組みを教えてほしいと求めました。そこのところでは、基本的に平成２７年と平成２８年は変わらないと考えるのか、職員の待遇の部分についてもの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"それと、報酬改定等も含めた法人とのヒアリングの中で、区のほうでも必要に応じて支援できるところはしていくということです。質の向上・人材確保につきましては、区のほうも各法人向けにさまざまな支援を行っているところですし、今後もそれは継続して行っていきます。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"幾ら委託料を出すよという協定になっているという意味でしょうか、その点、１点お願いします。その協定の中の委託料の計算の仕方が、何を基準にしてどういうふうに決まってくるのかを、わかる範囲で教えていただきたいのが１点です。","respondent":"寺嶋高齢者福祉課長","answer":"それから、それは各施設のほうできちんとした対応をして、各職員として給料として還元されるような対応をとっているところです。法人によっては１桁台のところもまだまだありますので、この辺はどういった取り組みをしているのかも、人材確保・定着に努めているところです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、離職率は、１４.８％になってしまった、２.７％も上がったというのは、区としてはどう捉えているでしょうか。そういう点で言えば、離職率が２.７％も上がってしまったことに対して区としてどう捉えているかをお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"その辺は当然認識を持った上でやっている、当然この仕事に働きがいを持ってやっていると言っております。例えば、送迎とか配食サービスの実施とか、そういった個別の事業について加算をして給付金額を決めていくといった内容です。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"資格のきちんとした人の配置に向けた支援も必要かと思うのですけれども、この介護福祉士の資格取得の支援は区としてはあるのか１点お聞かせください。それともう一つ、ショートステイの全体の需要は区としてはどうなってどう捉えられているかについての説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"２つ目のショートステイですけれども、緊急ショートなど、この場合の対応が１つ必要だということがあります。これは、デイとヘルプで対応ができているという数値なので、この数字が高い・低いについてはあまり問題ないという認識を持っております。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、先ほどの賃金にしても、２１万円台というのは、やはり１０万円くらい差があるという数字になると思うのです。そういうところもぜひ区のほうからも求めていただきたいということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"簡単に２点だけお聞きします。ここだけ特別に入所者の平均年齢が８９歳ということだったのですけれども、ここだけなのか、その辺の感覚をまず。","respondent":"寺嶋高齢者福祉課長","answer":"ご指摘のとおりここにしか書いていないのですけれども、ほかの施設については実際には上がっているという認識です。原因は分析していないのですけれども、ここの施設が結果的に下がったので、こういう記載があったと認識しております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それからもう一つだけ、５７ページ、品川児童学園です。肢体不自由児への対応や保育園等との併用利用というのが出てきて、昨日もたしか出ていたので、この辺もう一回の説明を求めました。","respondent":"中山障害者福祉課長","answer":"Ｃｏｍｐａｓｓは少し違うのですが、通園について言うと、ほかの幼稚園あるいは保育園に通っている方がご利用できない状況になっております。例えば週２日の療育を受けられる、そういう機会を確保していく必要がある、事業者とも共通の認識を持っているところです。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"福栄会がこういうコメントを出していること、グローが今後はやっていく、その辺の引き継ぎ関係は十分とれているのか。場所としても、あの場所ではできないですよね、その辺はどう考えているのかの説明を求めました。","respondent":"中山障害者福祉課長","answer":"昨年度１年間かけて、その引っ越しが終わった後の１年間は、福栄会とゆうゆうで引き継ぎの作業をこの間やってきました。平成３１年度に新しい施設に移ったときに速やかにそういったことができるよう、運営事業者とクラス編成の持ち方について話を進めているところです。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"１０ページですけれども、昨年度比で５００万円の光熱水費を削減したとあるのですが、職員の方々の負担はあったのかどうかを１つ教えていただきたい。","respondent":"寺嶋高齢者福祉課長","answer":"ランニングコストが５００万円、実際７,５００万円程度のものが７,０００万円ぐらいに下がったということを、改善点として上げたという内容です。したがって、大きな施設であればこのレベルの機械室はあると思いますけれども、施設規模によって違ってくると思います。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"２５ページで、すごく正直に書かれているなと思ったのですけれども、そういう状況もあるのかなと思うのです。先ほど、それ以上に区として人材確保の支援を進めていく体制、今後どうされていくのかというのを伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"経験のない職員の方を法人の経営方針にあわせて１から研修をしていくというやり方が効果的だと捉えている法人もいますので、全くの新しい方をとる。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"人材確保のための賃金アップを国に求めるとか、介護の改悪をストップさせるとか、そういった立場に立ってほしいと求めました。そうすると、児童発達支援ほぼそれの利用率になるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"すみません、ご説明が足りませんでした。児童発達支援のうち通園の部分の利用率になっております。","id":"exchange-019"}]},{"id":"topic-03","title":"平成３０年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）」の入居待機者の募集","agenda":"平成３０年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）」の入居待機者の募集","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その順位をつけるに当たって明確な点数になっているのかを教えていただきたいのですが、そういう点数表があって、高い順番から順位が決められるのか。","respondent":"松山高齢者地域支援課長","answer":"ただ、点数では判断できないご本人の生活状況等もありますので、そちらも加味しながら行っているものです。それから３点目、築年数あるいは壁などにかなり傷みがあるですとか、そういったものも考慮の対象になっております。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"補欠登録者は単身が２０人と２人用が１０組ということなのですけれども、ここのところでは１年間で何人ぐらい入れたのかの説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"それから２点目ですけれども、大井林町の入居人数ですけれども、平成２８年度は９名の方が入居されております。全額、要は上限まで助成を受けている方がどれくらいいるのかというご質問だと思いますが、ほとんどの方が対象になっているかと思います。","id":"exchange-021"}]},{"id":"topic-04","title":"後期高齢者医療制度保険料","agenda":"後期高齢者医療制度保険料","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その財政安定化基金というのは、東京都広域連合で幾らたまっているというのがわかったら教えてほしいと求めました。剰余金は８４億円、保険料抑制のために、平成２８・２９年度のときは使われたということで考えていいのでしょうか、それが１点です。","respondent":"三ッ橋国保医療年金課長","answer":"一方、剰余金に関しましては、現時点で見込むことは困難です。例えば、平成２７年の決算が終わらないと剰余金がはっきりしませんので、そちらに関しましては現時点では剰余金を見込むことが困難となっております。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１万３,６９２円という形ではなくて、平成２８・２９年度と均等割・所得割、それほど大きく変わらなくて済むと考えていいのか。一番初めのページの２つ目の保険料率算定時の設定条件というのがありますけれども、これがどういう中身なのかについての説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"やはり低所得者に対するもの等さまざまなものがありますので、特例対策は実施していくものと考えております。国の制度施行時の特例措置については、現在２０％ですが、今後、平成３０年度は廃止の見込みとなっております。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとも、国が０にするのだからと東京都までなくしてしまうとか、そういうところまで話し合われているのかどうかを１つお聞かせいただきたい。そういう軽減措置が平成３０年度から国のほうでなくなっていくと、東京都は一体どうするのか、その辺の見通しの説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"与えないよう現行制度を継続するようにということを、はっきりしたものが出ていないのですけれども、国に対してはそのように言っているところです。その部分がまだ実際公表されておらず、取りまとめ中ですので、またわかり次第お伝えできる段階でお伝えしていきたいと思います。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もっとですかね、７５歳以上ですから、継続できるようにお願いしたいと思います。それはぜひ要望いたします。","respondent":"三ッ橋国保医療年金課長","answer":"次に短期証ですが、短期証の方は、平成２９年８月１日現在で６０名になっております。滞納者数は平成２９年５月末現在で１,２０５名となっております。","id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"そういう中で、均等割の上がりが２００円と。それぐらいに今回もなっていくのか、そういうのは今の時点ではわかりますかとの意見を述べました。","respondent":"三ッ橋国保医療年金課長","answer":"この１人当たりの平均保険料率につきましては、増加する要因と減少する要因、剰余金とこの基金以外にもさまざまな要因があります。したがいまして、今の段階では広域連合が算定できておりませんので、またわかり次第お伝えする予定です。","id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私も上がってほしくないという思いで、幾らかなということで質問してしまいました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"地下１階と言いながら地面から入れるところなのか、その辺のところがわからないのですけれども、なぜ地下１階なのか。もう一つは、今まで使われていた上大崎１－３－１２そのものもどんな状況なのかよくわからないのですけれども、その点についての説明を求めました。","respondent":"寺嶋高齢者福祉課長、松山高齢者地域支援課長","answer":"１つは、再開発事業の中で公共公益施設の設置というものがありますので、在宅介護支援センターほか公共公益施設が入るということで。この在宅介護支援センターの移転の後なのですけれども、今、上大崎シルバーセンター１階の洋室に在宅介護支援センターが入っている状態なのです。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"補助金もたしか税金投入が１００億円を超えたと思うのですけれども、そんな中で何で地下１階しか出さないのかという思いがするのです。本当に地上からそのまま入れるようなところへ要求はできなかったのか、その思いだけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"現在の在支から目黒駅前の開発ということで、利便性とか、面積も大変広々となって、在支の役割を十分に果たしていただけるものだと期待しております。利用者のお声はどういうふうに聞かれて、相談しながら進めることになるのでしょうか、そこの確認だけ。","respondent":"松山高齢者地域支援課長","answer":"３月１日に受け付けを開始しまして、一般の方々向けには３月１０日から受け付け開始を考えています。ですので、そのスケジュールで逆算しまして、町会と近隣の方々にはご説明をしようと考えています。","id":"exchange-030"},{"speaker":"若林委員","kind":"確認","question":"今の２０平米の部屋を内装をして、しつらえて、そこはまた地域の方の交流の場に使っていただけるということで部屋について、どういう仕様、使い勝手のよさにするかという、地域の方の町会等の声は聞いて何か反映させる方向性があるのかどうかだけ確認します。","respondent":"松山高齢者地域支援課長","answer":"今の部屋はかなり手狭で、部屋自体の工夫、間にパーテーションを入れるとかそういった部屋ではなく、２０平米ほどです。机・椅子は用意して、空調などもきちんと整備した上で、使い勝手のいいような形では考えたいと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"手狭で引っ越すということなのですけれども、今度のところの広さだけの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"新しく移転する先の在宅介護支援センターの床面積は、現在の資料では１４８.０５平米となっています。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/999880?Template=document&Id=3488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":65913,"voices":110}},{"id":"h29-20170926-8","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"建設委員会","time":"午前１０時００分～午後 ３時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"目黒駅前地区第一種市街地再開発事業の施設建築物竣工","agenda":"目黒駅前地区第一種市街地再開発事業の施設建築物竣工","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと確認したいと思います。ちょっと具体的に教えていただきたいのと、緊急時の二方向避難というのはどんなふうになっていらっしゃるのかの説明を求めました。","respondent":"稲田都市開発課長","answer":"次に、住居数をお知らせいたしますと、全部で９４０戸の予定です。１Ｋが１００戸、１ＬＤＫが２４０戸、２ＬＤＫが３００戸、３ＬＤＫが３００戸というような予定で現在やっているです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"組合からの提案があって、というのをちょっとお伺いしたいのと、伺ったのは１２０名の定員だということですけれども。都市開発課としての見込みをお伺いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"１２０名となったのは、保育課の判断なのですか。ほかのところから引っ張ってくるというのは、そのあたり都市開発課としての判断はどうだったのかなというのもお伺いしたいというのが２つ目です。","respondent":"稲田都市開発課長","answer":"在宅介護のほう、保育もそうなのですけれども、所管と協議をしながらこのような形でやってきたです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"所管とどんな協議をしているのかというのをお伺いしているのですけれど。まちづくりなわけですから、最終的には……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それは今回幾らで、それは同様に、この公共施設との関係は何かあるのかというのを、２点目、お伺いしたいと。それをお伺いしたい。","respondent":"稲田都市開発課長","answer":"これとは別に都市計画道路補助の１５９号線を整備するこの開発の中で、都市計画道路を整備するということで、これは別途出ているものです。区の権利床ということです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと聞いたのでお伺いしたいなと思いますのと、これは今回の公益施設ということもあるから、そこに対応して幾らというわけではないのかどうかと。そこはちょっとはっきりしなかったので、お伺いしたいなと思います。","respondent":"稲田都市開発課長","answer":"公共施設管理者負担金の、区としてこの組合に充てている補助金の総額が、９億９,８２１万７,０００円、約１０億円です。地域貢献施設ではこういうものをつくっていきましょうというところでやってきたものですから、補助金は関係しているというものではございません。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"１点だけ、確認します。この地域のここの場所の駐輪対策、自転車の対策がどうなっているのかというところを確認したいと思います。","respondent":"稲田都市開発課長","answer":"この開発の中で、一般の方、ここに住んでいる方以外が使える駐輪場の台数が２１５台あります。その中で、保育施設に１０台、在宅介護施設に１０台ほど割当てがあるということで進めております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"では、これは保育施設のところに１０台とかではなくて、決まった場所に。駐輪場がどこの位置になるのか尋ねました。","respondent":"稲田都市開発課長","answer":"表記がないのですが、資料の右上のこの平面図を見ていただきますと、区画道路２号というのが、左上のほうに書いてあります。その下のＡ棟１階平面図というものがありますが、この１階の部分で、これが駐輪場です。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺の融通策があるのでしょうかというのが１点です。災害時にいろいろな地域の方々が利用される部分もあるのだろうなと思うのですが、備蓄についてはどう考えたらいいのか尋ねました。","respondent":"稲田都市開発課長","answer":"再開発組合等々と協議をして、ではこれぐらい、あれぐらい。では、これでいこうかというようなことで決まっていくという状況です。","id":"exchange-009"}]},{"id":"topic-02","title":"平成２９年度ウォームビズキャンペーンの実施","agenda":"平成２９年度ウォームビズキャンペーンの実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"室温１９度ということを目途にということなのですけれども、部屋によっても違うと思うのですけれども、そのためには大体エアコンは何度ぐらいの目安になるのかと、どのように呼びかけをするのでしょうかということをお伺いします。","respondent":"小林環境課長","answer":"ただ、その設定する、感知する場所によって１９度が適切かどうかというような判断は多少変わってくるかというふうに思っております。部屋の中にある温度計を見ながら、１９度に細かく調整していくということが必要なのかなというふうに思っているところです。","id":"exchange-010"}]},{"id":"topic-03","title":"シェアサイクル事業の開始","agenda":"シェアサイクル事業の開始","exchanges":[{"speaker":"横山委員","kind":"質問","question":"２点目なのですけれども、こちらの区内のモデル周遊コースのようなものは想定されているのでしょうか。それを例えばパンフレットですとかホームページ等で周知・告知していったりするということなど、何かお考えがありましたらの説明を求めました。","respondent":"今井土木管理課長","answer":"そういうことを検討していく内容です。今後、自転車を活用した検討を進めていきたいというお声もありますので、一緒に検討を進めていく内容だというふうに考えております。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"先行自治体との比較ですとか、そういったところも、うまく広域化とともに進めてほしいと求めました。こちらも、うまく周知のほうを連携して進めていただきたいということで、ご要望だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"持ち運びしていくのですかという形をどう考えられているのですかということ。何となく観光と絡めてと言っておりましたけれど、もう少し分析等々が必要ではないかなと思うのですが、いかがか尋ねました。","respondent":"今井土木管理課長","answer":"ただし、今、東京都環境局の補助金がありますので、このうち２分の１は都の補助金で進める予定です。それから４点目の設置ポートですけれども、デメリットもご説明できませんので、検討してまいります。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"１点目のコストの件ですが、これはドコモのほうでもうけがなかった場合、品川区は補助するということはあり得るのでしょうか。これから開発するにせよ、予測を立てながらやっていく必要があるのかなと思うのですが、その辺の考え方はいかがか尋ねました。","respondent":"今井土木管理課長","answer":"次にポートの設置場所ですけれども、今、自区内の検証は今年度で終わらせようと思っています。これは広域連携をして、どのような場所に設置していくのがいいかというのも、ほかの連携している区やそして東京都とも確認しながら進めてまいります。","id":"exchange-014"},{"speaker":"西本委員","kind":"確認","question":"再度、確認です。１点目だけ、お願いします。","respondent":"今井土木管理課長","answer":"現在の時点では、広域先行自治体も含めて、運営費というのは、なかなか補助というのは難しいという状況です。中国なども含めてありますので、まずは社会実験という形で進めながら、状況に応じて対応していくものだというふうに考えております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"確認","question":"どれくらいの自治体で実施実績があるのかお伺いしたいのと、あと料金設定ですけれど、これは消費税別ということですかねという確認と。お伺いしたいと思います。","respondent":"今井土木管理課長","answer":"２３区以外でも横浜市など既に進めているところですが、先ほど申しました都心６区に加えて、大田が導入いたします。私どもも種々検討いたしましたけれども、今後広域連携していくという中では、私どもの判断で先行自治体と同じ料金ということで決定いたしました。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"実施規模ということで１８箇所ということでありますけれど、それともさらに１８箇所から順次拡大していくというふうなのか、お伺いしたいと思います。","respondent":"今井土木管理課長","answer":"それから、もう一つ充電ですが、充電のほうも、再配置とともに業者であるドコモ・バイクシェアのほうが充電というのも行います。フル充電したときには、区内の今の面積を考えますと、一定の期間は十分ご利用いただけるというふうに考えております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"そうですか。区としては、どの辺を一番ターゲットに考えているのかと、そこら辺をお伺いしたいのですけれど。","respondent":"今井土木管理課長","answer":"ポートを置ける場所、または置いていただける民間企業等にお声をかけまして、ビジネスユースも考えていく範囲には入っております。日常利用につきましては、まずは日常というのは、今後ポートを増やしていった中で活用されていくものだというふうに考えております。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"利用料金の中の１日パス１,５００円で、これはこの専用のカードの発行ということでの５００円なのか、ちょっと確認をしたいと思います。","respondent":"今井土木管理課長","answer":"実は他区ではもう既に実施されているのですが、利便性を高めるために有人窓口で購入する場合の発行手数料が５００円かかるという形になっております。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"自転車のデザインや形というのは、この写真のとおりなのでしょうか。広域ということで、それは全て統一ですということで、よろしいのか尋ねました。","respondent":"今井土木管理課長","answer":"ご質問いただきましたとおり、ドコモのシェアサイクルは全てこの赤い自転車です。２９年度は自区内運用ですので、平成２９年度は、品川区で運用していますということがわかるようにしてまいります。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"では、形はこれということで、多い荷物を運ぶにはちょっとかごが少ないのかなという。最終的にはこのドコモ・バイクシェアがお考えになることかもしれませんけれども、その点、ご見解はいかがか尋ねました。","respondent":"今井土木管理課長","answer":"かごも、もしかしたらもう少しいいものになるかもしれませんが、現状ではこういうふうな形で進めていくものです。ほかの広域連携になりますと、３０年度以降の自転車のときには、看板のような形で運用されていくものと考えております。","id":"exchange-021"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"何点かお伺いしたいのですけれど、品川区としては財産になるものなのですかということが一点と、しながわ」と書いてあるわけですよね。","respondent":"今井土木管理課長","answer":"私の説明に不備があったと思いますけれども、こちらのほうはドコモが購入することに対して、品川区が補助するという形になります。見えるところにつくような形での使用を検討しているとは聞いておりますので、あくまで広域連携の中で活かしながら取り組んでまいりたいと思います。","id":"exchange-022"},{"speaker":"いながわ副委員長","kind":"意見","question":"この赤いドコモのシェアサイクルはそのままにしておいてくださいなのか、それとも乗る前にしっかり注意をするのかどうなのかとか、その辺というのは何か対策というのは考えられているのかなという１点だけの説明を求めました。","respondent":"今井土木管理課長","answer":"もちろん放置自転車禁止区域にとめているものは、これは撤去の対象になります。可能性としてはほかの自治体で行われておりますので、それも含めての運営というふうに考えているところです。","id":"exchange-023"}]},{"id":"topic-04","title":"交通安全宣言５０周年記念「しながわ交通安全フェア」の開催","agenda":"交通安全宣言５０周年記念「しながわ交通安全フェア」の開催","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"やはりいざ事故が起きてしまった場合などは大事だと思うので、そういった周知といったこともぜひこの中にあるといいなと思うのですけれども、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"自転車シミュレーターといったものも実際現場のほうに置きまして、こういったところを実際に乗ってもらって、自転車の安全性を確認してもらう。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"加入できますよということで、周知できるようなブースなどを工夫できれば、ぜひお願いしたいというふうに思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-05","title":"本日は防災対策に関することのうち、地域防災計画の改訂","agenda":"本日は防災対策に関することのうち、地域防災計画の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、やはりそういったところも大きく章立てをしてつくっていっていただきたいのですけれども、いかがでしょうかというのが１つです。コンビナートの火災ですとか、区内で起こり得る被害想定というものをどこまでされているのか、そこら辺についてはどうか尋ねました。","respondent":"古巻防災課長","answer":"検討経過のところで記載させていただいている中で、備蓄の関係で、そういったあたりはまずは予防対策になるのかなというふうに思います。コンビナート関係の事故に関しましては、こちらの中で想定をして、計画の中に反映していくというふうに考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは当然新ルート計画を今国が進めている状況で、この航空機の大規模事故というのは一体何を指しているのか、ご確認したいというのが一つあります。それから質問のもう一つは、区としては何か改善していくという計画やお考えはあるのかないのか、お伺いしたいと思います。","respondent":"古巻防災課長","answer":"対策を記述するですので、そちらの羽田関係の状況とは切り離して考えていきたいということで、ご理解いただければというふうに思います。区としても耐震助成などを進めているですので、そのあたりは十分対策を考えて区としても進めているというふうに認識しております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"今落下という話もありましたが、この航空機の大規模の事故というのは墜落事故が含まれているということでよろしいのかどうかをお伺いします。そのように修正していく必要があるのではないかと思うのですが、いかがか尋ねました。","respondent":"鈴木建築課長、古巻防災課長","answer":"やはりこの平成１２年を境にしたところでも数棟被害が出たというところで、この建物の耐震性能をチェックできるチェックシートが公表されております。そういった構成にかかわる部分につきましては説明がちょっと薄い部分があるかとも思いますけれども、そのような形でご理解をいただければと思います。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと現実的ではないのではないかという思いもありますので、そこら辺はちょっと私もさらに研究して要望もさせてほしいと求めました。","respondent":"古巻防災課長","answer":"区内で墜落事故がというのはちょっと考えづらい部分もありますけれども、墜落をするということも当然可能性としてはあり得るというふうには思います。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"町会の人がやるのですか。２－３で男女共同参画の方々に意見を伺いということなのですが、情報収集されているところもあるので、それらはまとめられているのか尋ねました。","respondent":"古巻防災課長","answer":"多様化する避難というところでの、避難所における発災時初期の対応が重要であるというようなお話でございましたけれども。ですので、今現在行っております個別計画の作成の支援の中で、さまざまな資料をつくってご説明をしていきたいというふうに考えているところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"これに入れ込めるのかどうかわかりませんが、現状を踏まえながら、実際必要なことをまず見直しを図っていただきたいと考えています。なので、この初期の体制を何とか研究を進めていただきたいと思うのですが、最後にお聞きしたいと思います。","respondent":"古巻防災課長","answer":"やはり非常に必要なことであるというふうには認識しておりますので、基本的な考え方については、さらにそういった部分をきちんと職員間においても認識が進むような形で進めていきたいというふうに思います。","id":"exchange-031"},{"speaker":"新妻委員","kind":"質問・要望","question":"促進をしていただきますが、促進ができているのかどうかというのは、区はどうやって確認をしていただくのでしょうか。そこをお聞かせほしいと求めました。","respondent":"古巻防災課長","answer":"区は認識をしていますので、まずマニュアルに関しましては、計画の中に項目でありますとか考え方を明らかにしていきたいと思います。避難所連絡会議の中で、現在マニュアルの作成の状況がどうなのかとか、そちらの中で防災課のほうで把握していきたいというふうに考えております。","id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"水と備蓄とトイレがあれば生き延びていかれるわけですから、このトイレの確保というところもしっかりと周知をしてほしいと求めました。","respondent":"古巻防災課長","answer":"ペットの訓練については進めていきたいというふうに思っておりますので、そういった訓練が進むようにしていきたいと思います。そういった中で、ご家庭でのこういった備蓄の考え方でありますとか、十分提案できるような修正をしていきたいというふうに考えております。","id":"exchange-033"},{"speaker":"大沢委員","kind":"質問・要望","question":"表記のことで伺いたいところなのですが、２－３とありますが、２－１の１番目の「『受援計画』を地域防災計画に追加する」。２－３で「意見を伺い、計画へ反映する」というのですけれども、この計画なるものはどのようなものか。","respondent":"古巻防災課長","answer":"検討結果の２－３の「意見を伺い、計画へ反映する」の「計画」につきましては地域防災計画のことです。特に意図があって計画というふうに縮めたものではありませんけれども。","id":"exchange-034"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"確認というか、どういうイメージかだけ教えていただきたいのですけれども、１－３、黒丸「円滑な災害対応に向けた災害対策本部の再編を進める」。それはこれから議論されるのかもしれないですけれども、今の現段階でのイメージの説明を求めました。","respondent":"古巻防災課長","answer":"ちょっと説明がうまくいっていなかったでしょうか。","id":"exchange-035"},{"speaker":"いながわ副委員長","kind":"質問","question":"何か多少リンクして、立ち上がったときには災対本部とこの復興本部の人というのは、兼務することになるということでいいのですか。要は、密にするというのは、当事者がやっているわけですから、密も何も、何かぴんとこなかったので質問させていただいたので。","respondent":"古巻防災課長","answer":"体制としては若干オーバーラップする部分もあると思うのですけれども、業務としては少し切り分けて考えていただいたほうがいいかなと考えています。ただ、中でそういった形で記述をしていこうというふうに考えております。","id":"exchange-036"},{"speaker":"いながわ副委員長","kind":"質問","question":"それを加える、推進するために設置すると書いてあるということは、要は今はないわけではないですか。まちの復興ですから、これは危険な建物ですよと貼ったりする業務は、ここの本部を中心として指令が出てやるというイメージでいいのか尋ねました。","respondent":"古巻防災課長","answer":"震災復興本部の設置についても現行の計画の中できちんと記載があるものですので、忘れないようにきちんとここで連携について記載すると。","id":"exchange-037"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"その人たちの役割というのは何なのですかというのは、恐らく書いてあるのですけれど、あまり明確になっていない。その人たちの役割というのは何なのですかといったときに、わかりやすい計画にしていただきたいなと思いますが、いかがでしょう。","respondent":"古巻防災課長、曽田災害対策担当部長","answer":"わかりやすい計画にということは当然意識しておりますので、震災復興マニュアルにつきましても、今後改訂をしていくというような形になろうかと思いますので、中できちんと明確にしていくということを意識してまいりたいと思います。復興本部というのは、将来に向けた防災に強いまちづくりをしていくということで、もう数年単位の事業になろうかということになります。","id":"exchange-038"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"やはり自転車をどう位置づけるかという計画、そこら辺についても、調査をぜひ深めていかれたらなという思いがあります。防災まちづくり、やはりふだんからの防災コミュニティというのですか、ある程度の時間はしっかり確保していただけるとありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問","question":"中越市民防災安全士会がありまして、これは事業として市がお金を出しているのだと思いますけれども、ここら辺の取組みを少しお伺いしたいと思います。長岡市の資料の後ろのほうです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"新妻委員","kind":"確認","question":"火事があったときには危険だという認識があった中で、なかなかそこが進められなかった現状といいますか、そこを確認したいなと思います。それと、自転車レーンの整備、自転車の走行にあたっての道路整備がどのくらい進んでいるのかというのをちょっと確認したいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594236?Template=document&Id=4214#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":56952,"voices":148}}]);
